import { writeFileSync } from 'node:fs';
const base = 'http://127.0.0.1:9222';
const target = (await (await fetch(base + '/json/list')).json()).find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); }
  else if (m.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text));
  else if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') logs.push('console.error ' + m.params.args.map(a => a.value ?? a.description).join(' '));
};
const send = (method, params = {}) => new Promise((resolve, reject) => { const mid = ++id; pending.set(mid, { resolve, reject }); ws.send(JSON.stringify({ id: mid, method, params })); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result?.value; };
const click = async (x, y) => { await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 }); await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 }); };
const clickSel = async sel => { const pt = await ev(`(() => { const r=document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`); await click(pt.x, pt.y); };
const shot = async p => { const r = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(p, Buffer.from(r.data, 'base64')); };

await send('Runtime.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await send('Page.navigate', { url: 'http://localhost:3002/' });
await sleep(3200);
await ev(`localStorage.setItem('cryout-best-v2', JSON.stringify({ cryout:{score:986700,acc:100,rank:'S+',maxCombo:328,full:true}, world:{score:1234567,acc:97.4,rank:'S',maxCombo:410,full:false} }))`);
await send('Page.reload'); await sleep(3600);
console.log('PB BADGES', await ev(`[...document.querySelectorAll('.track-card')].map(c=>({id:c.dataset.track,pb:c.querySelector('.tc-best').textContent,pbTitle:c.querySelector('.tc-best').title}))`));
console.log('PB LINE', await ev(`document.getElementById('bestLine').textContent`));
await clickSel('.track-card[data-track="cryout"]'); await sleep(2600);
await clickSel('#startBtn'); await sleep(2200);
await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 20, y: 800, radiusX: 8, radiusY: 8, id: 1 }] });
await ev(`(() => {
  const c = window.__cryout;
  const notes = [...c.chart.notes].sort((a, b) => a.t - b.t);
  for (const n of notes) { c.audio.startAt = c.audio.ctx.currentTime - n.t - 0.004; c.pressLane(n.lane); }
  c.audio.startAt = c.audio.ctx.currentTime - (c.chart.song.chartEnd + 0.05);
})()`);
for (let i = 0; i < 80; i++) { if ((await ev(`document.getElementById('resultLoading').classList.contains('show')`))) break; await sleep(60); }
await sleep(1000);
console.log('MOBILE LOADING LAYOUT', await ev(`(() => { const el=document.querySelector('#resultLoading .compile'); const r=el.getBoundingClientRect(); return {box:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)], view:[innerWidth,innerHeight], centered: Math.abs((r.top + r.bottom)/2 - innerHeight/2) < 40}; })()`));
await shot('/tmp/opencode/fix-mobile-loading.png');
for (let i = 0; i < 100; i++) { if ((await ev(`document.getElementById('resultScreen').classList.contains('show')`))) break; await sleep(80); }
await sleep(1300);
await shot('/tmp/opencode/fix-mobile-results.png');
console.log('RESULT', await ev(`({state:window.__cryout.state, rank:document.getElementById('rank').textContent, best:document.getElementById('bestNote').textContent, delta:document.getElementById('scoreDelta').textContent, acc:document.getElementById('finalAcc').textContent})`));
await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
console.log('LOGS', logs);
ws.close();

