cd /tmp/opencode && cat > durations.mjs <<'EOF'
const base='http://127.0.0.1:9222';
const target=await (async()=>{const l=await (await fetch(base+'/json/list')).json();return l.find(t=>t.type==='page');})();
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
let id=0;const p=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&p.has(m.id)){const q=p.get(m.id);p.delete(m.id);m.error?q.reject(new Error(JSON.stringify(m.error))):q.resolve(m.result)}};
const send=(method,params={})=>new Promise((res,rej)=>{const mid=++id;p.set(mid,{resolve:res,reject:rej});ws.send(JSON.stringify({id:mid,method,params}))});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const ev=async x=>{const r=await send('Runtime.evaluate',{expression:x,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value};
await send('Runtime.enable');await send('Page.enable');
await send('Page.navigate',{url:'http://localhost:3002/'});await sleep(3000);
console.log(await ev(`(async()=>{
  const out={};
  for (const [name,url] of [['cryout','./audio/cryout.mp3'],['world','./audio/world-yearning.mp3'],['chrono','./audio/chronostasis.mp3']]) {
    const buf=await (await fetch(url)).arrayBuffer();
    const ctx=new (window.AudioContext||window.webkitAudioContext)();
    const dec=await ctx.decodeAudioData(buf.slice(0));
    out[name]=+dec.duration.toFixed(3);
    ctx.close();
  }
  return out;
})()`));
ws.close();
EOF
