const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
let id=0;const p=new Map();const logs=[];
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&p.has(m.id)){const q=p.get(m.id);p.delete(m.id);m.error?q.reject(new Error(JSON.stringify(m.error))):q.resolve(m.result)}else if(m.method==='Runtime.exceptionThrown')logs.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)};
const send=(method,params={})=>new Promise((res,rej)=>{const mid=++id;p.set(mid,{resolve:res,reject:rej});ws.send(JSON.stringify({id:mid,method,params}))});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const ev=async x=>{const r=await send('Runtime.evaluate',{expression:x,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value};
const click=async(x,y)=>{await send('Input.dispatchMouseEvent',{type:'mousePressed',x,y,button:'left',clickCount:1});await send('Input.dispatchMouseEvent',{type:'mouseReleased',x,y,button:'left',clickCount:1});};
const clickSel=async sel=>{const pt=await ev(`(() => { const el=document.querySelector(${JSON.stringify(sel)}); el.scrollIntoView({block:'center'}); const r=el.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);await sleep(200);await click(pt.x,pt.y);};
const shot=async pb=>{const r=await send('Page.captureScreenshot',{format:'png'});writeFileSync(pb,Buffer.from(r.data,'base64'));};
await send('Runtime.enable');await send('Page.enable');
for (const [w,h,mobile,tag] of [[1280,800,false,'desktop'],[390,844,true,'portrait'],[844,390,true,'landscape']]) {
  await send('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:1,mobile});
  await send('Emulation.setTouchEmulationEnabled',{enabled:mobile,maxTouchPoints:5});
  await send('Page.navigate',{url:'http://localhost:3002/'});await sleep(3000);
  for (let i=0;i<40;i++){ if (await ev(`!document.getElementById('startBtn').disabled`)) break; await sleep(250); }
  const menu=await ev(`(()=>{const s=document.getElementById('startScreen');const b=document.getElementById('startBtn').getBoundingClientRect();const cards=[...document.querySelectorAll('.track-card')].map(c=>{const r=c.getBoundingClientRect();return[r.x|0,r.y|0,r.width|0,r.height|0]});return{scroll:s.scrollTop,sh:s.scrollHeight,ch:s.clientHeight,btn:[b.x|0,b.y|0,b.width|0,b.height|0],cards,bodyScroll:document.documentElement.scrollTop,pendline:document.querySelector('.pendline').textContent.trim()}})()`);
  console.log(tag,'menu',menu);
  await shot('/tmp/opencode/menu-'+tag+'.png');
  await clickSel('.track-card[data-track="chronostasis"]');await sleep(2000);
  await clickSel('#startBtn');await sleep(1600);
  await ev(`(()=>{const c=window.__cryout;c.audio.startAt=c.audio.ctx.currentTime-28.5;})()`);
  await sleep(1800);
  console.log(tag,'play',await ev(`({state:window.__cryout.state,sec:document.getElementById('sectionName').textContent,keys:document.getElementById('keys').textContent,t:+window.__cryout.audio.time.toFixed(1)})`));
  await shot('/tmp/opencode/play-'+tag+'.png');
}
console.log('LOGS',logs);
ws.close();
EOF
