}

// ---------------------------------------------------------------- input
function keyDown(e) {
  if (e.code === 'Escape') {
    if (gameState === 'playing') { e.preventDefault(); pauseGame(); }
    else if (gameState === 'paused') { e.preventDefault(); resumeGame(); }
    return;
  }
  if (e.code === 'Space') {
    if (gameState === 'playing' && swingMode) {
      e.preventDefault();
      if (!e.repeat) swingTap();
    }
    return;
  }
  if (e.repeat) return;
  const lane = KEYMAP[e.code];
  if (lane === undefined) return;
  e.preventDefault();
  if (gameState !== 'playing') return;

  if (gameState !== 'playing') return;
  if (held[lane]) return;
  held[lane] = true;
  dom.pads[lane].classList.add('pressed');
  pressLane(lane);
}

function keyUp(e) {
  const lane = KEYMAP[e.code];
  if (lane === undefined) return;
  if (!held[lane]) return;
  held[lane] = false;
  dom.pads[lane].classList.remove('pressed');
  releaseLane(lane);
}

