import fs from 'node:fs';
const d=JSON.parse(fs.readFileSync('boss2.json','utf8'));
const peaks=d.peaks;
function fit(t0,t1,step0){
  let step=step0, phase=0;
  for(let it=0;it<8;it++){
    const pts=[];
    for(const p of peaks){ if(p.t<t0||p.t>=t1)continue; const n=Math.round((p.t-phase)/step); const res=p.t-(phase+n*step); if(Math.abs(res)<step*0.38) pts.push({t:p.t,n,w:Math.min(3,p.strength)}); }
    // weighted linear regression t = phase + n*step
    let sw=0,sn=0,st=0,snn=0,snt=0;
    for(const q of pts){sw+=q.w;sn+=q.w*q.n;st+=q.w*q.t;snn+=q.w*q.n*q.n;snt+=q.w*q.n*q.t;}
    const denom=sw*snn-sn*sn; if(!denom)break;
    step=(sw*snt-sn*st)/denom; phase=(st-step*sn)/sw;
