827:     p.style.left = g.x.toFixed(1) + 'px';
828:     p.style.top = bottom.toFixed(1) + 'px';
829:     p.style.width = width.toFixed(1) + 'px';
830:     p.style.height = height.toFixed(1) + 'px';
831:     p.style.transform = transform;
832:     const live = active.has(i);
