import fs from 'node:fs';
const peaks=JSON.parse(fs.readFileSync('boss2.json','utf8')).peaks;
function score(t0,t1,bpm,phase,stepDiv=2){
  const step=60/bpm/stepDiv;let s=0,n=0;
  for(const p of peaks){if(p.t<t0||p.t>=t1)continue;const k=(p.t-phase)/step;const r=Math.abs(k-Math.round(k))*step;if(r<step*0.35){s+=Math.min(3,p.strength)*(1-r/(step*0.35));n++;}}
  return {s,n,density:n/(t1-t0)};
}
function best(t0,t1,lo=88,hi=100,div=2){
  let out=null;
  for(let bpm=lo;bpm<=hi;bpm+=0.1){
    const period=60/bpm/div;
    for(let ph=0;ph<period;ph+=0.005){
      const r=score(t0,t1,bpm,ph,div);
      if(!out||r.s>out.s)out={...r,bpm,phase:ph,div};
    }
  }
  return out;
}
