/* ---------------- pendulum centre tap (CHRONOSTASIS STASIS) ---------------- */
#centerPad{
  position:fixed;left:50%;top:52%;width:190px;height:190px;z-index:6;
  transform:translate(-50%,-50%) scale(.82);
  display:grid;place-items:center;
  padding:0;border:1px solid rgba(255,209,102,.5);border-radius:50%;
  background:radial-gradient(circle, rgba(255,209,102,.16), rgba(255,209,102,.05) 58%, transparent 72%);
  box-shadow:0 0 46px rgba(255,209,102,.22), inset 0 0 34px rgba(255,209,102,.1);
  opacity:0;visibility:hidden;pointer-events:none;
  transition:opacity .22s ease, transform .22s ease, visibility .22s;
  touch-action:none;overflow:visible;
}
#centerPad.show{
  opacity:1;visibility:visible;pointer-events:auto;
  transform:translate(-50%,-50%) scale(1);
}
#centerPad.pressed{
  transform:translate(-50%,-50%) scale(.92);
  background:radial-gradient(circle, rgba(255,209,102,.36), rgba(255,209,102,.1) 58%, transparent 72%);
  box-shadow:0 0 70px rgba(255,209,102,.42), inset 0 0 44px rgba(255,209,102,.2);
}
.cp-ring{
  position:absolute;inset:12%;border:1px dashed rgba(255,226,154,.4);border-radius:50%;
  animation:cp-spin 9s linear infinite;
}
.cp-label{
  font-family:var(--mono);font-size:10px;letter-spacing:.28em;color:#fff6dc;
  padding:5px 11px 4px;border-radius:999px;pointer-events:none;
  background:rgba(6,9,20,.62);border:1px solid rgba(255,209,102,.34);
  box-shadow:0 0 18px rgba(255,209,102,.28),inset 0 0 10px rgba(255,209,102,.12);
  text-shadow:0 0 12px rgba(255,209,102,1),0 0 3px rgba(255,240,200,.9);
}
@keyframes cp-spin{to{transform:rotate(360deg)}}
body.pendulum .pad{opacity:.2}
body.pendulum .pad.pressed{opacity:.32}
/* Keep hit feedback clear of the centre target while the pendulum runs. */
body.pendulum #judge{color:#ffe6a3;top:33%}

