    let pi = (slot + Math.floor(slot / barSlots) * 2) % pattern.length;
    let pos = pattern[pi];
    let lane = active[pos];
    if (lane === lastLane && t - lastT < Math.max(0.16, step * 1.2)) {
      pos = pattern[(pi + 1) % pattern.length];
      lane = active[pos];
      if (lane === lastLane && t - lastT < 0.14) continue;
    }

