805: function alignPads(ahead = new Set()) {
806:   // Long touch strips follow the projected lane direction. Tapping anywhere
807:   // along the lane hits that lane, and a lane with an incoming note is made
808:   // live before its section actually starts.
809:   const active = new Set(currentSection ? activeLanesFor(currentSection.keys) : []);
810:   for (const lane of ahead) active.add(lane);
811:   for (let i = 0; i < 8; i++) {
812:     const g = scene.laneScreenGeometry(i);
813:     const left = i > 0 ? g.x - scene.laneScreenGeometry(i - 1).x : g.x - scene.laneScreenGeometry(1).x;
814:     const right = i < 7 ? scene.laneScreenGeometry(i + 1).x - g.x : g.x - scene.laneScreenGeometry(6).x;
815:     // Fill the whole gap between neighbouring lanes. The strip boundaries meet
816:     // (and slightly overlap) at the midpoint, so a thumb landing between two
817:     // lanes still hits one of them instead of an invisible dead zone.
818:     const gap = Math.max(26, (Math.abs(left) + Math.abs(right)) * 0.5);
819:     const width = Math.max(48, Math.min(240, gap * 1.1));
820:     // The strip is anchored at the hit circle and runs straight up the lane;
821:     // a small tail below the ring gives thumbs somewhere to land naturally.
822:     const bottom = g.y + 26;
823:     const top = Math.max(6, Math.min(bottom - 110, g.topY));
824:     const height = Math.max(110, bottom - top);
825:     const p = dom.pads[i];
826:     const transform = `translate(-50%,-100%) rotate(${g.angle.toFixed(4)}rad)`;
827:     p.style.left = g.x.toFixed(1) + 'px';
828:     p.style.top = bottom.toFixed(1) + 'px';
829:     p.style.width = width.toFixed(1) + 'px';
830:     p.style.height = height.toFixed(1) + 'px';
831:     p.style.transform = transform;
832:     const live = active.has(i);
833:     if (p.classList.contains('sleep') === live) p.classList.toggle('sleep', !live);
834:     p.setAttribute('aria-hidden', String(!live));
835:   }
836:   alignCenterPad();
837: }
