content.text:
/* ============================================================
   CRYOUT — dynamic 3D rhythm
   ============================================================ */
:root{
  --bg:#04040c;
  --ink:#eaf6ff;
  --muted:#8393ab;
  --cyan:#5ee7ff;
  --magenta:#ff5fd2;
  --violet:#9374ff;
  --panel:rgba(8,12,26,.58);
  --line:rgba(148,190,255,.18);
  --mono:ui-monospace,"DejaVu Sans Mono","Liberation Mono",Menlo,Consolas,monospace;
  --sans:Lato,"DejaVu Sans","Liberation Sans",system-ui,sans-serif;
}

*{box-sizing:border-box}
html,body{height:100%;margin:0;background:var(--bg);color:var(--ink);overflow:hidden}
body{
  font-family:var(--sans);
  -webkit-font-smoothing:antialiased;
  overscroll-behavior:none;
  user-select:none;
  -webkit-user-select:none;
  -webkit-tap-highlight-color:transparent;
}
body.playing{touch-action:none}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer}
#scene{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none}

#vignette{
  position:fixed;inset:0;pointer-events:none;z-index:1;
  background:
    radial-gradient(ellipse at 50% 44%, transparent 28%, rgba(2,2,9,.28) 66%, rgba(1,1,6,.82) 100%),
    linear-gradient(180deg, rgba(1,1,6,.55) 0%, transparent 18%, transparent 72%, rgba(1,1,6,.7) 100%);
  mix-blend-mode:multiply;
}
#vignette::after{
  content:"";position:absolute;inset:0;opacity:.16;pointer-events:none;
  background-image:repeating-linear-gradient(0deg, rgba(255,255,255,.08) 0 1px, transparent 1px 3px);
  .compile-copy p{margin-bottom:10px;font-size:7px}
  .compile-bars{bottom:-34px;height:20px}
}

/* three-track start menu: keep phones on one screen */
@media (max-width:620px) and (orientation:portrait){
  .start-grid{gap:16px;padding-bottom:56px}
  .start-copy h1{font-size:clamp(62px,19vw,88px);margin:10px 0 8px}
  .start-copy .tagline{display:none}
  .track-picker{gap:5px;margin-bottom:10px}
  .track-card{padding:8px 11px}
  .specs{padding:9px 0;margin-bottom:11px}
  .start-copy .hint{margin-top:10px}
}
@media (max-height:540px) and (orientation:landscape){
  .start-copy .specs{display:none}
  .track-picker{gap:4px;margin-bottom:8px}
  .track-card{padding:7px 10px}
  .start-copy h1{margin:4px 0 6px}
  .start-copy .hint{font-size:7px;line-height:1.25;margin-top:5px}
}


/* ---------------- pendulum centre tap (CHRONOSTASIS STASIS) ---------------- */
#centerPad{
  position:fixed;left:50%;top:52%;width:190px;height:190px;z-index:6;
  transform:translate(-50%,-50%) scale(.82);
  display:grid;place-items:center;
  padding:0;border:1px solid rgba(255,209,102,.5);border-radius:50%;
  background:radial-gradient(circle, rgba(255,209,102,.16), rgba(255,209,102,.05) 58%, transparent 72%);
  box-shadow:0 0 46px rgba(255,209,102,.22), inset 0 0 34px rgba(255,209,102,.1);
  opacity:0;visibility:hidden;pointer-events:none;
  transition:opacity .22s ease, transform .22s ease, visibility .22s;
  touch-action:none;overflow:visible;
}
#centerPad.show{
  opacity:1;visibility:visible;pointer-events:auto;
  transform:translate(-50%,-50%) scale(1);
}
