input.newString:
case 'clockTick': scene.clockTick(ev.hand, ev.power ?? 1); break;
case 'pendulum':
  if (ev.mode === 'start') startPendulum(ev);
  else endPendulum();
  break;
case 'bossCamera':
  scene.bossCameraEvent(ev.pos, ev.look, ev.fov, ev.roll, ev.dur);
  break;
case 'bossGlitch':
  scene.bossGlitch(ev.power ?? 1);
  glitchScreen(ev.power ?? 1);
