import fs from 'node:fs';
const base = 'http://127.0.0.1:9222';
const target = await (async () => {
  const list = await (await fetch(base + '/json/list')).json();
  return list.find((t) => t.type === 'page' && t.url.startsWith('http')) || list.find((t) => t.type === 'page');
})();
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });
let id = 0;
const pending = new Map();
const logs = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) {
    const q = pending.get(m.id); pending.delete(m.id);
    m.error ? q.reject(new Error(JSON.stringify(m.error))) : q.resolve(m.result);
  } else if (m.method === 'Runtime.exceptionThrown') {
    logs.push(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
  } else if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') {
    logs.push(m.params.args.map((a) => a.value ?? a.description).join(' '));
  }
};
const send = (method, params = {}) => new Promise((res, rej) => {
  const mid = ++id; pending.set(mid, { resolve: res, reject: rej });
  ws.send(JSON.stringify({ id: mid, method, params }));
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const ev = async (x) => {
  const r = await send('Runtime.evaluate', { expression: x, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
  return r.result?.value;
};
const shot = async (name) => {
  const r = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('/tmp/opencode/boss/' + name, Buffer.from(r.data, 'base64'));
};
await send('Runtime.enable');
await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: 'http://127.0.0.1:3002/' });
await sleep(4500);

console.log('initial', await ev(`({
  state: window.__cryout?.state,
  cards: [...document.querySelectorAll('.track-card')].map(c=>c.dataset.track),
  title: document.title,
})`));

await ev(`document.querySelector('[data-track="untouchable"]').click()`);
await sleep(4500);
console.log('selected', await ev(`({
  state: window.__cryout?.state,
  track: window.__cryout?.chart.song.title,
  boss: window.__cryout?.scene.boss,
  body: document.body.className,
  btn: document.getElementById('startBtnLabel').textContent,
})`));
await shot('boss-menu.png');

await ev(`document.getElementById('startBtn').click()`);
await sleep(1800);
console.log('started', await ev(`({
  state: window.__cryout?.state,
  t: +window.__cryout?.audio.time.toFixed(2),
  body: document.body.className,
  boss: window.__cryout?.scene.boss,
  hudOpacity: getComputedStyle(document.getElementById('hud')).opacity,
  caption: document.getElementById('bossCaption').className,
})`));
await shot('boss-intro-open.png');

const seek = async (t) => {
  await ev(`(()=>{const a=window.__cryout.audio;a.startAt=a.ctx.currentTime-${t};})()`);
  await sleep(1300);
};
await seek(7.0);
console.log('t7', await ev(`({t:+window.__cryout.audio.time.toFixed(2), sec:document.getElementById('sectionName').textContent, boss:window.__cryout.scene.boss, cam:window.__cryout.scene.camera.position.toArray().map(n=>+n.toFixed(1)), body:document.body.className, cap:document.getElementById('bossCaption').className})`));
await shot('boss-intro-7.png');

await seek(15.5);
console.log('t15.5', await ev(`({t:+window.__cryout.audio.time.toFixed(2), sec:document.getElementById('sectionName').textContent, cam:window.__cryout.scene.camera.position.toArray().map(n=>+n.toFixed(1)), cap:document.getElementById('bcTitle').textContent})`));
await shot('boss-intro-15.png');

