await shot('boss-transition.png');

await seek(30.0);
console.log('t30', await ev(`({t:+window.__cryout.audio.time.toFixed(2), sec:document.getElementById('sectionName').textContent, keys:document.getElementById('keysCount').textContent, body:document.body.className, field:+window.__cryout.scene.boss.fieldFade.toFixed(2), boss:window.__cryout.scene.boss.mode, hud:getComputedStyle(document.getElementById('hud')).opacity, notes:window.__cryout.notes.filter(n=>n.state==='pending').length, free:window.__cryout.notes[0]?.free})`));
