import fs from 'node:fs';
const base = 'http://127.0.0.1:9222';
const target = (await (await fetch(base + '/json/list')).json()).find((t) => t.type === 'page' && t.url.startsWith('http'));
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { const q = pending.get(m.id); pending.delete(m.id); m.error ? q.reject(new Error(JSON.stringify(m.error))) : q.resolve(m.result); }
  else if (m.method === 'Runtime.exceptionThrown') logs.push(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
};
const send = (method, params = {}) => new Promise((res, rej) => { const mid = ++id; pending.set(mid, { resolve: res, reject: rej }); ws.send(JSON.stringify({ id: mid, method, params })); });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const ev = async (x) => { const r = await send('Runtime.evaluate', { expression: x, returnByValue: true, awaitPromise: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result?.value; };
const shot = async (name) => { const r = await send('Page.captureScreenshot', { format: 'png' }); fs.writeFileSync('/tmp/opencode/boss/' + name, Buffer.from(r.data, 'base64')); };
await send('Runtime.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: 'http://127.0.0.1:3002/' });
await sleep(4000);
await ev(`document.querySelector('[data-track="untouchable"]').click()`);
await sleep(3000);
await ev(`document.getElementById('startBtn').click()`);
await sleep(1400);
await ev(`(()=>{const a=window.__cryout.audio;a.startAt=a.ctx.currentTime-31.0;})()`);
await sleep(1800);
console.log('base', await ev(`({
  t:+window.__cryout.audio.time.toFixed(2),
  bloom:+window.__cryout.scene.bloom.strength.toFixed(3),
  mode:window.__cryout.scene.boss.mode,
  churchVisible:window.__cryout.scene.church.visible,
  churchChildren:window.__cryout.scene.church.children.length,
})`));
await shot('probe-base.png');

const setVis = async (expr) => { await ev(expr); await sleep(500); };
await setVis(`window.__cryout.scene.church.visible=false`);
console.log('church off');
await shot('probe-nochurch.png');
await setVis(`window.__cryout.scene.church.visible=true; window.__cryout.scene.laneRoot.visible=false; window.__cryout.scene.noteRoot.visible=false;`);
console.log('lanes off');
await shot('probe-nolanes.png');
await setVis(`window.__cryout.scene.laneRoot.visible=true; window.__cryout.scene.noteRoot.visible=true; window.__cryout.scene.windRoot.visible=false;`);
console.log('wind off');
await shot('probe-nowind.png');
await setVis(`window.__cryout.scene.windRoot.visible=true; window.__cryout.scene.bloom.strength=0;`);
console.log('bloom 0');
await shot('probe-nobloom.png');
await setVis(`window.__cryout.scene.bloom.strength=0.44; window.__cryout.scene.scene.getObjectByName('bossClock').visible=false;`);
console.log('clock off');
await shot('probe-noclock.png');

// inspect church material opacities
console.log('mats', await ev(`(()=>{const out=[];window.__cryout.scene.church.traverse(o=>{if(o.material&&o.material.opacity!==undefined)out.push([o.type,o.material.type,o.material.blending,+o.material.opacity.toFixed(3),o.scale.x.toFixed(1),o.position.z.toFixed(1)])});return out.slice(0,50)})()`));
console.log('logs', logs);
ws.close();

