357:   stats.weight += WEIGHT[kind];
358:   stats.score += SCORE[kind];
359:   stats.health = Math.min(100, stats.health + (kind === 'perfect' ? 1.1 : kind === 'great' ? .8 : kind === 'good' ? .4 : -1.6));
360: 
361:   if (kind === 'bad') {
362:     setCombo(0, false);
363:   } else {
364:     setCombo(stats.combo + 1);
365:   }
366: 
367:   if (note.type === 'hold') {
368:     note.state = 'holding';
369:     note.endTime = note.data.t + note.data.dur;
370:     note.tickAt = audio.time;
371:     note.head.visible = false;
372:     holdNote[note.lane] = note;
373:   } else {
374:     note.state = 'done';
375:     note.group.visible = false;
376:   }
377: 
378:   const text = kind === 'perfect' ? 'PERFECT' : kind === 'great' ? 'GREAT' : kind === 'good' ? 'GOOD' : 'BAD';
379:   showJudge(kind, text);
380:   scene.hitFx(note.lane, kind);
381:   audio.click(note.lane, kind === 'perfect' ? 0.52 : 0.38);
382: }
