384: function missNote(note) {
385:   if (note.state !== 'pending') return;
386:   note.state = 'miss';
387:   note.group.visible = false;
388:   stats.miss++;
389:   stats.judged++;
390:   stats.health = Math.max(0, stats.health - 5);
391:   setCombo(0, false);
392:   showJudge('miss', 'MISS');
393:   scene.missFx(note.lane);
394:   audio.thud();
395: }
