397: function dropHold(note) {
398:   if (note.state !== 'holding') return;
399:   note.state = 'dropped';
400:   note.group.visible = false;
401:   holdNote[note.lane] = null;
402:   stats.dropped++;
403:   stats.miss++;
404:   stats.judged++;
405:   stats.health = Math.max(0, stats.health - 4);
406:   setCombo(0, false);
407:   showJudge('miss', 'HOLD LOST');
408:   scene.missFx(note.lane);
409:   audio.thud();
410: }
