412: function completeHold(note) {
413:   if (note.state !== 'holding') return;
414:   note.state = 'done';
415:   note.group.visible = false;
416:   holdNote[note.lane] = null;
417:   stats.score += 450;
418:   stats.health = Math.min(100, stats.health + 1.2);
419:   scene.pressFx(note.lane);
420:   scene.hitFx(note.lane, 'great');
421: }
