423: function pressLane(lane) {
424:   if (gameState !== 'playing') return;
425:   scene.pressFx(lane);
426:   audio.click(lane, 0.16);
427:   const t = audio.time;
428:   if (t < 0) return;
429: 
430:   let best = null;
431:   let bestAbs = Infinity;
432:   for (const n of noteObjects) {
433:     if (n.lane !== lane || n.state !== 'pending') continue;
434:     const d = t - n.data.t;
435:     if (d < -EARLY_WINDOW || d > HIT_WINDOW) continue;
436:     const a = Math.abs(d);
437:     if (a < bestAbs) { bestAbs = a; best = n; }
438:   }
439:   if (!best) return;
440:   judgeHit(best, t - best.data.t);
441: }
