443: function releaseLane(lane) {
444:   if (gameState !== 'playing') return;
445:   const n = holdNote[lane];
446:   if (!n) return;
447:   // Another finger still resting on the glass keeps every active hold alive.
448:   if (touching()) return;
449:   holdNote[lane] = null;
450:   if (audio.time < n.endTime - 0.12) dropHold(n);
451:   else completeHold(n);
452: }
