493: function judgeSwing(note, offset) {
494:   const a = Math.abs(offset);
495:   let kind;
496:   if (a <= WIN.perfect) kind = 'perfect';
497:   else if (a <= WIN.great) kind = 'great';
498:   else if (a <= WIN.good) kind = 'good';
499:   else kind = 'bad';
500: 
501:   note.state = 'done';
502:   stats[kind]++;
503:   stats.judged++;
504:   stats.weight += WEIGHT[kind];
505:   stats.score += SCORE[kind];
506:   stats.health = Math.min(100, stats.health + (kind === 'perfect' ? 1.2 : kind === 'great' ? .9 : kind === 'good' ? .5 : -1.4));
507: 
508:   if (kind === 'bad') setCombo(0, false);
509:   else setCombo(stats.combo + 1);
510: 
511:   showJudge(kind, kind === 'perfect' ? 'PERFECT' : kind === 'great' ? 'GREAT' : kind === 'good' ? 'GOOD' : 'BAD');
512:   scene.swingResolve(note.index, 'hit');
513:   audio.click(3, kind === 'perfect' ? 0.56 : 0.4);
514: }
515: 
516: function missSwing(note) {
517:   if (note.state !== 'pending') return;
518:   note.state = 'miss';
519:   stats.miss++;
520:   stats.judged++;
521:   stats.health = Math.max(0, stats.health - 5);
522:   setCombo(0, false);
523:   showJudge('miss', 'MISS');
524:   scene.swingResolve(note.index, 'miss');
525:   audio.thud();
526: }
