535: function swingTap() {
536:   if (gameState !== 'playing' || !swingMode) return;
537:   const t = audio.time;
538:   let best = null;
539:   let bestAbs = Infinity;
540:   for (const n of swingNotes) {
541:     if (n.state !== 'pending') continue;
542:     const d = t - n.t;
543:     if (d < -EARLY_WINDOW || d > HIT_WINDOW) continue;
544:     const a = Math.abs(d);
545:     if (a < bestAbs) { bestAbs = a; best = n; }
546:   }
547:   if (!best) {
548:     scene.swingWhiff();
549:     audio.click(3, 0.1);
550:     return;
551:   }
552:   judgeSwing(best, t - best.t);
553: }
