555: // ---------------------------------------------------------------- note render
556: const SPEED = 8.4;
557: 
558: function updateNotes(t) {
559:   const ns = scene.noteScale;
560:   for (const n of noteObjects) {
561:     if (n.state === 'pending') {
562:       const y = (n.data.t - t) * SPEED;
563:       if (n.free) {
564:         // Boss notes fly along a curved stage-space path and converge on the
565:         // lane ring exactly at the hit line.
566:         const pose = scene.freeNotePose(n.lane, y, n.index);
567:         n.group.position.set(pose.x, pose.y, pose.z);
568:       } else {
569:         // local lane space: the lane frame supplies the diagonal world position
570:         n.group.position.set(0, y, 0.24);
571:       }
572:       n.group.visible = y < 14.5 && y > -1.3;
573:       n.head.scale.set(1.04 * ns, 1.04 * ns, 1);
574:       if (n.body) {
575:         const len = n.data.dur * SPEED;
576:         n.body.visible = n.group.visible;
577:         n.tail.visible = n.group.visible;
578:         n.body.scale.set(0.52 * ns, len, 1);
579:         n.body.position.y = len / 2;
580:         n.body.material.rotation = n.free ? 0 : -scene.laneScreenAngle(n.lane);
581:         n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
582:         n.tail.position.y = len;
583:       }
584:       if (t > n.data.t + HIT_WINDOW) missNote(n);
585:     } else if (n.state === 'holding') {
586:       if (!held[n.lane] && !touching()) { dropHold(n); continue; }
587:       if (t >= n.endTime - 0.02) {
588:         completeHold(n);
589:         continue;
590:       }
591:       const remain = Math.max(0, (n.endTime - t) * SPEED);
592:       n.group.visible = true;
593:       if (n.free) {
594:         const pose = scene.freeNotePose(n.lane, 0, n.index);
595:         n.group.position.set(pose.x, 0.02, pose.z);
596:       } else {
597:         n.group.position.set(0, 0.02, 0.24);
598:       }
599:       n.head.visible = false;
600:       if (n.body) {
601:         n.body.visible = remain > 0.03;
602:         n.body.scale.set(0.52 * ns, remain, 1);
603:         n.body.position.y = remain / 2;
604:         n.body.material.rotation = n.free ? 0 : -scene.laneScreenAngle(n.lane);
605:         n.tail.visible = remain > 0.4;
606:         n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
607:         n.tail.position.y = remain;
608:       }
609:       if (t > n.tickAt) {
610:         n.tickAt = t + 0.12;
611:         stats.score += 24;
612:         stats.health = Math.min(100, stats.health + 0.06);
613:       }
614:     } else {
615:       n.group.visible = false;
616:     }
617:   }
618: }
