707: function rankFor(acc, judged) {
708:   if (judged === 0) return 'F';
709:   if (acc >= 99.5) return 'S+';
710:   if (acc >= 98) return 'S';
711:   if (acc >= 93) return 'A';
712:   if (acc >= 86) return 'B';
713:   if (acc >= 76) return 'C';
714:   return acc < 50 ? 'F' : 'D';
715: }
