717: function comboGraphPath(history, peak) {
718:   const w = 320, h = 116;
719:   const pts = history.length ? history : [0, 0, 0, 0];
720:   const max = Math.max(1, peak, ...pts);
721:   const step = w / Math.max(1, pts.length - 1);
722:   let line = '';
723:   for (let i = 0; i < pts.length; i++) {
724:     const x = i * step;
725:     const y = h - (pts[i] / max) * (h - 10);
726:     line += `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`;
727:   }
728:   const fill = `${line}L${w} ${h}L0 ${h}Z`;
729:   return { line, fill };
730: }
