742: function animateNumber(el, to, duration, formatter) {
743:   const from = 0;
744:   const start = performance.now();
745:   const tick = (now) => {
746:     const p = Math.min(1, (now - start) / duration);
747:     const eased = 1 - Math.pow(1 - p, 3);
748:     el.textContent = formatter(Math.round(from + (to - from) * eased));
749:     if (p < 1) requestAnimationFrame(tick);
750:   };
751:   requestAnimationFrame(tick);
752: }
