826:   const rank = rankFor(acc, stats.judged);
827:   comboHistory.push(stats.combo);
828:   if (comboHistory.length > COMBO_CAP) comboHistory.shift();
829:   const full = stats.miss === 0 && stats.bad === 0 && stats.judged > 0;
830:   const runScore = stats.score;
831:   const prevBest = bestMap[selectedTrack.id] || null;
