834:     || (runScore === prevBest.score && acc > prevBest.acc);
835:   if (isBest) {
836:     bestMap[selectedTrack.id] = { score: runScore, acc, rank, maxCombo: stats.maxCombo, full, at: Date.now() };
837:     try { localStorage.setItem(BEST_KEY, JSON.stringify(bestMap)); } catch { /* storage unavailable */ }
838:   }
