859:     const p = Math.min(1, (now - start) / duration);
860:     const eased = 1 - Math.pow(1 - p, 3);
861:     dom.loadProgress.style.width = (eased * 100).toFixed(1) + '%';
862:     dom.loadPct.textContent = String(Math.round(eased * 100)).padStart(2, '0') + '%';
863:     if (p < 1) requestAnimationFrame(tick);
