880: function alignPads(ahead = new Set()) {
881:   // Long touch strips follow the projected lane direction. Tapping anywhere
882:   // along the lane hits that lane, and a lane with an incoming note is made
883:   // live before its section actually starts.
884:   const active = new Set(currentSection ? activeLanesFor(currentSection.keys) : []);
885:   for (const lane of ahead) active.add(lane);
886:   for (let i = 0; i < 8; i++) {
887:     const g = scene.laneScreenGeometry(i);
888:     const left = i > 0 ? g.x - scene.laneScreenGeometry(i - 1).x : g.x - scene.laneScreenGeometry(1).x;
889:     const right = i < 7 ? scene.laneScreenGeometry(i + 1).x - g.x : g.x - scene.laneScreenGeometry(6).x;
890:     // Fill the whole gap between neighbouring lanes. The strip boundaries meet
891:     // (and slightly overlap) at the midpoint, so a thumb landing between two
892:     // lanes still hits one of them instead of an invisible dead zone.
893:     const gap = Math.max(26, (Math.abs(left) + Math.abs(right)) * 0.5);
894:     const width = Math.max(48, Math.min(240, gap * 1.1));
