import { createRequire } from 'node:module';
import { readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
if (!process.env.DISPLAY) {
  try { process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim(); } catch {}
}
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const out = '/tmp/opencode/boss-shots';
import { mkdirSync } from 'node:fs';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 90000 });

console.log('menu state ok');
await page.screenshot({ path: join(out, '00-menu.png') });

// select boss track
await page.click('.track-card[data-track="untouchable"]');
await page.waitForTimeout(600);
const meta = await page.evaluate(() => ({
  track: document.querySelector('#startTrack')?.textContent,
  lanes: document.querySelector('#startLanes')?.textContent,
  level: document.querySelector('#startLevel')?.textContent,
  chartNotes: window.__cryout.chart.notes.length,
  sections: window.__cryout.chart.sections.map((s) => `${s.start}:${s.name}:${s.keys}`),
  intro: window.__cryout.chart.song.intro,
  freeNotes: window.__cryout.chart.song.freeNotes,
}));
console.log(JSON.stringify(meta, null, 2));
await page.screenshot({ path: join(out, '01-boss-menu.png') });

await page.click('#startBtn');
const t0 = Date.now();
const marks = [
  [3.5, '02-intro-3s'],
  [12, '03-intro-12s'],
  [22, '04-intro-22s'],
  [27.5, '05-intro-prebeat'],
  [31, '06-clock-31s'],
  [38, '07-clock-38s'],
  [55, '08-clock-55s'],
];
for (const [sec, name] of marks) {
  const wait = sec * 1000 - (Date.now() - t0);
  if (wait > 0) await page.waitForTimeout(wait);
  const info = await page.evaluate(() => ({
    state: window.__cryout.state,
    t: +window.__cryout.audio.time.toFixed(2),
    bossMode: window.__cryout.scene.debugBoss?.() ?? null,
    section: document.querySelector('#sectionName')?.textContent,
    bodyClass: document.body.className,
    hudHidden: document.querySelector('#hud')?.classList.contains('hidden'),
  }));
  console.log(name, JSON.stringify(info));
  await page.screenshot({ path: join(out, name + '.png') });
}

// gameplay sanity: notes exist near t and lanes are hit-testable
const gameplay = await page.evaluate(() => {
  const notes = window.__cryout.notes;
  const pending = notes.filter((n) => n.state === 'pending').length;
  const visible = notes.filter((n) => n.group.visible).length;
  const pads = [...document.querySelectorAll('.pad')].map((p) => ({
    lane: p.dataset.lane,
    live: p.classList.contains('active') || !p.classList.contains('sleep'),
    w: p.style.width, h: p.style.height,
  }));
  return { pending, visible, pads, t: window.__cryout.audio.time };
});
console.log('gameplay', JSON.stringify(gameplay, null, 2));

console.log('errors', errors.length ? errors : 'none');
await browser.close();

