// A long, curling wisp used by the boss stage's wind streams. Straight beam
// sprites read as scratch lines when they rotate; a curved, tapered gust reads
// as moving air even when it is billboarded.
function gustTexture() {
  const [c, x] = canvas(256, 1024);
  x.lineCap = 'round';
  const strands = [
    { off: -46, w: 30, a: 0.34, bend: 60, al: 0.12 },
    { off: -6, w: 24, a: 0.62, bend: -42, al: 0.5 },
    { off: 40, w: 15, a: 0.4, bend: 54, al: 0.4 },
    { off: 76, w: 8, a: 0.26, bend: -34, al: 0.55 },
  ];
  for (const s of strands) {
    const g = x.createLinearGradient(0, 1024, 0, 40);
    g.addColorStop(0, 'rgba(255,255,255,0)');
    g.addColorStop(s.al * 0.55, `rgba(255,255,255,${s.a * 0.55})`);
    g.addColorStop(s.al, `rgba(255,255,255,${s.a})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    x.strokeStyle = g;
    x.shadowColor = '#fff';
    x.shadowBlur = 24;
    x.lineWidth = s.w;
    const x0 = 128 + s.off * 0.2;
    const x1 = 128 + s.off;
    x.beginPath();
    x.moveTo(x0, 1024);
    x.bezierCurveTo(x0 + s.bend * 0.5, 760, x1 - s.bend, 360, x1, 40);
    x.stroke();
    // bright inner filament
    x.shadowBlur = 6;
    x.lineWidth = Math.max(2, s.w * 0.18);
    x.strokeStyle = `rgba(255,255,255,${s.a * 0.65})`;
    x.stroke();
  }
  return tex(c);
}
