import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
try { process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim(); } catch {}
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const out = '/tmp/opencode/smoke-shots'; mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 90000 });
await page.click('.track-card[data-track="untouchable"]');
await page.waitForTimeout(400);
await page.click('#startBtn');
await page.waitForTimeout(500);

// Fast-forward near the first notes.
await page.evaluate(() => { window.__cryout.audio.startAt -= 27.5; });
await page.waitForTimeout(1200);
await page.screenshot({ path: join(out, 'a-near-start.png') });

const before = await page.evaluate(() => ({
  t: +window.__cryout.audio.time.toFixed(2),
  state: window.__cryout.state,
  judged: window.__cryout.stats.judged,
  score: window.__cryout.stats.score,
}));
console.log('before autoplay', JSON.stringify(before));

// Install an autoplay bot that taps each pending note on its exact time.
await page.evaluate(() => {
  const codes = ['KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon'];
  window.__bot = setInterval(() => {
    const app = window.__cryout;
    if (!app || app.state !== 'playing') return;
    const t = app.audio.time;
    for (const n of app.notes) {
      if (n.state !== 'pending') continue;
      if (Math.abs(n.data.t - t) > 0.028) continue;
      if (n.type === 'hold') {
        document.dispatchEvent(new KeyboardEvent('keydown', { code: codes[n.lane] }));
        setTimeout(() => document.dispatchEvent(new KeyboardEvent('keyup', { code: codes[n.lane] })), (n.data.dur || 0) * 1000 + 60);
      } else {
        document.dispatchEvent(new KeyboardEvent('keydown', { code: codes[n.lane] }));
        setTimeout(() => document.dispatchEvent(new KeyboardEvent('keyup', { code: codes[n.lane] })), 40);
      }
    }
  }, 12);
});
await page.waitForTimeout(12000);
const mid = await page.evaluate(() => {
  clearInterval(window.__bot);
  const s = window.__cryout.stats;
  return {
    t: +window.__cryout.audio.time.toFixed(2),
    state: window.__cryout.state,
    score: s.score, judged: s.judged, combo: s.combo, maxCombo: s.maxCombo,
    perfect: s.perfect, great: s.great, good: s.good, bad: s.bad, miss: s.miss,
  };
});
console.log('after autoplay', JSON.stringify(mid));
await page.screenshot({ path: join(out, 'b-autoplay.png') });

// Jump to the finale to see the 8-lane free field.
const jumpTo = 118;
await page.evaluate((target) => {
  const app = window.__cryout;
  const t = app.audio.time;
  app.audio.startAt -= (target - t);
}, jumpTo);
await page.waitForTimeout(2500);
const finale = await page.evaluate(() => ({
  t: +window.__cryout.audio.time.toFixed(2),
  state: window.__cryout.state,
  section: document.querySelector('#sectionName')?.textContent,
  active: [...document.querySelectorAll('.pad')].filter((p) => !p.classList.contains('sleep')).length,
}));
console.log('finale', JSON.stringify(finale));
await page.screenshot({ path: join(out, 'c-finale.png') });

// Force the end of the chart and verify the results screen.
await page.evaluate(() => {
  const app = window.__cryout;
  app.audio.startAt -= (app.chart.song.chartEnd - app.audio.time + 1.5);
});
await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: 20000 });
await page.waitForTimeout(2600);
const results = await page.evaluate(() => ({
  state: window.__cryout.state,
  visible: document.querySelector('#resultScreen')?.classList.contains('show'),
  rank: document.querySelector('#rank')?.textContent,
  score: document.querySelector('#finalScore')?.textContent,
  acc: document.querySelector('#finalAcc')?.textContent,
  track: document.querySelector('#resultTrack')?.textContent,
  bpm: document.querySelector('#resultBpm')?.textContent,
  best: document.querySelector('#bestNote')?.textContent,
  errors: document.querySelector('#resultLoading')?.classList.contains('show'),
}));
console.log('results', JSON.stringify(results));
await page.screenshot({ path: join(out, 'd-results.png') });

// Back to the menu and ensure other tracks still select and load.
await page.click('#menuBtn');
await page.waitForTimeout(500);
await page.click('.track-card[data-track="chronostasis"]');
await page.waitForFunction(() => window.__cryout.state === 'menu', undefined, { timeout: 30000 });
const menu = await page.evaluate(() => ({
  state: window.__cryout.state,
  track: document.querySelector('#startTrack')?.textContent,
  laneLabel: document.querySelector('#startLanes')?.textContent,
  boss: document.body.classList.contains('boss-track'),
  chartNotes: window.__cryout.chart.notes.length,
}));
console.log('menu-after', JSON.stringify(menu));
await page.screenshot({ path: join(out, 'e-menu-after.png') });

console.log('errors', errors.length ? errors : 'none');
await browser.close();

