try { process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim(); } catch {}
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const out = '/tmp/opencode/full-run'; mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 90000 });
await page.click('.track-card[data-track="untouchable"]');
await page.waitForFunction(() => window.__cryout.state === 'menu', undefined, { timeout: 60000 });
await page.waitForTimeout(300);
await page.click('#startBtn');
await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });

const scheduled = await page.evaluate(() => {
  const codes = ['KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon'];
  const chart = window.__cryout.chart;
  let n = 0;
  for (const note of chart.notes) {
    const delay = Math.max(0, (note.t - window.__cryout.audio.time) * 1000);
    const hold = note.type === 'hold' ? (note.dur || 0) : 0.03;
    setTimeout(() => {
      if (window.__cryout.state !== 'playing') return;
      document.dispatchEvent(new KeyboardEvent('keydown', { code: codes[note.lane] }));
      setTimeout(() => {
        document.dispatchEvent(new KeyboardEvent('keyup', { code: codes[note.lane] }));
      }, hold * 1000 + 45);
    }, delay);
    n++;
  }
  return n;
});
console.log('scheduled notes:', scheduled);

const snap = async (label) => {
  const s = await page.evaluate(() => {
    const st = window.__cryout.stats;
    return {
      t: +window.__cryout.audio.time.toFixed(2),
      state: window.__cryout.state,
      section: document.querySelector('#sectionName')?.textContent,
      score: st.score, judged: st.judged, perfect: st.perfect, great: st.great,
      good: st.good, bad: st.bad, miss: st.miss, dropped: st.dropped,
      combo: st.combo, maxCombo: st.maxCombo,
    };
  });
  console.log(label, JSON.stringify(s));
  return s;
};

await page.waitForFunction(() => window.__cryout.audio.time >= 22, undefined, { timeout: 60000 });
await page.screenshot({ path: join(out, '1-intro.png') });

await page.waitForFunction(() => window.__cryout.audio.time >= 35.7, undefined, { timeout: 30000 });
await page.screenshot({ path: join(out, '2-hold.png') });
await snap('hold');

await page.waitForFunction(() => window.__cryout.audio.time >= 70, undefined, { timeout: 60000 });
await snap('hunt');

await page.waitForFunction(() => window.__cryout.audio.time >= 112.8, undefined, { timeout: 60000 });
await page.screenshot({ path: join(out, '3-apotheosis.png') });
await snap('apotheosis');

await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: 60000 });
await page.waitForTimeout(2600);
const final = await page.evaluate(() => {
  const st = window.__cryout.stats;
  return {
    state: window.__cryout.state,
    rank: document.querySelector('#rank')?.textContent,
    score: document.querySelector('#finalScore')?.textContent,
    acc: document.querySelector('#finalAcc')?.textContent,
    maxCombo: document.querySelector('#fMaxCombo')?.textContent,
    fullCombo: document.querySelector('#fcBadge')?.classList.contains('on'),
    tag: document.querySelector('#resultTag')?.textContent,
    counts: {
      perfect: st.perfect, great: st.great, good: st.good, bad: st.bad,
      miss: st.miss, dropped: st.dropped, judged: st.judged,
    },
    best: document.querySelector('#bestNote')?.textContent,
  };
});
console.log('FINAL', JSON.stringify(final, null, 1));
await page.screenshot({ path: join(out, '4-results.png') });
console.log('errors', errors.length ? errors : 'none');
await browser.close();

content.text:
Now I can see the full-res gameplay clearly.

Hold shot (4 lanes, CHAMBER, 36s):
- Beautiful. The clock face is legible with rose petals as outer ring. Side windows. Lane lines.
- **Bug/oddity:** The HUD shows "8 COMBO" and "4 LANES"; the 4 active rings are labeled D, F, J, K (correct), but there are **white lane lines going up from the rings through the clock**, and their top ends have no notes except one orange note at left. The hold at lane 5 (K) should show a hold body alongside the string? At t=36, hold started 35.05 dur 1.25, so it's still active until 36.3; the K lane should show a sustained beam/body. The K lane (rightmost ring) has a white line; I don't see a special hold body. Hmm, in `updateNotes` for holding state, it sets group position at freeNotePose(lane, 0) and body scale remain etc. The hold body should be a thick beam from the ring upward. The lane line is white; hold body is colored? I see the K lane line is white like the others. Maybe the hold body is there but thin/short? The remaining time 0.3s => body length 0.3*8.4=2.5 units, visible as a short segment. Hard to distinguish.

Wait—stats at 37.52 showed judged 9, but the screenshot at ~36.9? The file says 0:36. Judged 9 by 37.5. The hold at 35.05 gives one judged; notes at 30.367.. maybe 8 taps + hold = 9. OK.

- **Major issue:** The lane strings are **white** and very prominent, extending from the rings all the way up through the clock, making the clock look like a puppet. In the screenshot the 4 lane strings pass over the clock face, one directly through the center. It obscures the numerals. But arguably beams are part of the field. In other tracks, lanes are also lines. Here because the camera looks up, they overlap the clock. The chart camera at this section is [0,8.1,18.4] look [0,5.4,-3], so the clock is behind/above. The lane lines go to y 14.5, which projects into the clock. We could cap lane line height during boss to stop below the clock (e.g., y=9) so they don't stripe the clock. But notes also fly up to 14.5 and would still pass over the clock as they approach—that's desirable (free-flying notes across the playfield/clock). The strings, though, add clutter. Hmm, they also give a visual link and indicate lanes. Most rhythm games show lane beams. I'd reduce their opacity in boss mode (lineTarget * 0.55) rather than cap, to keep the clock readable. The current line opacity for live lanes is 0.86/0.96*0.58 ≈ 0.5; a bit strong. Reduce boss line target by another ~0.55. Also lane beams (wide gradient) already *0.55. Could do.

- The 250 combo at APOTHEOSIS: **Problem:** The combo counter "250" overlaps the clock on the left and is huge. Existing game style; okay.

- **Note paths**: In the APOTHEOSIS 8-lane screenshot, the notes fly on wildly angled paths (some on diagonal lines from bottom-right to top-left), and the lane rings at the bottom have white/gold lines. Actually the notes' approach paths are diagonal because of free-note sway; the **white lane strings** (guide lines) are still vertical, while notes appear on separate diagonal paths as if detached. Wait the notes are on diagonal trajectories not aligned with their lane strings. Since freeNotePose sways x by ±2 units and z by ±1.4, the projection creates diagonal approaches. This matches "notes move freely across the playfield". At the top, some notes are far from their lane strings; it may be visually confusing. But the notes converge to their rings. In the screenshot, 8 rings are visible, and note orbs are scattered above (some over the clock). It's chaotic—intended for a boss finale. Difficult but readable? The note destinations are unclear until near the rings because trajectories curve. This could make the chart effectively unreadable for humans, despite the autoplay bot hitting everything.

The user requested "allow notes to move freely across the playfield" and "difficult". So yes.

- **Wind**: I don't see wind streaks in the hold shot (4 lanes active => 4 wind streams at outer lanes, which are off-screen? In the 4-lane layout, the unused lanes 0,1,6,7 are mapped to wide spacing; their x ±? They may be outside the screen edges, so wind is invisible). In the APOTHEOSIS 8-lane shot all lanes active, so no wind. Hmm. In CHAMBER 4-lane, the unused lanes are far outside, so wind is off-screen—failing the "unused lanes become wind" visual for 4-lane sections. The frameFor(4) spacing 3.15 positions lanes 0..7 across x=±11, outside view. The wind streams follow `lanes[stream.lane].group.position.x`, so outer lanes beyond screen. In the 6-lane MECHANISM screenshot earlier, wind was visible at edges. For 4-lane, not.

We could position wind streams for unused lanes at the *visible* edge positions rather than the far lane x. E.g., clamp laneX to ±(visible half width) or use a normalized position. The idle lane positions in 4-lane sections are offscreen anyway (rings not shown). To show wind, place unused lane streams at interpolated screen-edge positions. Simplest: in updateWind, compute `laneX` as the lane group x, but clamp to ±6.5; or for inactive lanes, use a remapped x based on lane index across the *visible* field: x = (lane - 3.5) * state.spacing * (state.keyCount/8)? Hmm.

Better: For boss wind, don't tie to lane x at all; use a "wind column" x computed from lane index normalized across the screen. But requirement says unused lanes become wind, so keeping near their lane positions is good, but if offscreen, no effect. The field for 4 lanes is centered; unused lanes are outside the playfield entirely. The wind could sweep across the field from the edges. Use: `const laneX = THREE.MathUtils.clamp(lanes[stream.lane].group.position.x, -state.spacing*2.2, state.spacing*2.2)`? For 4-lane spacing 3.15, clamp ±6.9, still near screen edges at x±6.9 (visible? camera fov 46, z~18, half-width at z0 ≈ 7.8 → visible). The outer lane x = (0-3.5)*3.15 = -11 → clamp -6.9, visible at left edge. For 8-lane spacing 1.75, lane 0 x=-6.1, visible. So clamping to ±(spacing*2.2) gives wind at edges. But all unused lanes clamp to the same x if far (lanes 0,1 both -6.9). Use a smaller subset or offset per lane: clamp(±(spacing*(1.6 + lane%2*0.5))) etc. Simpler: use visible field edge based on keyCount:
```
const halfSpan = (state.keyCount - 1) * state.spacing * 0.5;
const edge = halfSpan + state.spacing * (0.8 + (stream.lane % 2) * 0.55);
const laneX = stream.lane < 3.5 ? -edge : edge;
```
This places wind just outside the active lane field, regardless of key count. For 4 lanes: halfSpan=4.725; edge=7.2-8.9 → maybe offscreen slightly. Reduce to +0.45..0.8*spacing = 6.1-7.2; half-width at z=0 ~? camera at z18.4, fov 46, aspect 1.6: half-height = tan(23°)*18.4≈7.8, half-width≈12.5. So x=7 is visible. Good. For 8 lanes: halfSpan=6.1; edge 6.1+0.8..1.35*1.75 = 7.5-8.5, visible. Good.

But using x edges far from playfield: wind still crosses via sway.

Then adjust `updateWind` to use this edge x instead of lane group x. It should also work during intro (all lanes inactive, keyCount 8 from section OVERTURE =8): wind at ±7.5-8.5, outside the 8-lane field edges; that might look sparse. During intro, ideally wind streams spread across all lanes (they currently do). We can use lane group x during intro, and edge-clamped x during play. Or blend: if boss.intro, use lane x; else clamp. Use:
```
let laneX = lanes[stream.lane].group.position.x;
if (!boss.intro) {
  const half = (state.keyCount - 1)*state.spacing*0.5;
  const edge = half + state.spacing*(0.55 + (stream.lane%2)*0.45);
  laneX = stream.lane < 3.5 ? -edge : edge;
}
```
For 6-lane: half=5.4; edge 5.4+1.19..2.16 = 6.6-7.6; visible. 4-lane: half 4.725; edge 6.45-8.14. Good.
- In portrait, camera z ~+6.4 further, fov52: horizontal half-width at z0 ~ (18.8+? ) tan(26)*? aspect 0.46 → half-width ≈ 8.9*0.46=4.1? Portrait visible width is narrow: at z=0, distance 18.8, half-height=9.2, half-width=4.2. Edge 6.4 is offscreen. Our wind in portrait screenshots showed at edges? We saw pink shards near edges in mobile 2-play, likely from intro lane positions? In play, edge x 6.4 would be offscreen. Should compute clamp based on camera visibility? Simpler: multiply edge by 0.75 in portrait => 4.8, still slightly outside 4.2 but ribbons sway inward; might show. Or use 0.55. Could compute approximate halfWidth:
```
const dist = camera.position.z; // ~18-19
const halfH = Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*dist;
const halfW = halfH*camera.aspect;
edge = Math.min(edge, halfW*0.92)
```
But in boss camera locked, z varies. Good enough. Actually for portrait edge should be near halfW*0.8 ≈ 3.4. For desktop halfW ≈ 12, edge clamp 6.6 unaffected. Let's compute with camera.aspect and fov each frame: `const halfW = Math.tan(camera.fov*π/360) * Math.abs(camera.position.z) * camera.aspect; const edge = min(half + ..., halfW*0.9);`. But during intro camera z=48 far; intro uses lane x anyway.

This would ensure wind visible at the sides on all layouts.

Do we want to spend more time? The game is already complete; but this improves an explicit requirement ("Turn unused lanes into flying 3D wind effects"). In 4-lane sections currently invisible => worth fixing.

Also lane strings over clock: reduce opacity.

Also the results screen final numbers: we need to verify by waiting longer. Could rerun later.

Let me implement the wind edge placement + line dimming, then do a focused screenshot at 4-lane gameplay (t=36) to confirm wind visible at sides. That requires a 36s wait or jump. Use jump: start, then set audio.startAt -= 30, wait 6s to reach 36; events cascade, but note timing/autoplay not needed. Screenshot. For mobile too.

Implementation details:
In updateWind:
```
const intro = boss.intro;
...
let laneX = lanes[stream.lane].group.position.x;
if (!intro) {
  const half = (Math.max(4,state.keyCount)-1)*state.spacing*0.5;
  const side = stream.lane < 3.5 ? -1 : 1;
  const dist = Math.abs(camera.position.z);
  const halfW = Math.tan(camera.fov*Math.PI/360) * dist * camera.aspect;
  const edge = Math.min(half + state.spacing*(0.55+(stream.lane%2)*0.45), halfW*0.86);
  laneX = side*edge;
