import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
try { process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim(); } catch {}
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const out = '/tmp/opencode/wind-final'; mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
for (const view of [{ n: 'desktop', w: 1440, h: 900, m: false }, { n: 'mobile', w: 390, h: 844, m: true }]) {
  const page = await browser.newPage({ viewport: { width: view.w, height: view.h }, isMobile: view.m, hasTouch: view.m });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
  await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 90000 });
  await page.click('.track-card[data-track="untouchable"]');
  await page.waitForFunction(() => window.__cryout.state === 'menu', undefined, { timeout: 60000 });
  await page.waitForTimeout(300);
  await page.click('#startBtn');
  await page.waitForTimeout(500);
  await page.evaluate(() => { window.__cryout.audio.startAt -= 29; });
  await page.waitForTimeout(7000);
  const info = await page.evaluate(() => {
    const app = window.__cryout;
    const wind = app.scene.windRoot.children.filter((c) => c.visible);
    return {
      t: +app.audio.time.toFixed(1),
      section: document.querySelector('#sectionName')?.textContent,
      active: app.scene.state.active.size,
      windVisible: wind.length,
      errors: null,
