import * as THREE from 'three';
import { CHART } from '/home/runner/work/PlayGround/PlayGround/src/charts/untouchable.js';

const events = CHART.events.filter((e) => e.type === 'bossCamera' && e.t >= 28.4);
const ringY = 0;      // hit line world height
const ringZ = 0.24;
const clockTopY = 10.4 + 10.5 * 0.96;
const clockZ = -39;

function project(ev, aspect, opts) {
  const cam = new THREE.PerspectiveCamera(ev.fov, aspect, 0.1, 240);
  let [x, y, z] = ev.pos;
  if (opts.zMin !== undefined) z = Math.max(z, opts.zMin);
  if (opts.yMax !== undefined) y = Math.min(y, opts.yMax);
  if (opts.yScale !== undefined) y *= opts.yScale;
  cam.position.set(x, y, z);
  const [lx, ly, lz] = ev.look;
  cam.lookAt(new THREE.Vector3(lx, opts.lookY ?? ly, lz));
  if (opts.roll) cam.rotation.z += opts.roll;
  cam.updateMatrixWorld();
  cam.updateProjectionMatrix();
  const pRing = new THREE.Vector3(0, ringY, ringZ).project(cam);
  const pClockTop = new THREE.Vector3(0, clockTopY, clockZ).project(cam);
  const pClockBottom = new THREE.Vector3(0, 10.4 - 10.5 * 0.96, clockZ).project(cam);
  const sy = (p) => (1 - p.y) / 2;
  const sx = (p) => (p.x + 1) / 2;
  return {
    ring: sy(pRing), ringX: sx(pRing),
    clockTop: sy(pClockTop), clockBottom: sy(pClockBottom),
  };
}

for (const opts of [
  { label: 'current' },
  { label: 'zMin19.5', zMin: 19.5 },
  { label: 'zMin20.5', zMin: 20.5 },
  { label: 'zMin21.5', zMin: 21.5 },
]) {
  for (const [name, aspect] of [['desk', 1.6], ['port', 0.462]]) {
    let worstRing = 0, worstClockTop = 1;
    const rows = [];
    for (const ev of events) {
      const p = project(ev, aspect, opts);
      worstRing = Math.max(worstRing, p.ring);
      worstClockTop = Math.min(worstClockTop, p.clockTop);
      rows.push({ t: ev.t, ring: p.ring, ct: p.clockTop });
    }
    rows.sort((a, b) => b.ring - a.ring);
    console.log(opts.label, name,
      'worst ring', (worstRing * 100).toFixed(1) + '%',
      'clock top min', (worstClockTop * 100).toFixed(1) + '%',
      'top5', rows.slice(0, 5).map((r) => `${r.t.toFixed(0)}s:${(r.ring * 100).toFixed(0)}%/ct${(r.ct * 100).toFixed(0)}`).join(' '));
  }
}

