import { readFileSync } from 'node:fs';

const src = readFileSync('/home/runner/work/PlayGround/PlayGround/tools/build-boss-chart.mjs', 'utf8');
const block = src.slice(src.indexOf('const cameraKeys = ['), src.indexOf('];', src.indexOf('const cameraKeys = [')) + 2);
const cameraKeys = eval(block.replace('const cameraKeys =', '(') + ')');

const clockY = 10.4, clockR = 10.5, clockZ = -39;
const ringY = 0.02, ringZ = 0.22;
const D2R = Math.PI / 180, R2D = 180 / Math.PI;

function solveKey([t, pos, look, fov, roll, dur], ringFrac = 0.8, clockFrac = 0.1) {
  const [x, y, z] = pos;
  const dxr = Math.hypot(x - 0, z - ringZ);
  const dxc = Math.hypot(x - 0, (z - clockZ));
  const a = Math.atan2(ringY - y, dxr);
  const b = Math.atan2(clockY + clockR - y, dxc);
  const span = b - a;
  const ndcRing = 1 - 2 * ringFrac;   // negative
  const ndcClock = 1 - 2 * clockFrac; // positive
  // atan(-ndcRing*T) + atan(ndcClock*T) = span
  let lo = 0.01, hi = 4;
  for (let i = 0; i < 80; i++) {
    const T = (lo + hi) / 2;
    const s = Math.atan(-ndcRing * T) + Math.atan(ndcClock * T);
    if (s < span) lo = T; else hi = T;
  }
  const T = (lo + hi) / 2;
  const needFov = 2 * Math.atan(T) * R2D;
  const p = a + Math.atan(-ndcRing * T);
  return { t, x, y, z, fov, needFov, pitch: p * R2D, span: span * R2D };
}

console.log('t      posy  posz  fov  needFov pitch  span');
for (const key of cameraKeys) {
  if (key[0] < 28.4) continue;
  const r = solveKey(key);
  console.log(
    r.t.toFixed(2).padStart(6),
    r.y.toFixed(1).padStart(5),
    r.z.toFixed(1).padStart(5),
    String(r.fov).padStart(4),
    r.needFov.toFixed(1).padStart(7),
    r.pitch.toFixed(1).padStart(6),
    r.span.toFixed(1).padStart(5),
  );
}

