import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const url = process.env.CAP_URL || 'http://127.0.0.1:3002/';
const outDir = '/tmp/opencode/shots';
mkdirSync(outDir, { recursive: true });
const times = (process.env.SHOT_TIMES || '70,108,116,120,137,139').split(',').map(Number);
const mobile = process.env.SHOT_MOBILE === '1';

process.env.DISPLAY = ':' + (await import('node:fs')).readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse((await import('node:fs')).readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

for (const t of times) {
  const page = await browser.newPage({
    viewport: mobile ? { width: 390, height: 844 } : { width: 1440, height: 900 },
    deviceScaleFactor: 1,
    isMobile: mobile,
    hasTouch: mobile,
  });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
  await page.evaluate(async () => { await window.__cryout.selectTrack('untouchable'); });
  await page.waitForFunction(() => window.__cryout.state === 'menu' && window.__cryout.audio.loaded);
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });
  await page.waitForTimeout(500);
  await page.evaluate((tt) => window.__cryout.audio.start(Math.max(0, tt - 2.2)), t);
  await page.waitForTimeout(2900);
  const info = await page.evaluate(() => {
    const c = window.__cryout;
    const cam = c.scene.camera;
    return {
      t: c.audio.time,
      cam: [cam.position.x, cam.position.y, cam.position.z].map((v) => +v.toFixed(2)),
      fov: +cam.fov.toFixed(1),
      state: c.state,
    };
  });
  const file = join(outDir, `${mobile ? 'm' : 'd'}-${t}.png`);
  await page.screenshot({ path: file });
  console.log(t, JSON.stringify(info), errors.length ? 'ERRORS ' + errors.join('|') : '');
  await page.close();
}
await browser.close();

