}

function updateGhostEvents(t) {
  const list = chart.ghosts || [];
  while (ghostCursor < list.length && list[ghostCursor].t <= t) {
    const g = list[ghostCursor++];
    scene.ghostFx(g.lane, g.type);
  }
}

function updateChartEvents(t) {
  const list = chart.events || [];
  while (eventCursor < list.length && list[eventCursor].t <= t) {
    const ev = list[eventCursor++];
    switch (ev.type) {
      case 'echo': scene.echoFx(ev.lane, ev.dir ?? (ev.lane < 3.5 ? -1 : 1), ev.power ?? 1); break;
      case 'pulse': scene.pulseFx(ev.power ?? 1); break;
      case 'burst': scene.burstFx(ev.lane, ev.power ?? 1); break;
      case 'vibe':
        scene.vibeFx(ev.power ?? 1);
        flashScreen(ev.power ?? 1);
        break;
      case 'motion': scene.motionEvent(ev.style, ev.amp, ev.speed, ev.pitch); break;
      case 'clock':
        scene.setClock(ev.mode, ev.power ?? 1, ev.t);
        if (ev.mode !== 'freeze') endPendulum();
        break;
      case 'clockTick': scene.clockTick(ev.hand, ev.power ?? 1); break;
      case 'pendulum':
        if (ev.mode === 'start') startPendulum(ev);
        else endPendulum();
        break;
      case 'bossCamera':
        scene.bossCameraEvent(ev.pos, ev.look, ev.fov, ev.roll, ev.dur);
        break;
      case 'bossGlitch':
        scene.bossGlitch(ev.power ?? 1);
        glitchScreen(ev.power ?? 1);
        flashScreen((ev.power ?? 1) * 0.6);
        break;
      case 'bossTick':
        scene.bossTick(ev.hand, ev.power ?? 1);
        break;
      case 'bossPhase':
        scene.setBoss(ev.mode === 'play' ? 'play' : 'outro');
        if (ev.mode === 'play') {
          setBossIntro(false);
          toast('CLOCK STAGE // FREE FIELD', 1700);
        } else {
          hideCaption();
        }
        break;
      case 'wind':
        scene.windFx(ev.power ?? 1);
        break;
      case 'caption':
        showCaption(ev);
        break;
      default: break;
    }
  }
}

// ---------------------------------------------------------------- input
function keyDown(e) {
  if (e.code === 'Escape') {
    if (gameState === 'playing') { e.preventDefault(); pauseGame(); }
    else if (gameState === 'paused') { e.preventDefault(); resumeGame(); }
    return;
  }
  if (e.code === 'Space') {
    if (gameState === 'playing' && swingMode) {
      e.preventDefault();
      if (!e.repeat) swingTap();
    }
    return;
  }
  if (e.repeat) return;
  const lane = KEYMAP[e.code];
  if (lane === undefined) return;
  e.preventDefault();

  function render() {
    composer.render();
  }

  function dispose() {
    renderer.dispose();
  }

  return {
    scene, camera, stage, noteRoot, state, clock, boss, bloom, laneRoot, windRoot, church,
    makeNote, setSection, animate, render, laneX, laneZ, worldPoint,
    laneScreenXs, laneScreenPoints, laneScreenGeometry, laneScreenAngle,
    setPreviewLanes, setCity, setTempo,
    setClock, clockTick, clockReset,
    setBoss, bossCameraEvent, bossGlitch, bossTick, windFx, freeNotePose,
    startPendulum, stopPendulum, swingResolve, swingWhiff, pendulumReset, pendulumTargetScreen,
    pendulum,
    pressFx, hitFx, missFx, ghostFx, echoFx, pulseFx, burstFx, vibeFx, motionEvent,
    clearGhosts, layout, dispose,
    get noteSpeed() { return state.noteSpeed; },
    set noteSpeed(v) { state.noteSpeed = v; },
    get noteScale() { return Math.max(1, Math.min(1.3, state.view.ring / 1.65)); },
  };
}

