import { readFileSync, writeFileSync } from 'node:fs';

const path = '/home/runner/work/PlayGround/PlayGround/tools/build-boss-chart.mjs';
const src = readFileSync(path, 'utf8');
const start = src.indexOf('const cameraKeys = [');
const end = src.indexOf('];', start);
const keys = eval(src.slice(start, end + 1).replace('const cameraKeys =', '(') + ')');

const clockY = 10.4, clockR = 10.5, clockZ = -39;
const ringY = 0.02, ringZ = 0.22;
const R2D = 180 / Math.PI;
const ringFrac = Number(process.env.RING_FRAC || 0.795);
const clockFrac = Number(process.env.CLOCK_FRAC || 0.085);
const maxFov = Number(process.env.MAX_FOV || 56);
const minFov = Number(process.env.MIN_FOV || 46);
const ndcRing = 1 - 2 * ringFrac, ndcClock = 1 - 2 * clockFrac;

function frame(x, y, z) {
  const ar = Math.atan2(ringY - y, Math.hypot(x, z - ringZ));
  const ac = Math.atan2(clockY + clockR - y, Math.hypot(x, z - clockZ));
  const span = ac - ar;
  let lo = 0.01, hi = 4;
  for (let i = 0; i < 90; i++) {
    const T = (lo + hi) / 2;
    if (Math.atan(-ndcRing * T) + Math.atan(ndcClock * T) < span) lo = T; else hi = T;
  }
  const T = (lo + hi) / 2;
  return { fov: 2 * Math.atan(T) * R2D, pitch: ar + Math.atan(-ndcRing * T) };
}

const out = [];
const rows = [];
for (const key of keys) {
  const [t, pos, look, fov, roll, dur] = key;
  const [x, y0, z] = pos;
  if (t < 28.4) { out.push(key); continue; }
  let f = frame(x, y0, z);
  let y = y0;
  if (f.fov > maxFov) {
    // lower the camera until the required fov fits inside the cap
    let lo = -4, hi = y0;
    for (let i = 0; i < 90; i++) {
      const mid = (lo + hi) / 2;
      if (frame(x, mid, z).fov > maxFov) hi = mid; else lo = mid;
    }
    y = (lo + hi) / 2;
    f = frame(x, y, z);
  }
  const nf = Math.round(Math.min(maxFov, Math.max(minFov, f.fov)) * 10) / 10;
  // Recompute pitch for the rounded fov so the ring sits exactly on target.
  const T = Math.tan((nf * Math.PI) / 360);
  const ar = Math.atan2(ringY - y, Math.hypot(x, z - ringZ));
  const pitch = ar + Math.atan(-ndcRing * T);
  const lookY = y + Math.tan(pitch) * (z - look[2]);
  const nk = [
    t,
    [+x.toFixed(2), +y.toFixed(2), +z.toFixed(2)],
    [+look[0].toFixed(2), +lookY.toFixed(2), +look[2].toFixed(2)],
    nf,
    roll,
    dur,
  ];
  out.push(nk);
  rows.push({ t, y0, y: nk[1][1], fov, nf, lookY: nk[2][1], dy: +(nk[1][1] - y0).toFixed(2) });
}

console.log(rows.map((r) => `${r.t.toFixed(1)} y ${r.y0}->${r.y} fov ${r.fov}->${r.nf} lookY ${r.lookY}`).join('\n'));

if (process.env.WRITE === '1') {
  const body = out.map((k) => `  [${k[0]}, [${k[1].join(', ')}], [${k[2].join(', ')}], ${k[3]}, ${k[4]}, ${k[5]}],`).join('\n');
  const next = src.slice(0, start) + 'const cameraKeys = [\n' + body + '\n' + src.slice(end);
  writeFileSync(path, next);
  console.log('wrote', path);
}

