    // pitch
    if (needs pitch || fov changed) camera.rotateX(delta)
    // fov for crown
    if (crownY < 0.02) { fov = min(fovMax, fov * crownFactor); apply }
    // fov for horizontal
    if (xOverflow) { fov = min(fovMax, fov * xFactor); apply; continue; }
    if (xOverflow && fov >= fovMax) { dolly back; continue; }
