import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const mobile = process.env.MOBILE === '1';
const times = (process.env.TIMES || '30,34,41,49,55,62,64,70,74,79,83,87,89,97,105,107,112,116,120,124,128,132,137,140').split(',').map(Number);

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

for (const T of times) {
  const page = await browser.newPage({
    viewport: mobile ? { width: 390, height: 844 } : { width: 1440, height: 900 },
    deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile,
  });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
  await page.evaluate(async () => { await window.__cryout.selectTrack('untouchable'); });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });
  await page.evaluate((tt) => window.__cryout.audio.start(tt - 0.4), T);
  await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
  const out = await page.evaluate(() => {
    const c = window.__cryout;
    c.audio.pause();
    for (let i = 0; i < 200; i++) c.scene.animate(1 / 30, c.audio.time, true);
    c.scene.render();
    const cam = c.scene.camera;
    const V = cam.position.constructor;
    const st = c.scene.state;
    const p = (x, y, z) => { const v = new V(x, y, z).project(cam); return { x: (v.x + 1) / 2, y: (1 - v.y) / 2 }; };
    const rings = [];
    for (const i of st.active) {
      const x = st.laneXNow[i];
      const z = 0.015 * (i - 3.5) * st.view.spacing * (i - 3.5) * st.view.spacing * 0 + 0.22;
      rings.push({ i, ...p(x, 0.02, z) });
    }
    const clockG = c.scene.church.children.find((o) => o.name === 'bossClock');
    const crownY = clockG ? clockG.position.y + 10.5 * clockG.scale.y : 0;
    const crown = p(0, crownY, clockG ? clockG.position.z : -39);
    return {
      t: +c.audio.time.toFixed(2), mode: c.scene.boss.mode, keys: st.keyCount,
      portrait: st.portrait,
      cam: [cam.position.x, cam.position.y, cam.position.z].map((v) => +v.toFixed(2)),
      fov: +cam.fov.toFixed(1),
      ringMinX: +Math.min(...rings.map((r) => r.x)).toFixed(3),
      ringMaxX: +Math.max(...rings.map((r) => r.x)).toFixed(3),
      ringY: +Math.max(...rings.map((r) => r.y)).toFixed(3),
      crownY: +crown.y.toFixed(3),
      active: [...st.active].join(','),
    };
  });
  console.log(JSON.stringify(out), errors.length ? 'ERR ' + errors.join('|') : '');
  await page.close();
}
await browser.close();

