import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const mobile = process.env.MOBILE === '1';
const times = (process.env.TIMES || '29,31,35,41,45,49,53,56,59,62,64,66,70,72,75,78,81,84,86,88,90,94,98,102,105,106,108,110,112,114,116,118,120,122,124,126,128,130,132,134,136,138,140,142')
  .split(',').map(Number).sort((a, b) => a - b);

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

const page = await browser.newPage({
  viewport: mobile ? { width: 390, height: 844 } : { width: 1440, height: 900 },
  deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile,
});
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
await page.evaluate(async () => { await window.__cryout.selectTrack('untouchable'); });
await page.click('#startBtn');
await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });

const rows = [];
for (const T of times) {
  await page.evaluate((tt) => window.__cryout.audio.start(tt - 0.35), T);
  await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
  const out = await page.evaluate(() => {
    const c = window.__cryout;
    c.audio.pause();
    for (let i = 0; i < 220; i++) c.scene.animate(1 / 30, c.audio.time, true);
    const cam = c.scene.camera;
    const V = cam.position.constructor;
    cam.updateMatrixWorld();
    const st = c.scene.state;
    const p = (v) => { const q = v.clone().project(cam); return { x: (q.x + 1) / 2, y: (1 - q.y) / 2 }; };
    let minX = 9, maxX = -9, maxY = -9, minCrown = 9;
    for (const i of st.active) {
      const w = c.scene.laneRoot.children[i].localToWorld(new V(0, 0.02, 0.22));
      const q = p(w);
      minX = Math.min(minX, q.x); maxX = Math.max(maxX, q.x); maxY = Math.max(maxY, q.y);
    }
    const clockG = c.scene.church.children.find((o) => o.name === 'bossClock');
    const crown = p(new V(0, clockG.position.y + 10.5 * clockG.scale.y, clockG.position.z));
    return {
      t: +c.audio.time.toFixed(1), keys: st.keyCount, mode: c.scene.boss.mode,
      cam: [cam.position.x, cam.position.y, cam.position.z].map((v) => +v.toFixed(1)),
      fov: +cam.fov.toFixed(0),
      x: [+minX.toFixed(2), +maxX.toFixed(2)], ring: +maxY.toFixed(2), crown: +crown.y.toFixed(2),
    };
  });
  rows.push(out);
  await page.evaluate(() => window.__cryout.audio.resume());
}

const bad = rows.filter((r) => r.ring > 0.88 || r.crown < 0.0 || r.x[0] < -0.01 || r.x[1] > 1.01);
console.log(mobile ? 'PORTRAIT' : 'DESKTOP', 'rows', rows.length, 'violations', bad.length);
for (const r of rows) console.log(`${r.t.toFixed(1).padStart(5)} k${r.keys} ${r.mode.padEnd(5)} fov${String(r.fov).padStart(3)} cam[${r.cam.join(',')}] ringY ${r.ring} crown ${r.crown} x[${r.x.join(',')}]${bad.includes(r) ? '  <-- OUT' : ''}`);
if (errors.length) console.log('ERRORS', errors.join('|'));
await page.close();
await browser.close();

