import { readFileSync, writeFileSync } from 'node:fs';

const path = '/home/runner/work/PlayGround/PlayGround/tools/build-boss-chart.mjs';
const src = readFileSync(path, 'utf8');
const start = src.indexOf('const cameraKeys = [');
const end = src.indexOf('];', start);
const head = src.slice(0, start);
const body = src.slice(start, end + 1);
const tail = src.slice(end + 1);

const clockY = 10.4, clockR = 10.5, clockZ = -39;
const ringY = 0.02, ringZ = 0.22;
const R2D = 180 / Math.PI;
const ringFrac = 0.785, clockFrac = 0.10;
const maxFov = 54, minFov = 46;
const ndcRing = 1 - 2 * ringFrac, ndcClock = 1 - 2 * clockFrac;

function needFov(x, y, z) {
  const a = Math.atan2(ringY - y, Math.hypot(x, z - ringZ));
  const b = Math.atan2(clockY + clockR - y, Math.hypot(x, z - clockZ));
  const span = b - a;
  let lo = 0.01, hi = 4;
  for (let i = 0; i < 90; i++) {
    const T = (lo + hi) / 2;
    if (Math.atan(-ndcRing * T) + Math.atan(ndcClock * T) < span) lo = T; else hi = T;
  }
  return { fov: 2 * Math.atan((lo + hi) / 2) * R2D, a };
}

const num = (v) => String(+v.toFixed(2));

const lines = body.split('\n').map((line) => {
  const m = line.match(/^(\s*\[)([^,]+),\s*\[([^\]]+)\],\s*\[([^\]]+)\],\s*([^,]+),\s*([^,]+),\s*([^\]]+)\](.*)$/);
  if (!m) return line;
  const t = parseFloat(m[2]);
  if (!(t >= 28.4)) return line;
  const pos = m[3].split(',').map(Number);
  const look = m[4].split(',').map(Number);
  const [, x, y0, z] = pos;
  let y = y0;
  let fov = needFov(x, y, z).fov;
  if (fov > maxFov) {
    let lo = -4, hi = y0;
    for (let i = 0; i < 90; i++) {
      const mid = (lo + hi) / 2;
      if (needFov(x, mid, z).fov > maxFov) hi = mid; else lo = mid;
    }
    y = (lo + hi) / 2;
    fov = needFov(x, y, z).fov;
  }
  fov = Math.min(maxFov, Math.max(minFov, fov));
  const T = Math.tan((fov * Math.PI) / 360);
  const a = Math.atan2(ringY - y, Math.hypot(x, z - ringZ));
  const pitch = a + Math.atan(-ndcRing * T);
  const lookY = y + Math.tan(pitch) * (z - look[2]);
  return `${m[1]}${m[2]}, [${x}, ${num(y)}, ${z}], [${look[0]}, ${num(lookY)}, ${look[2]}], ${num(fov)}, ${m[6]}, ${m[7]}]${m[8]}`;
});

writeFileSync(path, head + lines.join('\n') + tail);
console.log('updated gameplay camera keys');

