import { createRequire } from 'node:module';
import { mkdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const out = '/tmp/opencode/final-shots';
mkdirSync(out, { recursive: true });
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

async function newPage(mobile) {
  const page = await browser.newPage({
    viewport: mobile ? { width: 390, height: 844 } : { width: 960, height: 600 },
    deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile,
  });
  await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
  return page;
}

async function shot(page, name) {
  await page.screenshot({ path: join(out, name + '.jpg'), type: 'jpeg', quality: 72 });
  console.log('shot', name);
}

async function seek(page, t, steps = 150) {
  await page.evaluate((tt) => window.__cryout.audio.start(tt - 0.25), t);
  await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
  await page.evaluate((n) => {
    const c = window.__cryout;
    c.audio.pause();
    for (let i = 0; i < n; i++) c.scene.animate(1 / 30, c.audio.time, true);
    c.scene.render();
  }, steps);
  await page.waitForTimeout(150);
}

// start screens
for (const mobile of [false, true]) {
  const page = await newPage(mobile);
  await shot(page, mobile ? 'start-mobile' : 'start-desktop');
  await page.close();
}

// cryout gameplay + pause + results
{
  const page = await newPage(false);
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });
  await seek(page, 62);
  await shot(page, 'play-cryout');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  await shot(page, 'pause');
  await page.evaluate(() => { window.__cryout.audio.resume(); });
  await page.click('#resumeBtn');
  await page.evaluate((end) => window.__cryout.audio.start(end - 0.25), 133.3);
  await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: 30000 });
  await page.waitForTimeout(2600);
  await shot(page, 'results-cryout');
  await page.close();
}

// chronostasis pendulum
{
  const page = await newPage(false);
  await page.evaluate(async () => { await window.__cryout.selectTrack('chronostasis'); });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });
  await seek(page, 68.4);
  await shot(page, 'chrono-pendulum');
  await page.close();
}

// boss intro + gameplay
{
  const page = await newPage(false);
  await page.evaluate(async () => { await window.__cryout.selectTrack('untouchable'); });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });
  await seek(page, 12, 40);
  await shot(page, 'boss-intro-12');
  await seek(page, 70);
  await shot(page, 'boss-play-70');
  await seek(page, 120);
  await shot(page, 'boss-play-120');
  await page.close();
}

// boss results
{
  const page = await newPage(false);
  await page.evaluate(async () => { await window.__cryout.selectTrack('untouchable'); });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });
  await page.evaluate((end) => window.__cryout.audio.start(end - 0.25), 141.7);
  await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: 30000 });
  await page.waitForTimeout(2600);
  await shot(page, 'results-boss');
  await page.close();
}

await browser.close();

