import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

const only = process.argv.slice(2);
const ids = only.length ? only : ['cryout', 'world', 'chronostasis', 'untouchable'];
const summary = [];

for (const id of ids) {
  const page = await browser.newPage({ viewport: { width: 800, height: 500 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  try {
    await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });
    await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
    await page.evaluate(async (tid) => { await window.__cryout.selectTrack(tid); }, id);
    await page.click('#startBtn');
    await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 30000 });

    const plan = await page.evaluate(() => {
      const c = window.__cryout;
      const codes = ['KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon'];
      const key = (type, code) => document.dispatchEvent(new KeyboardEvent(type, {
        code, key: code, bubbles: true, cancelable: true,
      }));
      const now = c.audio.time;
      const lanes = Array.from({ length: 8 }, () => []);
      for (const n of c.chart.notes) lanes[n.lane].push(n);
      for (const list of lanes) list.sort((a, b) => a.t - b.t);
      const timers = [];
      const at = (t, fn) => { timers.push(setTimeout(fn, Math.max(0, (t - now) * 1000))); };
      for (let l = 0; l < 8; l++) {
        const list = lanes[l];
        for (let i = 0; i < list.length; i++) {
          const n = list[i];
          const next = list[i + 1];
          at(n.t - 0.012, () => key('keydown', codes[l]));
          const holdEnd = n.type === 'hold' ? n.t + (n.dur || 0) + 0.06 : n.t + 0.06;
          const up = Math.min(holdEnd, next ? next.t - 0.02 : Infinity);
          at(up, () => key('keyup', codes[l]));
        }
      }
      const swings = c.chart.swings || [];
      for (const s of swings) at(s.t - 0.012, () => key('keydown', 'Space'));
      for (const s of swings) at(s.t + 0.06, () => key('keyup', 'Space'));
      return { notes: c.chart.notes.length, holds: c.chart.notes.filter((n) => n.type === 'hold').length, swings: swings.length, end: c.chart.song.chartEnd };
    });
    console.log(`${id}: plan`, JSON.stringify(plan));

    await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: Math.ceil(plan.end * 1000) + 60000 });
    await page.waitForFunction(() => document.getElementById('resultScreen')?.classList.contains('show'), undefined, { timeout: 15000 }).catch(() => {});
    await page.waitForTimeout(1200);
    const out = await page.evaluate(() => {
      const c = window.__cryout;
      const s = c.stats;
      const acc = s.judged ? (s.weight / s.judged) * 100 : 100;
      return {
        state: c.state, judged: s.judged, perfect: s.perfect, great: s.great, good: s.good,
        bad: s.bad, miss: s.miss, dropped: s.dropped, maxCombo: s.maxCombo, score: s.score,
        acc: +acc.toFixed(2), rank: document.getElementById('rank')?.textContent,
        tag: document.getElementById('resultTag')?.textContent,
        delta: document.getElementById('scoreDelta')?.textContent,
      };
    });
    const expected = plan.notes + plan.swings;
    const pass = out.judged === expected && out.miss === 0 && out.dropped === 0 && out.bad === 0;
    console.log(`${id}: ${pass ? 'PASS' : 'FAIL'}`, JSON.stringify(out), errors.length ? 'ERRORS ' + errors.join(' | ') : '');
    summary.push({ id, pass, out, errors });
  } catch (err) {
    console.log(`${id}: EXCEPTION`, err.message, errors.join(' | '));
    summary.push({ id, pass: false, error: err.message, errors });
  }
  await page.close();
}

await browser.close();
console.log('SUMMARY', JSON.stringify(summary.map((s) => ({ id: s.id, pass: s.pass, acc: s.out?.acc, judged: s.out?.judged, miss: s.out?.miss, dropped: s.out?.dropped }))));

