import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

// 1. A zero-score run must not be stored or labelled a best.
{
  const ctx = await browser.newContext({ viewport: { width: 960, height: 600 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 20000 });
  await page.evaluate((end) => window.__cryout.audio.start(end - 0.2), 133.3);
  await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: 30000 });
  await page.waitForFunction(() => document.getElementById('resultScreen')?.classList.contains('show'), undefined, { timeout: 15000 });
  await page.waitForTimeout(1200);
  const info = await page.evaluate(() => ({
    tag: document.getElementById('resultTag')?.textContent,
    delta: document.getElementById('scoreDelta')?.textContent,
    badge: document.getElementById('bestBadge')?.classList.contains('on'),
    bestNote: document.getElementById('bestNote')?.textContent,
    stored: localStorage.getItem('cryout-best-v2'),
    clearCount: document.getElementById('clearCount')?.textContent,
    clearedCards: document.querySelectorAll('.track-card.cleared').length,
  }));
  console.log('zero-score', JSON.stringify(info), errors.length ? 'ERR ' + errors.join('|') : 'ok');
  await ctx.close();
}

