import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const file = process.argv[2] || '/home/runner/work/PlayGround/PlayGround/public/audio/intention.mp3';
const outFile = process.argv[3] || '/tmp/opencode/intent/analysis.json';
const b64 = readFileSync(file).toString('base64');

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
const page = await browser.newPage();
await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });

const result = await page.evaluate(async (b64) => {
  const bin = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const ctx = new OfflineAudioContext(1, 1, 44100);
  const buf = await ctx.decodeAudioData(bin.buffer);
  const sr = buf.sampleRate;
  const ch = buf.numberOfChannels;
  const chans = [];
  for (let c = 0; c < ch; c++) chans.push(buf.getChannelData(c));
  const step = Math.max(1, Math.round(sr / 22050));
  const dsr = sr / step;
  const n = Math.floor(buf.length / step);
  const mono = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    let v = 0;
    for (let c = 0; c < ch; c++) v += chans[c][i * step];
    mono[i] = v / ch;
  }

  // 10 ms RMS onset envelope: positive energy changes emphasise attacks.
  const hop = Math.max(1, Math.round(dsr * 0.01));
  const win = Math.max(2, Math.round(dsr * 0.04));
  const env = [];
  const rms = [];
  let prev = 0;
  for (let i = 0; i + win < mono.length; i += hop) {
    let e = 0;
    for (let k = 0; k < win; k++) { const s = mono[i + k]; e += s * s; }
    e = Math.sqrt(e / win);
    rms.push(e);
    env.push(Math.max(0, e - prev));
    prev = e;
  }
  const fps = dsr / hop;

  const corr = (from, to) => {
    const out = [];
    for (let bpm = from; bpm <= to; bpm += 0.25) {
      const lag = (60 / bpm) * fps;
      const lagI = Math.floor(lag);
      const frac = lag - lagI;
      let s = 0, norm = 0;
      for (let i = lagI + 1; i < env.length; i++) {
        const v = env[i] * ((1 - frac) * env[i - lagI] + frac * env[i - lagI - 1]);
        s += v; norm += env[i] * env[i];
      }
      out.push({ bpm, score: norm ? s / norm : 0 });
    }
    return out;
  };

  const global = corr(70, 220).sort((a, b) => b.score - a.score)[0];

