  const lag = (60 / global.bpm) * fps;
  let phase = 0, phaseScore = -1;
  for (let p = 0; p < lag; p += 0.25) {
    let s = 0;
    for (let i = 0; i < env.length; i++) {
      const d = ((i - p) % lag + lag) % lag;
      if (d < 2.2 || d > lag - 2.2) s += env[i];
    }
    if (s > phaseScore) { phaseScore = s; phase = p; }
  }

  // Windowed tempo: 8 s windows every 2 s.
  const windows = [];
  const secToFrame = (t) => Math.round(t * fps);
  for (let t = 0; t + 8 < n / dsr; t += 2) {
    const a = secToFrame(t), b = secToFrame(t + 8);
    const slice = env.slice(a, b);
    let best = { bpm: 0, score: -1 };
    for (let bpm = 150; bpm <= 210; bpm += 0.5) {
      const l = (60 / bpm) * fps;
      const li = Math.floor(l), fr = l - li;
      let s = 0, norm = 0;
      for (let i = li + 1; i < slice.length; i++) {
        s += slice[i] * ((1 - fr) * slice[i - li] + fr * slice[i - li - 1]);
        norm += slice[i] * slice[i];
      }
      if (norm && s / norm > best.score) best = { bpm, score: s / norm };
    }
    let e = 0;
    for (let i = a; i < b; i++) e += rms[i] || 0;
    windows.push({ t: +t.toFixed(1), bpm: best.bpm, conf: +best.score.toFixed(3), energy: +(e / Math.max(1, b - a)).toFixed(4) });
  }

  // Peaks: local onset maxima with adaptive threshold.
  const mean = env.reduce((a, b) => a + b, 0) / env.length;
  const std = Math.sqrt(env.reduce((a, b) => a + (b - mean) ** 2, 0) / env.length);
  const threshold = mean + std * 0.55;
  const minGap = Math.round(0.055 * fps);
  const peaks = [];
  let last = -minGap;
  for (let i = 2; i < env.length - 2; i++) {
    const v = env[i];
    if (v < threshold) continue;
    if (v < env[i - 1] || v < env[i + 1] || v < env[i - 2] || v < env[i + 2]) continue;
    if (i - last < minGap) {
      if (peaks.length && v > peaks[peaks.length - 1].s) peaks[peaks.length - 1] = { t: i / fps, s: v };
      continue;
    }
    peaks.push({ t: +(i / fps).toFixed(3), s: +v.toFixed(4) });
    last = i;
  }

  // Energy per second for structure reading.
  const perSec = [];
  for (let t = 0; t < buf.duration; t += 1) {
    const a = Math.round(t * dsr), b = Math.min(n, Math.round((t + 1) * dsr));
    let e = 0;
    for (let i = a; i < b; i++) e += mono[i] * mono[i];
    perSec.push(+Math.sqrt(e / Math.max(1, b - a)).toFixed(4));
  }

  return {
    duration: +buf.duration.toFixed(3), sampleRate: sr, channels: ch,
    bpm: global.bpm, bpmConfidence: +global.score.toFixed(3),
    beatOffset: +(phase / fps).toFixed(3),
    windows, peaks, perSec,
    frames: env.length, fps: +fps.toFixed(2),
  };
}, b64);

