  const l = lanes[i];
  let x = (i - 3.5) * v.spacing * v.spread;
  // The 1-lane and 2-lane gimmick sections are centred as a group: lane 3
  // becomes the single centre line, and lanes 2/4 straddle the middle.
  if (state.keyCount === 1) {
    x = i === 3 ? 0 : (i < 3 ? -1 : 1) * v.spacing * 4;
