import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

const skipFirst = process.env.SKIP_NOTE === '1';
const id = process.argv[2] || 'untouchable';
const ctx = await browser.newContext({ viewport: { width: 800, height: 500 } });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
await page.evaluate(async (tid) => { await window.__cryout.selectTrack(tid); }, id);
await page.click('#startBtn');
await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 30000 });

const plan = await page.evaluate((skip) => {
  const c = window.__cryout;
  const codes = ['KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon'];
  const key = (type, code) => document.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));
  const now = c.audio.time;
  const notes = [...c.chart.notes].sort((a, b) => a.t - b.t);
  const first = notes[0];
  const lanes = Array.from({ length: 8 }, () => []);
  for (const n of c.chart.notes) lanes[n.lane].push(n);
  for (const list of lanes) list.sort((a, b) => a.t - b.t);
  const at = (t, fn) => setTimeout(fn, Math.max(0, (t - now) * 1000));
  for (let l = 0; l < 8; l++) {
    const list = lanes[l];
    for (let i = 0; i < list.length; i++) {
      const n = list[i];
      const next = list[i + 1];
      if (!(skip && n === first)) at(n.t - 0.012, () => key('keydown', codes[l]));
      const holdEnd = n.type === 'hold' ? n.t + (n.dur || 0) + 0.06 : n.t + 0.06;
      const up = Math.min(holdEnd, next ? next.t - 0.02 : Infinity);
      at(up, () => key('keyup', codes[l]));
    }
  }
  for (const s of (c.chart.swings || [])) at(s.t - 0.012, () => key('keydown', 'Space'));
  for (const s of (c.chart.swings || [])) at(s.t + 0.06, () => key('keyup', 'Space'));
  return { notes: c.chart.notes.length, swings: (c.chart.swings || []).length, end: c.chart.song.chartEnd };
}, skipFirst);
console.log(id, 'plan', JSON.stringify(plan));

await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: Math.ceil(plan.end * 1000) + 60000 });
await page.waitForFunction(() => document.getElementById('resultScreen')?.classList.contains('show'), undefined, { timeout: 15000 });
await page.waitForTimeout(1200);
const out = await page.evaluate(() => {
  const c = window.__cryout;
  const s = c.stats;
  return {
    judged: s.judged, perfect: s.perfect, great: s.great, miss: s.miss, dropped: s.dropped,
    acc: +((s.weight / s.judged) * 100).toFixed(2), rank: document.getElementById('rank')?.textContent,
    tag: document.getElementById('resultTag')?.textContent,
    delta: document.getElementById('scoreDelta')?.textContent,
    badge: document.getElementById('bestBadge')?.classList.contains('on'),
    stored: localStorage.getItem('cryout-best-v2'),
  };
});
console.log(id, skipFirst ? '(one miss)' : '(perfect)', JSON.stringify(out), errors.length ? 'ERR ' + errors.join('|') : 'ok');

if (process.env.MENU_CHECK === '1') {
  await page.click('#menuBtn');
  await page.waitForFunction(() => window.__cryout.state === 'menu', undefined, { timeout: 15000 });
  const menu = await page.evaluate(() => ({
    clearCount: document.getElementById('clearCount')?.textContent,
    all: document.getElementById('clearCount')?.classList.contains('all'),
    cleared: [...document.querySelectorAll('.track-card.cleared')].map((c) => c.dataset.track),
    cryoutPb: document.querySelector('.track-card[data-track="cryout"] .tc-best')?.textContent,
    bossPb: document.querySelector('.track-card[data-track="untouchable"] .tc-best')?.textContent,
  }));
  console.log('menu', JSON.stringify(menu));
}

await ctx.close();
await browser.close();

