import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

const outDir = '/tmp/opencode/intent/shots';
mkdirSync(outDir, { recursive: true });

const ctx = await browser.newContext({ viewport: { width: 1280, height: 720 } });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
await page.evaluate(async () => { await window.__cryout.selectTrack('intention'); });
await page.click('#startBtn');
await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 30000 });
await page.evaluate(() => { window.__cryout.audio.gain.gain.value = 0.0; });

const marks = [
  ['05-void', 4.5],
  ['17.6-reveal', 17.7],
  ['21-ocean', 21],
  ['30-spin', 30.2],
  ['37-assail', 37],
  ['48-libra', 48],
  ['54-pillars', 54],
  ['62-halo', 62.3],
  ['70-halo-end', 70],
  ['73-dark', 73],
  ['76-guilt', 76],
  ['83-guilt2', 83],
  ['90-offbeat', 90],
  ['96-offbeat2', 96],
  ['102-fast', 102.5],
  ['108-tide', 108],
  ['120-memory', 120],
  ['142-static', 142],
  ['160-determined', 160],
  ['181.5-white', 181.5],
  ['185-fake', 185],
  ['196-fake-late', 196],
  ['205-dawn', 205.2],
];

const report = [];
for (const [name, at] of marks) {
  await page.evaluate(async (t) => {
    const a = window.__cryout.audio;
    await a.start(t + 0.16, { fadeStart: 900, fadeEnd: 901 });
  }, at);
  await page.waitForTimeout(1250);
  const snap = await page.evaluate(() => {
    const doc = document;
    const g = doc.getElementById('guiltFill');
    const sync = doc.querySelector('.sync');
    return {
      t: +window.__cryout.audio.time.toFixed(2),
      phase: window.__cryout.intent.phase,
      guilt: +window.__cryout.intent.guilt.toFixed(1),
      fake: +window.__cryout.intent.fakeValue.toFixed(1),
      fakeOn: window.__cryout.intent.fakeGuilt,
      heart: window.__cryout.intent.heartOn,
      body: doc.body.className,
      guiltWidth: g ? g.style.width : null,
      syncRainbow: !!sync && sync.classList.contains('rainbow'),
      energy: doc.getElementById('energyFill')?.style.height,
      whiteout: doc.getElementById('whiteout')?.classList.contains('on'),
      textOn: doc.getElementById('intentGlitchText')?.classList.contains('on'),
      cam: window.__cryout.scene.camera.position.toArray().map((v) => +v.toFixed(1)),
    };
  });
  report.push({ name, ...snap });
  await page.screenshot({ path: join(outDir, name + '.png') });
  console.log(name, JSON.stringify(snap));
}

console.log('errors', errors.length ? errors.join(' | ') : 'none');
await ctx.close();
await browser.close();

