import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
mkdirSync('/tmp/opencode/intent/shots', { recursive: true });

async function openGame() {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 720 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });
  await page.evaluate(async () => { await window.__cryout.selectTrack('intention'); });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 30000 });
  await page.evaluate(async () => { await window.__cryout.audio.start(74.2 + 0.16, { fadeStart: 900, fadeEnd: 901 }); });
  await page.waitForTimeout(500);
  return { ctx, page, errors };
}

async function schedule(page) {
  const plan = await page.evaluate(() => {
    const c = window.__cryout;
    const codes = ['KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon'];
    const key = (type, code) => document.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));
    const now = c.audio.time;
    const notes = c.chart.notes.filter((n) => n.t >= 74.3 && n.t < 104.2).sort((a, b) => a.t - b.t);
    const lanes = Array.from({ length: 8 }, () => []);
    for (const n of notes) lanes[n.lane].push(n);
    const at = (t, fn) => setTimeout(fn, Math.max(0, (t - now) * 1000));
    for (let l = 0; l < 8; l++) {
      const list = lanes[l];
      for (let i = 0; i < list.length; i++) {
        const n = list[i];
        const next = list[i + 1];
        at(n.t - 0.012, () => key('keydown', codes[l]));
        const holdEnd = n.type === 'hold' ? n.t + (n.dur || 0) + 0.06 : n.t + 0.06;
        at(Math.min(holdEnd, next ? next.t - 0.02 : Infinity), () => key('keyup', codes[l]));
      }
    }
    return { now, notes: notes.length };
  });
  return plan;
}

async function sampleAt(page, target, label) {
  await page.evaluate(async (t) => {
    const now = window.__cryout.audio.time;
    await new Promise((r) => setTimeout(r, Math.max(0, (t - now) * 1000)));
  }, target);
  const snap = await page.evaluate(() => {
    const c = window.__cryout;
    return {
      t: +c.audio.time.toFixed(2),
      guilt: +c.intent.guilt.toFixed(1),
      width: document.getElementById('guiltFill')?.style.width,
      fake: +c.intent.fakeValue.toFixed(1),
      fakeOn: c.intent.fakeGuilt,
      perfect: c.stats.perfect, great: c.stats.great, miss: c.stats.miss,
      body: document.body.className,
      white: document.getElementById('whiteout')?.classList.contains('on'),
      sync: document.querySelector('.sync')?.classList.contains('rainbow'),
      energy: document.getElementById('energyFill')?.style.height,
    };
  });
  console.log(label, JSON.stringify(snap));
  await page.screenshot({ path: `/tmp/opencode/intent/shots/${label}.png` });
  return snap;
}

// 1) perfect play through the guilt run
{
  const { ctx, page, errors } = await openGame();
  console.log('scheduled', await schedule(page));
  await sampleAt(page, 76.6, 'g1-early');
  await sampleAt(page, 80.0, 'g2');
  await sampleAt(page, 84.0, 'g3');
  await sampleAt(page, 89.4, 'g4-offbeat');
  await sampleAt(page, 96.0, 'g5-offbeat2');
  await sampleAt(page, 101.5, 'g6-fast');
  await ctx.close();
  console.log('perfect-run errors', errors.length ? errors.join(' | ') : 'none');
}

// 2) no-play drain + whiteout/fake/dawn checks
{
  const { ctx, page, errors } = await openGame();
  await sampleAt(page, 80.0, 'd1-noplay');
  await sampleAt(page, 84.0, 'd2-noplay');
  // precise whiteout shot
  await page.evaluate(async () => { await window.__cryout.audio.start(181.1 + 0.16, { fadeStart: 900, fadeEnd: 901 }); });
  await page.waitForTimeout(250);
  await sampleAt(page, 181.5, 'w1-white');
  await page.evaluate(async () => { await window.__cryout.audio.start(182.1 + 0.16, { fadeStart: 900, fadeEnd: 901 }); });
  await page.waitForTimeout(500);
  await sampleAt(page, 182.8, 'f1-fake');
  await page.evaluate(async () => { await window.__cryout.audio.start(204.5 + 0.16, { fadeStart: 900, fadeEnd: 901 }); });
  await page.waitForTimeout(900);
  await sampleAt(page, 205.6, 'dawn2');
  await ctx.close();
  console.log('no-play errors', errors.length ? errors.join(' | ') : 'none');
}

await browser.close();

