199: function pickLane(keys, i, variant = 0) {
200:   const set = ACTIVE[keys];
201:   if (keys === 1) return set[0];
202:   if (keys === 2) return set[(i + variant) % 2];
203:   const pats = {
204:     0: [0, 1, 2, 3, 2, 1, 3, 0, 2, 1, 0, 3],
205:     1: [0, 2, 1, 3, 0, 3, 1, 2, 0, 1, 2, 3],
206:     2: [3, 2, 1, 0, 1, 2, 3, 2, 1, 0, 2, 3],
207:     3: [0, 1, 0, 2, 1, 3, 2, 3, 0, 2, 3, 1],
208:   };
209:   const p = pats[variant % 4];
210:   return set[p[i % p.length] % set.length];
211: }
