213: function run(start, end, div, opts = {}) {
214:   const sec = sections.find((s) => start >= s.start && start < s.end);
215:   const out = grid(start, end, sec.bpm, sec.beatOffset, div);
216:   let i = 0;
217:   let added = 0;
218:   for (const t of out) {
219:     const strength = strengthAt(t, 0.065);
220:     const min = opts.min ?? 0;
221:     if (strength < min) { i++; continue; }
222:     // deterministic thinning keeps every phrase breathing instead of filling
223:     // every subdivision of an already dense boss chart
224:     if (opts.keep && hash(t, opts.salt || 1) > opts.keep) { i++; continue; }
225:     if (opts.skip && i % opts.skip === opts.skip - 1) { i++; continue; }
226:     const lane = opts.lane ?? pickLane(sec.keys, i, opts.variant || 0);
227:     if (addTap(t, lane)) added++;
228:     i++;
229:   }
230:   return added;
231: }
