267: // OFFBEAT / OFFBEAT II: two lanes, the gimmick. The accented tap is always the
268: // fourth beat of the bar; the second lane answers on a syncopated off-beat so
269: // the rhythm is deliberately different from the pulse.
270: function offbeatBars(start, end, bpmA, bpmB) {
271:   const times = ramp(start, end, bpmA, bpmB, 4); // sixteenth grid
272:   let bar = 0;
273:   for (let i = 16; i + 15 < times.length; i += 16) {
274:     const base = times[i];
275:     addTap(times[i + 12], 2);             // beat 4 — the required accent
276:     addTap(times[i + 6], 4);              // the "and" of beat 2 — displacement
277:     if (bar % 2 === 1) addTap(times[i + 14], 4); // late sixteenth answer
278:     if (bar % 4 === 3) {
279:       addTap(times[i + 13], 2);
280:       addTap(times[i + 15], 4);
281:     }
282:     bar++;
283:   }
284:   // late gimmick pressure: quick two-lane alternations on the last bar
285:   const tail = times.slice(-12);
286:   tail.forEach((t, i) => {
287:     if (i % 2 === 0) addTap(t, i % 4 === 0 ? 2 : 4);
288:   });
289: }
290: offbeatBars(88, 94, 180, 188);
