// WebAudio engine: exact transport time, suspend-safe pause, tiny hit clicks.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.buffer = null;
    this.source = null;
    this.gain = null;
    this.startAt = 0;
    this.offset = 0;
    this.duration = 0;
    this.loaded = false;
    this.muted = false;
    this.hitGain = null;
    this.cache = new Map();
  }

