import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
const shots = '/tmp/opencode/intent/final';
mkdirSync(shots, { recursive: true });

const ctx = await browser.newContext({ viewport: { width: 1280, height: 720 } });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://127.0.0.1:3003/', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__cryout?.audio?.loaded && window.__cryout.state === 'menu', undefined, { timeout: 60000 });

const menu = await page.evaluate(() => ({
  clear: document.getElementById('clearCount')?.textContent,
  count: document.getElementById('trackCount')?.textContent,
  cards: [...document.querySelectorAll('.track-card')].map((c) => c.dataset.track),
  intentionVisible: !!document.querySelector('.track-card[data-track="intention"]')?.offsetParent,
}));
console.log('MENU', JSON.stringify(menu));
await page.screenshot({ path: join(shots, 'menu.png') });

await page.evaluate(async () => { await window.__cryout.selectTrack('intention'); });
await page.click('#startBtn');
await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 30000 });

// Autoplay the first two movements so the guilt bar is exercised by real hits.
const plan = await page.evaluate(() => {
  const c = window.__cryout;
  const codes = ['KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon'];
  const key = (type, code) => document.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));
  const now = c.audio.time;
  const notes = c.chart.notes.filter((n) => n.t < 106).sort((a, b) => a.t - b.t);
  const lanes = Array.from({ length: 8 }, () => []);
  for (const n of notes) lanes[n.lane].push(n);
  const at = (t, fn) => setTimeout(fn, Math.max(0, (t - now) * 1000));
  for (let l = 0; l < 8; l++) {
    const list = lanes[l];
    for (let i = 0; i < list.length; i++) {
      const n = list[i];
      const next = list[i + 1];
      at(n.t - 0.012, () => key('keydown', codes[l]));
      const holdEnd = n.type === 'hold' ? n.t + (n.dur || 0) + 0.06 : n.t + 0.06;
      at(Math.min(holdEnd, next ? next.t - 0.02 : Infinity), () => key('keyup', codes[l]));
    }
  }
  return { now: +now.toFixed(2), notes: notes.length };
});
console.log('PLAN', JSON.stringify(plan));

async function sampleAt(t, name) {
  await page.evaluate(async (tt) => {
    const now = window.__cryout.audio.time;
    await new Promise((r) => setTimeout(r, Math.max(0, (tt - now) * 1000)));
  }, t);
  const info = await page.evaluate(() => {
    const c = window.__cryout;
    return {
      t: +c.audio.time.toFixed(2),
      section: document.getElementById('sectionName')?.textContent,
      keys: document.getElementById('keysCount')?.textContent,
      phase: c.intent.phase,
      guilt: +c.intent.guilt.toFixed(1),
      fake: +c.intent.fakeValue.toFixed(1),
      fakeOn: c.intent.fakeGuilt,
      heart: c.intent.heartOn,
      notesHidden: !c.scene.noteRoot.visible,
      body: document.body.className,
      white: document.getElementById('whiteout')?.classList.contains('on'),
      yellow: document.getElementById('yellowVignette')?.classList.contains('on'),
      rainbow: document.querySelector('.sync')?.classList.contains('rainbow'),
      syncHeight: document.getElementById('energyFill')?.style.height,
      perfect: c.stats.perfect, great: c.stats.great, miss: c.stats.miss,
    };
  });
  console.log(name, JSON.stringify(info));
  await page.screenshot({ path: join(shots, name + '.png') });
  return info;
}

await sampleAt(75.6, '01-guilt-start');
await sampleAt(80.0, '02-guilt-ready');
await sampleAt(90.0, '03-offbeat');
await sampleAt(93.7, '04-last-offbeat');
await sampleAt(95.2, '05-fastbeat-snap');
await sampleAt(100.4, '06-fastbeat-140');
await sampleAt(103.0, '07-camera-break');

// Jump to the late movements without playing: verify the staged HUD states.
async function seek(t) {
  await page.evaluate(async (tt) => {
    await window.__cryout.audio.start(tt + 0.16, { fadeStart: 900, fadeEnd: 901 });
  }, t);
  await page.waitForTimeout(700);
}
await seek(181.2);
await sampleAt(181.5, '08-whiteout');
await seek(182.2);
await sampleAt(184.0, '09-fake-guilt');
await seek(202.8);
await sampleAt(203.6, '10-fake-shatter');
await seek(204.6);
await sampleAt(205.4, '11-dawn');
await sampleAt(208.0, '12-dawn-wide');

console.log('ERRORS', errors.length ? errors.join(' | ') : 'none');
await ctx.close();
await browser.close();

