.touchicon{width:11px;height:16px;border:1px solid var(--muted);border-radius:3px;position:relative}
.touchicon::after{content:"";position:absolute;left:4px;top:3px;width:2px;height:4px;background:var(--cyan)}
.pendline{color:#e8c982;margin-top:8px}
.pendicon{width:14px;height:14px;border:1px solid currentColor;border-radius:50%;position:relative;box-shadow:0 0 8px rgba(255,209,102,.5)}
.pendicon::after{content:"";position:absolute;left:50%;top:1px;width:1px;height:6px;background:currentColor;transform-origin:50% 100%;transform:rotate(32deg)}
.syslist{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
