    const ahead = lanesAhead(t);
    scene.setPreviewLanes(ahead);
    updateGhostEvents(t);
    updateChartEvents(t);
    updateIntent(dt, t);
    updateSwing(t);
    updateNotes(t);
    updateHUD(t);
