import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 960, height: 540 } });
const file = '/tmp/opencode/uploads/b33eb5db-1b34-4977-a3e1-bdad98c61cb9/Record_2026-11-19-05-01-00.mp4';
const b64 = readFileSync(file).toString('base64');
await page.setContent('<body style="margin:0;background:#000"><video id="v" style="width:100vw;height:100vh;object-fit:contain" muted playsinline></video></body>');
const meta = await page.evaluate(async (b64) => {
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const url = URL.createObjectURL(new Blob([bytes], { type: 'video/mp4' }));
  const v = document.getElementById('v');
  v.src = url;
  await new Promise((res, rej) => { v.onloadedmetadata = res; v.onerror = () => rej(new Error('load ' + v.error?.code)); });
  return { duration: v.duration, w: v.videoWidth, h: v.videoHeight };
}, b64);
console.log('META', JSON.stringify(meta));
const out = '/tmp/opencode/verify/video';
mkdirSync(out, { recursive: true });
const count = 24;
for (let i = 0; i < count; i++) {
  const t = (meta.duration * i) / (count - 1);
  await page.evaluate(async (t) => {
    const v = document.getElementById('v');
    await new Promise((res) => { v.onseeked = res; v.currentTime = Math.min(t, v.duration - 0.03); });
  }, t);
  await page.waitForTimeout(120);
  await page.screenshot({ path: join(out, `f-${t.toFixed(2)}.jpg`), type: 'jpeg', quality: 78 });
}
await browser.close();

