// to the four-lane field.
boundary(28.5, 'spin');
caption(28.8, 'ONE LINE', 'HOLD THE CENTRE', 'DESCENT', 2.4);
cam(28.5, [0, 2.6, 7.2], [0, 1.5, 0], 58, 0, 0.4);
