197: function pickLane(keys, i, variant = 0) {
198:   const set = ACTIVE[keys];
199:   if (keys === 1) return set[0];
200:   if (keys === 2) return set[(i + variant) % 2];
201:   const pats = {
202:     0: [0, 1, 2, 3, 2, 1, 3, 0, 2, 1, 0, 3],
203:     1: [0, 2, 1, 3, 0, 3, 1, 2, 0, 1, 2, 3],
204:     2: [3, 2, 1, 0, 1, 2, 3, 2, 1, 0, 2, 3],
205:     3: [0, 1, 0, 2, 1, 3, 2, 3, 0, 2, 3, 1],
206:   };
207:   const p = pats[variant % 4];
208:   return set[p[i % p.length] % set.length];
209: }
