211: function run(start, end, div, opts = {}) {
212:   const sec = sections.find((s) => start >= s.start && start < s.end);
213:   const out = grid(start, end, sec.bpm, sec.beatOffset, div);
214:   let i = 0;
215:   let added = 0;
216:   for (const t of out) {
217:     const strength = strengthAt(t, 0.065);
218:     const min = opts.min ?? 0;
219:     if (strength < min) { i++; continue; }
220:     // deterministic thinning keeps every phrase breathing instead of filling
221:     // every subdivision of an already dense boss chart
222:     if (opts.keep && hash(t, opts.salt || 1) > opts.keep) { i++; continue; }
223:     if (opts.skip && i % opts.skip === opts.skip - 1) { i++; continue; }
224:     const lane = opts.lane ?? pickLane(sec.keys, i, opts.variant || 0);
225:     if (addTap(t, lane)) added++;
226:     i++;
227:   }
228:   return added;
229: }
