265: // OFFBEAT: two lanes, the gimmick. The accented tap is always the fourth beat
266: // of the bar; the second lane answers on a syncopated off-beat so the rhythm
267: // is deliberately different from the pulse. The second READY then hands the
268: // screen back to a single lane.
269: function offbeatBars(start, end, bpmA, bpmB) {
270:   const times = ramp(start, end, bpmA, bpmB, 4); // sixteenth grid
271:   let bar = 0;
272:   for (let i = 16; i + 15 < times.length; i += 16) {
273:     const base = times[i];
274:     addTap(times[i + 12], 2);             // beat 4 — the required accent
275:     addTap(times[i + 6], 4);              // the "and" of beat 2 — displacement
276:     if (bar % 2 === 1) addTap(times[i + 14], 4); // late sixteenth answer
277:     if (bar % 4 === 3) {
278:       addTap(times[i + 13], 2);
279:       addTap(times[i + 15], 4);
280:     }
281:     bar++;
282:   }
283:   // late gimmick pressure: quick two-lane alternations on the last bar
284:   const tail = times.slice(-12);
285:   tail.forEach((t, i) => {
286:     if (i % 2 === 0) addTap(t, i % 4 === 0 ? 2 : 4);
287:   });
288: }
