/* ============================================================
   INTENTION — guilt HUD, heartbeat, ocean overlays
   ============================================================ */
.track-card[data-track="intention"]{
  border-color:rgba(255,209,102,.30);
  background:linear-gradient(90deg,rgba(255,209,102,.07),rgba(120,190,255,.03));
}
.track-card[data-track="intention"] .tc-tags .thumb{color:#ffe6a3;border-color:rgba(255,209,102,.4)}

#guiltHud{
  position:absolute;left:clamp(14px,2.2vw,30px);bottom:clamp(108px,14.5vh,156px);
  width:clamp(180px,20vw,310px);display:none;flex-direction:column;gap:7px;
  font-family:var(--mono);pointer-events:none;
}
body.guilt-on #guiltHud{display:flex}
body.guilt-on .sync{opacity:0;pointer-events:none}
.guilt-head{display:flex;align-items:flex-end;justify-content:space-between;letter-spacing:.28em}
.guilt-head span{font-size:9px;color:#ff6b84;text-shadow:0 0 16px rgba(255,51,85,.6)}
.guilt-head b{font-size:clamp(24px,3vw,38px);line-height:.82;color:#fff;font-weight:800;
  font-variant-numeric:tabular-nums;text-shadow:0 0 20px rgba(255,51,85,.8)}
.guilt-track{
  position:relative;height:15px;background:rgba(255,51,85,.10);
  border:1px solid rgba(255,90,118,.32);overflow:hidden;
  box-shadow:0 0 0 1px rgba(0,0,0,.5) inset;
}
.guilt-track::after{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:repeating-linear-gradient(90deg,transparent 0 17px,rgba(4,2,8,.8) 17px 20px);
}
.guilt-track i{
  position:absolute;inset:0 auto 0 0;width:100%;display:block;
  background:linear-gradient(90deg,#7d0c24,#ff3355 48%,#ff879c);
  box-shadow:0 0 22px rgba(255,51,85,.8),0 0 6px rgba(255,200,210,.5) inset;
  transition:width .12s linear;
}
.guilt-track u{position:absolute;inset:0;display:block;opacity:0;pointer-events:none;
  background:
    linear-gradient(112deg,transparent 0 44%,rgba(4,2,8,.9) 45% 47%,transparent 48% 100%),
    linear-gradient(68deg,transparent 0 61%,rgba(4,2,8,.85) 62% 64%,transparent 65% 100%);
}
.guilt-copy{font-size:7px;letter-spacing:.18em;color:#8f6170;line-height:1.5;text-transform:uppercase}
body.guilt-fake .guilt-track{border-color:rgba(255,90,118,.55);animation:guilt-crack 1.7s steps(2,end) infinite}
body.guilt-fake .guilt-track u{opacity:1}
body.guilt-fake .guilt-head b{color:#ffd4dc;animation:guilt-flicker 2.1s steps(2,end) infinite}
body.guilt-fake .guilt-copy{color:#a3374b}
@keyframes guilt-crack{0%,100%{transform:translateX(0)}28%{transform:translateX(-1px)}31%{transform:translateX(2px)}34%{transform:translateX(0)}}
@keyframes guilt-flicker{0%,100%{opacity:1}42%{opacity:.55}46%{opacity:1}72%{opacity:.68}}
body:not(.guilt-on):not(.guilt-fake) #guiltHud{display:none}

/* heartbeat line — red, beat-synced, behind the playfield copy */
#heartbeat{
  position:fixed;left:0;right:0;top:44%;height:18vh;z-index:3;pointer-events:none;
  opacity:0;transition:opacity .45s ease;mix-blend-mode:screen;
}
#heartbeat.on{opacity:.72}
#heartbeat svg{width:100%;height:100%;overflow:visible}
#heartbeat path{fill:none;stroke-linecap:round;stroke-linejoin:round}
#heartbeat .hb-glow{stroke:rgba(255,51,85,.35);stroke-width:14;filter:blur(8px)}
#heartbeat .hb-line{stroke:#ff5b73;stroke-width:2.1;filter:drop-shadow(0 0 6px rgba(255,51,85,.9))}
#heartbeat.beat .hb-line{animation:hb-beat .3s ease}
#heartbeat.beat .hb-glow{animation:hb-glow .3s ease}
@keyframes hb-beat{0%{stroke:#fff;stroke-width:3.2}38%{stroke:#ff5b73;stroke-width:2.8}100%{stroke:#ff5b73;stroke-width:2.1}}
@keyframes hb-glow{0%{stroke-width:22;opacity:1}100%{stroke-width:14;opacity:.75}}
body.heartbeat-on #heartbeat{opacity:.68}

/* INTENTIONS glitch title */
#intentGlitchText{
  position:fixed;left:50%;top:43%;z-index:5;transform:translate(-50%,-50%);
  display:flex;flex-direction:column;align-items:center;gap:10px;pointer-events:none;
  opacity:0;visibility:hidden;transition:opacity .2s ease, visibility .2s;
}
#intentGlitchText.on{opacity:1;visibility:visible;animation:intent-shake .4s steps(2,end) infinite}
#intentGlitchText span{
  position:relative;font-family:var(--sans);font-weight:900;
  font-size:clamp(42px,9vw,128px);letter-spacing:.16em;color:#fff;line-height:.9;
  text-shadow:0 0 32px rgba(255,255,255,.38),0 0 90px rgba(120,200,255,.24);
}
#intentGlitchText span::before,#intentGlitchText span::after{
  content:attr(data-text);position:absolute;inset:0;pointer-events:none;
}
#intentGlitchText span::before{color:#ff3355;transform:translate(3px,-2px);clip-path:inset(12% 0 46% 0);opacity:.72}
#intentGlitchText span::after{color:#65e5ff;transform:translate(-3px,2px);clip-path:inset(56% 0 8% 0);opacity:.66}
#intentGlitchText em{font-family:var(--mono);font-style:normal;font-size:9px;letter-spacing:.58em;color:#ffd166;text-indent:.58em}
@keyframes intent-shake{0%,100%{transform:translate(-50%,-50%)}25%{transform:translate(calc(-50% + 2px),calc(-50% - 1px))}50%{transform:translate(calc(-50% - 2px),-50%)}75%{transform:translate(-50%,calc(-50% + 1px))}}

/* screen overlays */
#blackout,#whiteout{position:fixed;inset:0;pointer-events:none;z-index:1;opacity:0;transition:opacity .35s ease}
#blackout{background:#010104}
#blackout.on{opacity:1}
#whiteout{background:#fff;z-index:30;transition:opacity .12s ease}
#whiteout.on{opacity:1}
body.intent-whiteout #hud,body.intent-whiteout #vignette{opacity:0}
body.intent-whiteout #whiteout{opacity:1}
/* The 3D stage goes black for the guilt sections; no DOM overlay is used, so
   the white guilt lane and its notes stay readable above the void. */
body.intent-black #vignette{opacity:.35}

#pads{transition:opacity .4s ease}

#intentStatic{
  position:fixed;inset:0;z-index:3;pointer-events:none;opacity:0;
  background-image:
    repeating-linear-gradient(0deg,rgba(255,255,255,.055) 0 1px,transparent 1px 3px),
    repeating-linear-gradient(90deg,rgba(255,255,255,.035) 0 1px,transparent 1px 5px),
    radial-gradient(circle at 34% 62%,rgba(255,255,255,.16),transparent 26%),
    radial-gradient(circle at 72% 31%,rgba(120,210,255,.13),transparent 24%);
  background-size:100% 100%,100% 100%,170% 170%,190% 190%;
  mix-blend-mode:screen;animation:intent-static .28s steps(2,end) infinite;
  transition:opacity .35s ease;
}
body.static-on #intentStatic{opacity:.55}
body.static-on.static-heavy #intentStatic{opacity:.9}
@keyframes intent-static{0%{background-position:0 0,0 0,0 0,0 0}50%{background-position:0 2px,3px 0,4% 6%,-3% 2%}100%{background-position:0 0,0 0,0 0,0 0}}

#intentScanlines{
  position:fixed;inset:0;z-index:1;pointer-events:none;opacity:0;
  background:
    linear-gradient(90deg,rgba(255,0,60,.10),transparent 12%,transparent 82%,rgba(0,210,255,.10)),
    repeating-linear-gradient(0deg,rgba(255,255,255,.035) 0 1px,transparent 1px 4px);
  mix-blend-mode:screen;transition:opacity .3s ease;
}
body.distort-on #intentScanlines{opacity:.85;animation:intent-roll 2.2s linear infinite}
body.distort-on #scene{filter:saturate(1.15) contrast(1.06)}
@keyframes intent-roll{0%{background-position:0 0,0 0}100%{background-position:0 0,0 48px}}

#yellowVignette{
  position:fixed;inset:0;z-index:1;pointer-events:none;opacity:0;transition:opacity 1.2s ease;
  background:radial-gradient(ellipse at 50% 58%,transparent 30%,rgba(255,209,102,.12) 62%,rgba(255,190,50,.34) 100%);
  mix-blend-mode:screen;
}
#yellowVignette.on{opacity:1}
#rainbowWash{
  position:fixed;inset:0;z-index:1;pointer-events:none;opacity:0;transition:opacity 1.1s ease;
  background:linear-gradient(120deg,rgba(255,80,120,.12),rgba(255,210,80,.12) 22%,rgba(90,255,190,.12) 44%,rgba(80,190,255,.13) 62%,rgba(180,110,255,.13));
  mix-blend-mode:screen;
}
#rainbowWash.on{opacity:1}
body.bright-on #vignette{opacity:.32}

body.guilt-on #judge{color:#ff9dac}
body.guilt-on #comboHud b{color:#fff;text-shadow:0 0 24px rgba(255,51,85,.9),0 0 70px rgba(255,51,85,.45)}
body.guilt-on #comboHud span{color:#ff6b84}

/* rainbow sync bar at the dawn */
.sync.rainbow .sync-label{color:#ffe9a8}
.sync.rainbow .energy{width:8px;background:rgba(255,255,255,.18);box-shadow:0 0 18px rgba(255,255,255,.25)}
.sync.rainbow .energy i{
  background:linear-gradient(0deg,#ff5b73,#ffd166 22%,#9cffb0 44%,#65e5ff 66%,#b18cff 84%,#ff8ad8);
  box-shadow:0 0 18px rgba(255,255,255,.85);
  animation:rainbow-breathe 2.4s ease-in-out infinite;
}
@keyframes rainbow-breathe{0%,100%{filter:saturate(1.1) brightness(1)}50%{filter:saturate(1.5) brightness(1.25)}}

@media (max-width:900px){
  #guiltHud{bottom:clamp(96px,13vh,138px);width:clamp(150px,42vw,230px)}
  .guilt-track{height:13px}
  #intentGlitchText span{font-size:clamp(34px,12vw,78px)}
  #heartbeat{top:40%;height:15vh}
  body.guilt-on #comboHud{left:28%;top:35%}
}

