import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });

const ids = process.argv.slice(2);
const tracks = ids.length ? ids : ['cryout', 'world', 'chronostasis', 'untouchable', 'intention'];
const summary = [];

for (const id of tracks) {
  const page = await browser.newPage({ viewport: { width: 800, height: 500 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  try {
    await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 60000 });
    await page.waitForFunction(() => window.__cryout?.state === 'menu', undefined, { timeout: 60000 });
    await page.evaluate(async (track) => { await window.__cryout.selectTrack(track); }, id);
    await page.waitForFunction(() => window.__cryout.state === 'menu' && !document.getElementById('startBtn').disabled, undefined, { timeout: 60000 });
    await page.click('#startBtn');
    await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 30000 });

    const plan = await page.evaluate(() => {
      const c = window.__cryout;
      const codes = ['KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon'];
      const key = (type, code) => document.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));
      const notes = c.chart.notes.map((n) => ({ ...n }));
      const byLane = Array.from({ length: 8 }, () => []);
      for (const n of notes) byLane[n.lane]?.push(n);
      const now = c.audio.time;
      const at = (t, fn) => setTimeout(fn, Math.max(0, (t - now) * 1000));
      for (let l = 0; l < 8; l++) {
        const list = byLane[l].sort((a, b) => a.t - b.t);
        for (let i = 0; i < list.length; i++) {
          const n = list[i];
          const next = list[i + 1];
          at(n.t - 0.012, () => key('keydown', codes[l]));
          const holdEnd = n.type === 'hold' ? n.t + (n.dur || 0) + 0.06 : n.t + 0.06;
          at(Math.min(holdEnd, next ? next.t - 0.02 : Infinity), () => key('keyup', codes[l]));
        }
      }
      for (const s of (c.chart.swings || [])) at(s.t - 0.01, () => c.swingTap());
      return {
        notes: notes.length,
        holds: notes.filter((n) => n.type === 'hold').length,
        swings: (c.chart.swings || []).length,
        end: c.chart.song.chartEnd,
        now: +now.toFixed(2),
      };
    });
    console.log(id + ': plan ' + JSON.stringify(plan));

    await page.waitForFunction(() => window.__cryout.state === 'results', undefined, { timeout: 280000 });
    const res = await page.evaluate(() => {
      const c = window.__cryout;
      return {
        state: c.state,
        judged: c.stats.judged,
        perfect: c.stats.perfect,
        great: c.stats.great,
        good: c.stats.good,
        bad: c.stats.bad,
        miss: c.stats.miss,
        dropped: c.stats.dropped,
        maxCombo: c.stats.maxCombo,
        score: c.stats.score,
        acc: +(c.stats.judged ? (c.stats.weight / c.stats.judged) * 100 : 0).toFixed(2),
        rank: document.getElementById('rank')?.textContent,
        tag: document.getElementById('resultTag')?.textContent,
        errors: [],
      };
    });
    res.errors = errors;
    const ok = res.miss === 0 && res.dropped === 0 && res.bad === 0 && errors.length === 0;
    console.log(id + (ok ? ': PASS ' : ': CHECK ') + JSON.stringify(res));
    summary.push({ id, ok, res });
  } catch (err) {
    console.log(id + ': FAIL ' + err.message + (errors.length ? ' | ' + errors.join(' | ') : ''));
    summary.push({ id, ok: false, error: err.message });
  }
  await page.close();
}

console.log('SUMMARY ' + JSON.stringify(summary.map((s) => ({ id: s.id, ok: s.ok, miss: s.res?.miss, bad: s.res?.bad, dropped: s.res?.dropped, acc: s.res?.acc, rank: s.res?.rank }))));
await browser.close();

