import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1000, height: 620 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

const probe = () => page.evaluate(() => {
  const visible = (sel) => [...document.querySelectorAll(sel)].map((el) => ({
    sel,
    display: getComputedStyle(el).display,
    visibility: getComputedStyle(el).visibility,
    opacity: getComputedStyle(el).opacity,
    rect: el.getBoundingClientRect().toJSON(),
  }));
  return {
    state: window.__cryout.state,
    time: +window.__cryout.audio.time.toFixed(2),
    body: document.body.className,
    caption: {
      on: document.getElementById('bossCaption').classList.contains('on'),
      title: document.getElementById('bcTitle').textContent,
      visibility: getComputedStyle(document.getElementById('bossCaption')).visibility,
      opacity: getComputedStyle(document.getElementById('bossCaption')).opacity,
    },
    text: visible('#hud .brand, #hud .scoreblock, #hud .trackmeta, #hud .lane-count, #hud .sync-label, #comboHud, #judge, .pad .pk, #guiltHud .guilt-head, #guiltHud .guilt-copy, #intentGlitchText, #toast'),
    graphics: visible('#progressFill, .energy, #guiltFill'),
  };
});

try {
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout?.state === 'menu', undefined, { timeout: 60000 });
  await page.evaluate(async () => { await window.__cryout.selectTrack('intention'); });
  await page.waitForFunction(() => window.__cryout.state === 'menu' && !document.getElementById('startBtn').disabled, undefined, { timeout: 60000 });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', undefined, { timeout: 30000 });
  await page.waitForTimeout(2300);
  console.log('INTRO ' + JSON.stringify(await probe()));
  await page.screenshot({ path: '/tmp/opencode/verify/intent-intro.png' });

  await page.waitForFunction(() => window.__cryout.audio.time >= 18.6, undefined, { timeout: 30000 });
  console.log('PLAY ' + JSON.stringify(await probe()));
  await page.screenshot({ path: '/tmp/opencode/verify/intent-play.png' });

  await page.evaluate(() => {
    Object.defineProperty(window.__cryout.audio, 'time', { configurable: true, get: () => 205.2 });
  });
  await page.waitForTimeout(1200);
  console.log('OUTRO ' + JSON.stringify(await probe()));
  await page.screenshot({ path: '/tmp/opencode/verify/intent-outro.png' });
  console.log('ERRORS ' + JSON.stringify(errors));
} finally {
  await browser.close();
}

