128:     const base = (sectionIndex * 3) % patterns.length;
129:     let groupIdx = 0;
130: 
131:     for (const group of secGroups) {
132:       const variant = patterns[(base + Math.floor(groupIdx / 8)) % patterns.length];
133:       if (group.notes.length > 1) {
134:         const pair = CHORDS[keys][(sectionIndex + groupIdx) % CHORDS[keys].length];
135:         group.notes.forEach((n, j) => {
136:           const lane = lanePos(keys, pair[j % pair.length]);
137:           assigned.push({ ...n, lane });
138:         });
139:       } else {
140:         let pos = variant[groupIdx % variant.length];
141:         let lane = lanePos(keys, pos);
142:         if (lane === prevLane[keys] && group.t - (assigned[assigned.length - 1]?.t ?? -99) < 0.42) {
143:           pos = (pos + 1) % variant.length;
144:           lane = lanePos(keys, pos);
145:         }
146:         assigned.push({ ...group.notes[0], lane });
147:         prevLane[keys] = lane;
148:       }
149:       groupIdx++;
150:     }
151:     assigned.push(...secHolds);
152:   });
153: 
154:   // Drop taps that would overlap a hold in the same lane.
155:   const holdByLane = new Map();
156:   for (const h of holds) {
157:     if (!holdByLane.has(h.lane)) holdByLane.set(h.lane, []);
158:     holdByLane.get(h.lane).push(h);
159:   }
160:   const notes = assigned.filter((n) => {
161:     if (n.type === 'hold') return true;
162:     const list = holdByLane.get(n.lane) || [];
163:     return !list.some((h) => n.t > h.t - 0.12 && n.t < h.t + h.dur + 0.12);
164:   });
