245: function onsetStrength(peaks, t, window = 0.075) {
246:   let best = 0;
247:   for (const p of peaks) {
248:     if (p.t > t + window) break;
249:     if (p.t >= t - window && p.strength > best) best = p.strength;
250:   }
251:   return best;
252: }
