254: function buildWorld() {
255:   const bpm = 120;
256:   const beat = 60 / bpm;
257:   const bar = beat * 4;
258:   const offset = 0.04;
259:   const peaks = [...worldAnalysis.peaks].sort((a, b) => a.t - b.t);
260:   const rng = mulberry32(0x51a7c0de);
261:   const notes = [];
262: 
263:   worldSections.forEach((sec, sectionIndex) => {
264:     const keys = sec.keys;
265:     const patterns = PATTERNS[keys];
266:     const base = (sectionIndex * 2) % patterns.length;
267:     const firstBar = Math.ceil((Math.max(sec.start, sec.firstNote) - offset) / bar - 1e-6);
268:     const lastBar = Math.ceil((sec.end - offset) / bar - 1e-6);
269:     let groupIdx = 0;
270:     let lastLane = -1;
271:     let lastT = -99;
272: 
273:     for (let b = firstBar; b < lastBar; b++) {
274:       const barStart = offset + b * bar;
275:       if (barStart > sec.end - 0.18) continue;
276:       if (barStart + 0.02 < sec.firstNote) continue;
277: 
278:       const energy = sec.energy;
279:       let mask;
280:       if (energy < 0.3) mask = [0, 4];
281:       else if (energy < 0.55) mask = [0, 2, 4, 6];
282:       else if (energy < 0.72) mask = [0, 1, 2, 3, 4, 6];
283:       else if (energy < 0.88) mask = [0, 1, 2, 3, 4, 5, 6, 7];
284:       else mask = [0, 1, 2, 3, 4, 5, 6, 7];
285: 
286:       // A short 16th tail on some high-energy bars keeps the chart hard
287:       // without forcing long thumb-crossing bursts.
288:       const extra16 = energy > 0.85 && b % 4 === 3 ? 6 : -1;
289: 
290:       for (let mi = 0; mi < mask.length; mi++) {
291:         const slot = mask[mi];
292:         const t = barStart + slot * beat / 2;
293:         if (t < sec.firstNote - 0.01 || t > sec.end - 0.12) continue;
294:         const strength = onsetStrength(peaks, t);
295:         const onBeat = slot % 2 === 0;
296:         // Thin quiet off-beats, but never remove the downbeat anchors.
297:         if (!onBeat && strength < 1.55 && energy < 0.84 && rng() < 0.34) continue;
298:         if (onBeat && strength < 1.2 && energy < 0.4 && slot !== 0) continue;
299: 
300:         const variant = patterns[(base + Math.floor(groupIdx / 8)) % patterns.length];
301:         let pos = variant[groupIdx % variant.length];
302:         let lane = lanePos(keys, pos);
303:         if (lane === lastLane && t - lastT < beat * 0.8) {
304:           pos = (pos + 1 + (groupIdx % 2)) % variant.length;
305:           lane = lanePos(keys, pos);
306:         }
307:         notes.push({ t: round(t, 3), lane });
308:         lastLane = lane;
309:         lastT = t;
310:         groupIdx++;
311: 
312:         // occasional two-thumb chord on the downbeat, never on consecutive bars
313:         if (onBeat && slot === 0 && energy > 0.62 && b % 4 === 0) {
314:           const pair = CHORDS[keys][(sectionIndex + Math.floor(b / 4)) % CHORDS[keys].length];
315:           const lanes = [lanePos(keys, pair[0]), lanePos(keys, pair[1])];
316:           if (!lanes.includes(lane)) {
317:             const other = lanes[0] === lane ? lanes[1] : lanes[0];
318:             notes.push({ t: round(t, 3), lane: other });
319:           }
320:         }
321: 
322:         if (slot === extra16) {
323:           const lane2 = lanePos(keys, pos + 1);
324:           const t2 = round(t + beat / 4, 3);
325:           if (lane2 !== lane && t2 < sec.end - 0.05) {
326:             notes.push({ t: t2, lane: lane2 });
327:             lastLane = lane2;
328:             lastT = t2;
329:           }
330:         }
331:       }
332:     }
333: 
334:     // slow holds in the breathing sections
335:     if (sec.energy < 0.55) {
336:       const holdPositions = sec.name === 'BREAK' ? [1, 4] : [0, 2];
337:       holdPositions.forEach((pos, i) => {
338:         const t = round(sec.firstNote + (i + 1) * bar * 2 + beat / 2, 3);
