440: function nearestPeak(peaks, t, window = 0.085) {
441:   let best = null;
442:   let bestD = window;
443:   for (const p of peaks) {
444:     const d = Math.abs(p.t - t);
445:     if (d <= bestD) { bestD = d; best = p; }
446:   }
447:   return best;
448: }
