450: function buildChronostasis() {
451:   const bpm = 99.4;
452:   const beat = 60 / bpm;
453:   const bar = beat * 4;
454:   const offset = 0.323; // downbeat phase derived from the track's onset grid
455:   const step = beat / 4;
456:   const rng = mulberry32(0x0c10c4a7);
457:   const peaks = [...chronoAnalysis.peaks].sort((a, b) => a.t - b.t);
458:   const notes = [];
459:   const swings = [];
460: 
461:   // The clock's two hands live on the two unused lanes (0 and 7). Note
462:   // patterns are built around their tick-tock symmetry, so the chart and the
463:   // background clock share one motif rather than unrelated decoration.
464:   const clockOrder = {
465:     4: [0, 3, 1, 2, 2, 1, 3, 0],
466:     6: [0, 5, 1, 4, 2, 3, 3, 2, 4, 1, 5, 0],
467:   };
468: 
469:   chronoSections.forEach((sec) => {
470:     const keys = sec.keys;
471:     if (sec.swing) {
472:       // STASIS is the antique-clock gimmick: no lane notes, only centre taps
473:       // scheduled where the bob crosses the middle of its swing.
474:       const period = beat * 4;
475:       for (let t = sec.start + period / 4; t < sec.end - beat * 0.5; t += period / 2) {
476:         swings.push({ t: round(t, 3) });
477:       }
478:       return;
479:     }
480:     const startSlot = Math.ceil((Math.max(sec.start, sec.firstNote) - offset) / step - 1e-6);
481:     const endSlot = Math.floor((sec.end - 0.07 - offset) / step - 1e-6);
482:     let lastLane = -1;
483:     let lastT = -99;
484: 
485:     for (let slot = startSlot; slot <= endSlot; slot++) {
486:       const t = offset + slot * step;
487:       const is16 = slot % 2 === 1;
488:       const isBeat = slot % 4 === 0;
489:       const peak = nearestPeak(peaks, t);
490:       const strength = peak ? peak.strength : 0;
