const CHORDS = {
  4: [[0, 2], [1, 3], [0, 3], [1, 2]],
  6: [[0, 2], [1, 4], [0, 5], [2, 4], [1, 3]],
  8: [[0, 3], [1, 5], [2, 6], [4, 7], [0, 6], [1, 4]],
