  ghosts.sort((a, b) => a.t - b.t);

  return {
    song: {
      title: 'CRYOUT', shortTitle: 'CRYOUT', artist: 'ORIGINAL TRACK',
      bpm: 100, duration: 138.1, chartEnd: 133.5, beatOffset: 0.535,
      difficulty: 'ADVANCED', laneLabel: '4 · 6 · 8',
