const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
const trackId = process.argv[2] || 'cryout';
const rate = Number(process.argv[3] || 4);
(async () => {
  const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', (err) => errors.push('PAGEERROR ' + err.message));
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout && window.__cryout.state === 'menu', null, { timeout: 180000 });
  await page.evaluate((id) => window.__cryout.selectTrack(id), trackId);
  await page.waitForFunction(() => window.__cryout && window.__cryout.state === 'menu' && !document.getElementById('startBtn').disabled, null, { timeout: 180000 });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', null, { timeout: 60000 });

  const plan = await page.evaluate((rate) => {
    const c = window.__cryout;
    const audio = c.audio;
    audio.source.playbackRate.value = rate;
    const proto = Object.getPrototypeOf(audio);
    Object.defineProperty(proto, 'time', {
      configurable: true,
      get() { return (this.ctx.currentTime - this.startAt) * rate + this.offset; },
    });
    const keys = ['KeyA','KeyS','KeyD','KeyF','KeyJ','KeyK','KeyL','Semicolon'];
    const fire = (code, type) => document.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));
    const startChart = c.audio.time;
    const startPerf = performance.now();
    const at = (chartT) => startPerf + Math.max(0, (chartT - startChart) / rate) * 1000;
    let scheduled = 0;
    for (const n of c.chart.notes) {
      const downAt = n.t - 0.012;
      if (downAt < startChart) continue;
      const code = keys[n.lane];
      const delay = at(downAt) - performance.now();
      setTimeout(() => fire(code, 'keydown'), Math.max(0, delay));
      const upChart = n.type === 'hold' ? n.t + n.dur - 0.03 : n.t + 0.02;
      const upDelay = at(upChart) - performance.now();
      setTimeout(() => fire(code, 'keyup'), Math.max(8, upDelay));
      scheduled++;
    }
    for (const s of (c.chart.swings || [])) {
      if (s.t < startChart) continue;
      const delay = at(s.t - 0.012) - performance.now();
      setTimeout(() => fire('Space', 'keydown'), Math.max(0, delay));
      setTimeout(() => fire('Space', 'keyup'), Math.max(8, delay) + 20);
    }
    return { scheduled, duration: c.chart.song.duration, chartEnd: c.chart.song.chartEnd, startChart };
  }, rate);
  console.log('plan', trackId, plan);

  const deadline = Date.now() + (plan.chartEnd - plan.startChart) / rate * 1000 + 45000;
  let last = null;
  while (Date.now() < deadline) {
    last = await page.evaluate(() => {
      const c = window.__cryout;
      return { state: c.state, stats: { ...c.stats }, intent: { ...c.intent } };
    });
    if (last.state === 'results' || last.state === 'menu') break;
    await page.waitForTimeout(1000);
  }
  await page.screenshot({ path: `/tmp/opencode/${trackId}-result.png` });
  console.log(trackId, 'final', JSON.stringify(last));
  console.log('errors', errors);
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
