const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const launchOptions = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8')).browser?.launchOptions || {};
(async () => {
  const browser = await chromium.launch({ ...launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__cryout?.state === 'menu', null, { timeout: 180000 });
  await page.evaluate(() => window.__cryout.selectTrack('intention'));
  await page.waitForFunction(() => !document.getElementById('startBtn').disabled, null, { timeout: 180000 });
  await page.click('#startBtn');
  await page.waitForFunction(() => window.__cryout.state === 'playing', null, { timeout: 60000 });

  const rate = 2.5;
  const plan = await page.evaluate((rate) => {
    const c = window.__cryout;
    c.audio.source.playbackRate.value = rate;
    const proto = Object.getPrototypeOf(c.audio);
    Object.defineProperty(proto, 'time', {
      configurable: true,
      get() { return (this.ctx.currentTime - this.startAt) * rate + this.offset; },
    });
    const keys = ['KeyA','KeyS','KeyD','KeyF','KeyJ','KeyK','KeyL','Semicolon'];
    const fire = (code, type) => document.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));
    const startChart = c.audio.time;
    const startPerf = performance.now();
    const at = (t) => startPerf + Math.max(0, (t - startChart) / rate) * 1000;
    for (const n of c.chart.notes) {
      const downAt = n.t - 0.012;
      if (downAt < startChart) continue;
      const code = keys[n.lane];
      setTimeout(() => fire(code, 'keydown'), Math.max(0, at(downAt) - performance.now()));
      const upT = n.type === 'hold' ? n.t + n.dur - 0.03 : n.t + 0.02;
      setTimeout(() => fire(code, 'keyup'), Math.max(8, at(upT) - performance.now()));
    }
    for (const s of (c.chart.swings || [])) {
      if (s.t < startChart) continue;
      setTimeout(() => fire('Space', 'keydown'), Math.max(0, at(s.t - 0.012) - performance.now()));
      setTimeout(() => fire('Space', 'keyup'), Math.max(8, at(s.t - 0.012) - performance.now() + 20));
    }
    return { startChart };
  }, rate);

  await page.waitForFunction(() => window.__cryout.audio.time > 55, null, { timeout: 180000 });
  const info = await page.evaluate(() => {
    const sel = (s) => document.querySelector(s);
    const vis = (s) => {
      const el = sel(s);
      if (!el) return 'missing';
      const cs = getComputedStyle(el);
      return `${cs.display}/${cs.visibility}/${cs.opacity}`;
    };
    const c = window.__cryout;
    return {
      state: c.state,
      time: c.audio.time.toFixed(1),
      body: document.body.className,
      notesHidden: c.intent.notesHidden,
      hud: {
        brand: vis('#hud .brand'),
        score: vis('#hud .scoreblock'),
        track: vis('#hud .trackmeta'),
        lanes: vis('#hud .lane-count'),
        combo: vis('#comboHud'),
        judge: vis('#judge'),
        laneKey: vis('#hud .pad .pk'),
        centerLabel: vis('#hud #centerPad .cp-label'),
        guiltHead: vis('#guiltHud .guilt-head'),
        guiltCopy: vis('#guiltHud .guilt-copy'),
        caption: vis('#bossCaption'),
        glitchText: vis('#intentGlitchText'),
        guiltBar: vis('#guiltHud'),
        heartbeat: vis('#heartbeat'),
      },
    };
  });
  await page.screenshot({ path: '/tmp/opencode/intention-textless.png' });
  console.log(JSON.stringify({ plan, info, errors }, null, 2));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
