234:   // ---------------------------------------------------------------- flowers
235:   const FLOWERS = 340;
236:   const fPos = new Float32Array(FLOWERS * 3);
237:   const fCol = new Float32Array(FLOWERS * 3);
238:   const fBase = new Float32Array(FLOWERS * 3);
239:   const fPhase = new Float32Array(FLOWERS);
240:   const flowerColors = [new THREE.Color(0xffffff), new THREE.Color(0xffe9f4), new THREE.Color(0xfff2c8), new THREE.Color(0xd8ecff)];
241:   for (let i = 0; i < FLOWERS; i++) {
242:     const x = (Math.random() - .5) * 140;
243:     const z = -12 - Math.random() * 118;
244:     const y = -5.32 + Math.random() * .22;
245:     fBase[i * 3] = x; fBase[i * 3 + 1] = y; fBase[i * 3 + 2] = z;
246:     fPos[i * 3] = x; fPos[i * 3 + 1] = y; fPos[i * 3 + 2] = z;
247:     const c = flowerColors[i % flowerColors.length];
248:     fCol[i * 3] = c.r; fCol[i * 3 + 1] = c.g; fCol[i * 3 + 2] = c.b;
249:     fPhase[i] = Math.random() * 6.28;
250:   }
251:   const fGeo = new THREE.BufferGeometry();
252:   fGeo.setAttribute('position', new THREE.BufferAttribute(fPos, 3));
253:   fGeo.setAttribute('color', new THREE.BufferAttribute(fCol, 3));
254:   const fMat = new THREE.PointsMaterial({
255:     size: 1.15, map: T.flower, vertexColors: true, transparent: true, opacity: 0,
256:     depthWrite: false, blending: THREE.NormalBlending, sizeAttenuation: true, fog: false,
257:   });
258:   const flowers = new THREE.Points(fGeo, fMat);
259:   flowers.renderOrder = -12;
260:   root.add(flowers);
261: 
262:   // ---------------------------------------------------------------- libra
263:   const libra = new THREE.Group();
264:   let libraHomeZ = -27;
265:   libra.position.set(0, -5.4, libraHomeZ);
266:   root.add(libra);
267:   const goldMat = new THREE.MeshBasicMaterial({ color: 0xffc54a, transparent: true, opacity: 0, fog: false });
268:   const paleMat = new THREE.MeshBasicMaterial({ color: 0xffefbc, transparent: true, opacity: 0, fog: false });
269:   const darkMat = new THREE.MeshBasicMaterial({ color: 0x6b4a1a, transparent: true, opacity: 0, fog: false });
270:   const libraMats = [goldMat, paleMat, darkMat];
271:   function addCyl(mat, rTop, rBot, h, y, seg = 12) {
272:     const m = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBot, h, seg), mat);
273:     m.position.y = y;
274:     libra.add(m);
275:     return m;
276:   }
277:   addCyl(darkMat, 2.8, 3.5, 0.7, 0.35);
278:   addCyl(goldMat, 2.2, 2.8, 0.5, 0.9);
279:   addCyl(darkMat, 1.25, 2.0, 0.4, 1.32);
280:   addCyl(goldMat, .42, .62, 6.6, 4.8);
281:   addCyl(paleMat, .8, .5, .5, 8.2);
282:   const beam = new THREE.Mesh(new THREE.BoxGeometry(13.6, .34, .44), goldMat);
283:   beam.position.y = 8.7;
284:   libra.add(beam);
285:   const beamCap = new THREE.Mesh(new THREE.SphereGeometry(.42, 10, 8), paleMat);
286:   beamCap.position.y = 8.7;
287:   libra.add(beamCap);
288:   // beam tips
289:   for (const side of [-1, 1]) {
290:     const tip = new THREE.Mesh(new THREE.SphereGeometry(.3, 8, 6), paleMat);
291:     tip.position.set(side * 6.7, 8.7, 0);
292:     libra.add(tip);
293:     // chain with a little sag
294:     const pts = [];
295:     for (let k = 0; k <= 8; k++) {
296:       const p = k / 8;
297:       pts.push(new THREE.Vector3(side * 6.7, 8.7 - p * 4.4 + Math.sin(p * Math.PI) * .42, 0));
298:     }
299:     const line = new THREE.Line(
300:       new THREE.BufferGeometry().setFromPoints(pts),
301:       new THREE.LineBasicMaterial({ color: 0xffd166, transparent: true, opacity: 0, fog: false }),
302:     );
303:     libra.add(line);
304:     libraMats.push(line.material);
305:     const pan = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 1.7, .26, 20), goldMat);
306:     pan.position.set(side * 6.7, 4.05, 0);
307:     libra.add(pan);
308:     const rim = new THREE.Mesh(new THREE.TorusGeometry(2.12, .09, 6, 28), paleMat);
309:     rim.rotation.x = Math.PI / 2;
310:     rim.position.set(side * 6.7, 4.18, 0);
311:     libra.add(rim);
312:     const weight = new THREE.Mesh(new THREE.IcosahedronGeometry(.52, 0), paleMat);
313:     weight.position.set(side * 6.7, 4.5, 0);
314:     libra.add(weight);
315:   }
316:   // top star and halo rings
317:   const halo = new THREE.Group();
318:   halo.position.set(0, 9.9, 0);
319:   libra.add(halo);
320:   const starMat = new THREE.SpriteMaterial({
321:     map: T.star, color: 0xffe7a0, transparent: true, opacity: 0,
322:     depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending, fog: false,
323:   });
324:   const star = new THREE.Sprite(starMat);
325:   star.scale.set(4.2, 4.2, 1);
326:   star.renderOrder = 2;
327:   halo.add(star);
328:   const haloMats = [starMat];
329:   for (let i = 0; i < 3; i++) {
330:     const ring = new THREE.Mesh(
331:       new THREE.TorusGeometry(2.7 + i * 1.05, .055, 4, 64),
332:       new THREE.MeshBasicMaterial({ color: i ? 0xffd166 : 0xfff3cf, transparent: true, opacity: 0, fog: false }),
333:     );
334:     ring.rotation.set(Math.PI / 2 + i * .32, i * .6, i * .2);
335:     halo.add(ring);
336:     haloMats.push(ring.material);
337:   }
338:   const haloGlowMat = new THREE.SpriteMaterial({
339:     map: T.glow, color: 0xffd166, transparent: true, opacity: 0,
340:     depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending, fog: false,
341:   });
342:   const haloGlow = new THREE.Sprite(haloGlowMat);
343:   haloGlow.scale.set(14, 14, 1);
344:   haloGlow.renderOrder = 1;
345:   halo.add(haloGlow);
346:   haloMats.push(haloGlowMat);
347: 
348:   // ---------------------------------------------------------------- pillars
349:   const pillarDefs = [
350:     { x: 0, z: -58, h: 25, w: 2.1, hue: 0x355f8a },   // north
351:     { x: -34, z: -36, h: 17, w: 1.8, hue: 0x294c72 }, // west
352:     { x: 34, z: -36, h: 21, w: 1.9, hue: 0x2c527c },  // east
353:     { x: 0, z: -14, h: 10, w: 1.5, hue: 0x203d5e },   // south
354:   ];
355:   const pillars = [];
356:   for (const d of pillarDefs) {
357:     const g = new THREE.Group();
358:     g.position.set(d.x, -5.6, d.z);
359:     root.add(g);
360:     const solidMat = new THREE.MeshBasicMaterial({ color: d.hue, transparent: true, opacity: 0, fog: false });
361:     const edgeMat = new THREE.MeshBasicMaterial({ color: 0x9fd8ff, transparent: true, opacity: 0, fog: false });
362:     const body = new THREE.Mesh(new THREE.CylinderGeometry(d.w * .83, d.w, 1, 8, 1, true), solidMat);
363:     body.position.y = .5;
364:     g.add(body);
365:     const edge = new THREE.Mesh(new THREE.CylinderGeometry(d.w * .86, d.w * 1.03, 1, 8, 1, true), edgeMat);
366:     edge.position.y = .5;
367:     g.add(edge);
368:     const capMat = new THREE.SpriteMaterial({
369:       map: T.glow, color: 0xbfe6ff, transparent: true, opacity: 0,
370:       depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending, fog: false,
371:     });
372:     const cap = new THREE.Sprite(capMat);
373:     cap.scale.set(4.5, 4.5, 1);
374:     cap.position.y = 1;
375:     g.add(cap);
376:     pillars.push({ group: g, body, edge, cap, mat: solidMat, edgeMat, capMat, def: d, h: 0, flash: 0, grow: 0 });
377:   }
378: 
379:   // ---------------------------------------------------------------- void motes
380:   const MOTES = 420;
381:   const mPos = new Float32Array(MOTES * 3);
382:   const mBase = new Float32Array(MOTES * 3);
383:   const mPhase = new Float32Array(MOTES);
384:   for (let i = 0; i < MOTES; i++) {
385:     const x = (Math.random() - .5) * 64;
386:     const y = -3 + Math.random() * 24;
387:     const z = -26 + Math.random() * 42;
388:     mBase[i * 3] = x; mBase[i * 3 + 1] = y; mBase[i * 3 + 2] = z;
389:     mPos[i * 3] = x; mPos[i * 3 + 1] = y; mPos[i * 3 + 2] = z;
390:     mPhase[i] = Math.random() * 6.28;
391:   }
392:   const mGeo = new THREE.BufferGeometry();
393:   mGeo.setAttribute('position', new THREE.BufferAttribute(mPos, 3));
394:   const mMat = new THREE.PointsMaterial({
395:     size: .34, map: T.glow, color: 0xffffff, transparent: true, opacity: 0,
396:     depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true, fog: false,
397:   });
398:   const motes = new THREE.Points(mGeo, mMat);
399:   motes.renderOrder = 6;
400:   root.add(motes);
401: 
402:   // ---------------------------------------------------------------- memories
403:   const memories = [];
404:   for (let i = 0; i < 18; i++) {
405:     const mat = new THREE.SpriteMaterial({
406:       map: T.glow, color: i % 3 ? 0xff5f7f : 0xffd166, transparent: true, opacity: 0,
407:       depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending, fog: false,
408:     });
409:     const s = new THREE.Sprite(mat);
410:     s.scale.set(.8 + Math.random() * 1.8, .8 + Math.random() * 1.8, 1);
411:     s.renderOrder = -8;
412:     root.add(s);
413:     memories.push({
414:       sprite: s, mat, x: (Math.random() - .5) * 18,
415:       z: -20 - Math.random() * 28,
416:       phase: Math.random() * 6.28,
417:       speed: .5 + Math.random() * .7,
418:     });
419:   }
420: 
421:   // ---------------------------------------------------------------- update
422:   let time = 0;
423:   let pulse = 0;
424: 
425:   function setPhase(phase) {
426:     level.phase = phase;
427:     const t = phaseTable[phase] || phaseTable.off;
428:     target.world = t.world ?? 0;
429:     target.void = t.void ?? 0;
430:     target.flowers = t.flowers ?? 0;
431:     target.pillars = t.pillars ?? 0;
432:     target.halo = t.halo ?? 0;
433:     target.memory = t.memory ?? 0;
434:     target.bright = t.bright ?? 0;
435:     // The guilt/glitch transitions are cuts, not dissolves: black them out on
436:     // the downbeat so no ocean or libra silhouette leaks into the void.
437:     if (phase === 'guilt' || phase === 'fake' || phase === 'offbeat' || phase === 'fastbeat') {
438:       level.world = Math.min(level.world, target.world + 0.01);
439:       level.flowers = Math.min(level.flowers, target.flowers + 0.01);
440:       level.pillars = Math.min(level.pillars, target.pillars + 0.01);
441:       level.halo = Math.min(level.halo, target.halo + 0.01);
442:       level.memory = Math.min(level.memory, target.memory + 0.01);
443:     }
444:   }
445: 
446:   function setActive(on) {
447:     level.active = !!on;
448:     root.visible = !!on;
449:     if (!on) {
450:       level.phase = 'off';
451:       for (const k of Object.keys(target)) target[k] = 0;
452:     }
453:   }
454: 
455:   function beat(power = 1) {
456:     pulse = Math.max(pulse, Math.min(1.4, power));
457:     for (const p of pillars) p.flash = Math.max(p.flash, power * .8);
458:   }
459: 
460:   function glitch(power = 1) {
461:     level.glitch = Math.min(2.2, level.glitch + power);
462:   }
463: 
464:   function update(dt, songTime) {
465:     if (!level.active) return;
466:     time = songTime;
467:     pulse *= Math.exp(-dt * 4.2);
468:     level.glitch *= Math.exp(-dt * 4.8);
469:     for (const k of Object.keys(target)) {
470:       level[k] += (target[k] - level[k]) * (1 - Math.exp(-dt * 2.6));
471:     }
472: 
473:     const world = level.world;
474:     const voidA = level.void;
475:     const gl = level.glitch;
476: 
477:     root.visible = world > .012 || voidA > .012 || level.flowers > .01;
478:     skyMat.opacity = world * (.9 + level.bright * .08);
479:     oceanMat.opacity = world * .94;
480:     T.ocean.offset.x = (time * .005) % 1;
481:     T.ocean.offset.y = (time * .013) % 1;
482:     ocean.position.x = Math.sin(time * .04) * 2;
483: 
484:     // The libra breathes with the pulse and tilts like a real balance.
485:     libra.position.y = -5.4 + Math.sin(time * .38) * .08;
486:     libra.rotation.z = Math.sin(time * .31) * .012 + (pulse * .006);
487:     beam.rotation.z = Math.sin(time * .5) * .025 + Math.sin(time * .17) * .012;
488:     beam.rotation.y = Math.sin(time * .2) * .03;
489:     beamCap.scale.setScalar(1 + pulse * .18);
490:     halo.rotation.y += dt * (1.1 + pulse * 2.2);
491:     halo.rotation.z += dt * .45;
492:     halo.rotation.x = Math.sin(time * .3) * .12;
493:     const hf = level.halo;
494:     star.scale.set(4.2 * (1 + pulse * .16), 4.2 * (1 + pulse * .16), 1);
495:     starMat.opacity = (world * .55 + hf * .4) * (0.85 + pulse * .15);
496:     haloMats[1].opacity = hf * (.5 + pulse * .25);
497:     haloMats[2].opacity = hf * (.32 + pulse * .2);
498:     haloMats[3].opacity = hf * (.2 + pulse * .14);
499:     haloMats[4].opacity = hf * (.07 + pulse * .07);
500:     for (const m of libraMats) {
501:       if (m === goldMat) m.opacity = world * .96;
502:       else if (m === paleMat) m.opacity = world * .92;
503:       else if (m === darkMat) m.opacity = world * .8;
504:       else m.opacity = world * .55;
505:     }
506:     for (const m of haloMats) if (m !== starMat) { /* handled above */ }
507: 
508:     // Clouds drift; a slow parallax keeps the sky from feeling painted on.
509:     for (const c of clouds) {
510:       c.sprite.position.x = c.x + Math.sin(time * .035 + c.phase) * 3.2;
511:       c.sprite.position.y += Math.sin(time * .055 + c.phase) * dt * .12;
512:       c.mat.opacity = world * c.base * (.85 + .15 * Math.sin(time * .2 + c.phase));
513:     }
514: 
515:     // Flowers ride the swell and open up at dawn.
516:     const open = Math.min(1.8, level.flowers);
517:     fMat.opacity = world * Math.min(1, .18 + open * .68);
518:     fMat.size = 1.05 + open * .2;
519:     // The dawn uncovers the whole bloom, not just the petals already on screen.
520:     fGeo.setDrawRange(0, Math.min(FLOWERS, Math.floor(FLOWERS * (.62 + Math.min(.5, open * .36)))));
521:     for (let i = 0; i < FLOWERS; i++) {
522:       const ph = fPhase[i];
523:       const x = fBase[i * 3];
524:       const y = fBase[i * 3 + 1] + Math.sin(time * .75 + ph) * .16 + Math.sin(time * .27 + ph * 2.1) * .1;
525:       const z = fBase[i * 3 + 2];
526:       fPos[i * 3] = x + Math.sin(time * .19 + ph) * .45;
527:       fPos[i * 3 + 1] = y + open * .1;
528:       fPos[i * 3 + 2] = z;
529:     }
530:     fGeo.attributes.position.needsUpdate = true;
531: 
532:     // Pillars grow out of the ocean, then keep a slow ember pulse.
533:     for (const p of pillars) {
534:       const wanted = level.pillars * (1 + Math.sin(time * .33 + p.def.x * .04) * .012);
535:       p.grow += (wanted - p.grow) * (1 - Math.exp(-dt * 1.7));
536:       p.flash *= Math.exp(-dt * 2.4);
537:       const h = Math.max(.001, p.def.h * p.grow);
538:       p.h = h;
539:       p.body.scale.y = h;
540:       p.edge.scale.y = h;
541:       p.body.position.y = h * .5;
542:       p.edge.position.y = h * .5;
543:       p.cap.position.y = h + .4;
544:       p.cap.scale.setScalar((2.6 + pulse * 1.5) * Math.min(1, p.grow * 2));
545:       p.mat.opacity = world * (.3 + p.flash * .5);
546:       p.edgeMat.opacity = world * (.14 + p.flash * .45);
547:       p.capMat.opacity = world * (.04 + p.flash * .2 + pulse * .05);
548:       p.mat.color.set(p.def.hue).lerp(new THREE.Color(0xffd166), Math.min(1, p.flash));
549:       p.edgeMat.color.set(0x9fd8ff).lerp(new THREE.Color(0xfff1c0), Math.min(1, p.flash));
550:     }
551: 
552:     // Memory wisps rise toward the sky during the MEMORY phase.
553:     const mem = level.memory;
554:     for (let i = 0; i < memories.length; i++) {
555:       const m = memories[i];
556:       const cyc = ((time * m.speed + m.phase * 3.1) % 24 + 24) % 24;
557:       const y = -6 + cyc * 1.15;
558:       m.sprite.position.set(
559:         m.x + Math.sin(time * .24 + m.phase) * 1.8,
560:         y,
561:         m.z + Math.cos(time * .18 + m.phase) * 1.2,
562:       );
563:       const fade = Math.sin(Math.min(1, Math.max(0, y / 20)) * Math.PI);
564:       m.mat.opacity = Math.max(0, mem * .5 * fade * (0.7 + 0.3 * Math.sin(time * 3 + m.phase)));
565:       m.sprite.visible = m.mat.opacity > .004;
566:     }
567: 
568:     // Void motes: slow upward drift and drift-around, brightest when there is
569:     // no world behind them.
570:     mMat.opacity = Math.max(voidA, world * .26) * .84;
571:     mMat.size = .3 + voidA * .08;
572:     for (let i = 0; i < MOTES; i++) {
573:       const ph = mPhase[i];
574:       mPos[i * 3] = mBase[i * 3] + Math.sin(time * .11 + ph) * 1.7;
575:       mPos[i * 3 + 1] = mBase[i * 3 + 1] + Math.sin(time * .17 + ph * 1.7) * 1.3
576:         + ((time * (0.16 + (i % 5) * .035) + ph * 2.4) % 22) - 8;
577:       mPos[i * 3 + 2] = mBase[i * 3 + 2] + Math.cos(time * .09 + ph) * 1.3;
578:     }
579:     mGeo.attributes.position.needsUpdate = true;
580: 
581:     // world glitch: cramped, jittered geometry during the fracture sections
582:     if (gl > .005) {
583:       const k = gl * .12;
584:       libra.position.x = (Math.random() - .5) * k;
585:       libra.position.z = libraHomeZ + (Math.random() - .5) * k;
586:       for (const c of clouds) c.sprite.position.x += (Math.random() - .5) * k * .4;
587:       sky.rotation.z = (Math.random() - .5) * gl * .01;
588:     } else {
589:       libra.position.x *= .92;
590:       libra.position.z = libraHomeZ + (libra.position.z - libraHomeZ) * .92;
591:       sky.rotation.z *= .9;
592:     }
593:   }
594: 
595:   function layout(portrait) {
596:     level.portrait = portrait;
597:     const s = portrait ? .92 : 1.35;
598:     libra.scale.setScalar(s);
599:     libraHomeZ = portrait ? -36 : -27;
600:     libra.position.z = libraHomeZ;
601:     libra.position.y = -5.4;
602:     sky.scale.setScalar(portrait ? 1.15 : 1);
603:     pillars[0].group.position.z = portrait ? -64 : -58;
604:     pillars[1].group.position.x = portrait ? -27 : -34;
605:     pillars[2].group.position.x = portrait ? 27 : 34;
606:     halo.position.y = portrait ? 9.4 : 9.9;
607:     for (const c of clouds) {
608:       const k = portrait ? .82 : 1;
609:       c.sprite.scale.set(c.sx * k, c.sy * k, 1);
610:     }
611:   }
612: 
613:   return { root, setPhase, setActive, update, beat, glitch, layout, level };
614: }

import { TRACKS, DEFAULT_TRACK_ID, TRACK_BY_ID } from './tracks.js';
import { createScene } from './scene.js';
import { AudioEngine } from './audio.js';

// ---------------------------------------------------------------- constants
const KEYMAP = {
  KeyA: 0, KeyS: 1, KeyD: 2, KeyF: 3, KeyJ: 4, KeyK: 5, KeyL: 6, Semicolon: 7,
  Numpad1: 0, Numpad2: 1, Numpad3: 2, Numpad4: 3, Numpad5: 4, Numpad6: 5, Numpad7: 6, Numpad8: 7,
};
