function applyIntentHud(ev) {
  const on = ev.on !== false;
  switch (ev.hud) {
    case 'clear':
      clearIntentClasses();
      intent.guiltOn = false;
      intent.fakeGuilt = false;
      intent.heartOn = false;
      intent.screenGlitch = false;
      intent.forceSync = false;
      if (intent.notesHidden) setIntentNotesHidden(false);
      break;
    case 'black':
      // The 3D stage itself goes to black for the guilt sections; the class
      // only tints the HUD so the lanes stay readable on the pure void.
      document.body.classList.toggle('intent-black', on);
      break;
    case 'guilt':
      intent.guiltOn = on;
      intent.fakeGuilt = false;
      if (on) intent.guilt = ev.value ?? 100;
      document.body.classList.toggle('guilt-on', on);
      document.body.classList.remove('guilt-fake');
      if (dom.guiltCopy) dom.guiltCopy.textContent = 'CONSISTENT PERFECTS KEEP IT FULL';
      paintGuilt();
      break;
    case 'fakeGuilt':
      intent.fakeGuilt = on;
      intent.guiltOn = on;
      if (on) {
        intent.fakeBase = ev.value ?? 14;

        intent.fakeBase = ev.value ?? 14;
        intent.fakeValue = intent.fakeBase;
        intent.fakeStart = audio.time;
      }
      document.body.classList.toggle('guilt-fake', on);
      document.body.classList.toggle('guilt-on', on);
      if (dom.guiltCopy) dom.guiltCopy.textContent = 'IT WILL NOT REFILL';
      paintGuilt();
      break;
    case 'heartbeat':
      intent.heartOn = on;
      if (ev.bpm) intent.heartBpm = ev.bpm;
      intent.hbAcc = 0;
      if (on) {
        intent.hbBeat = -1;
        setHeartbeatPosition(0);
      } else {
        intent.hbBeat = -1;
      }
      dom.heartbeat?.classList.toggle('on', on);
      document.body.classList.toggle('heartbeat-on', on);
      break;
    case 'glitch':
      intent.screenGlitch = on;
      document.body.classList.toggle('intent-glitch', on);
      break;
    case 'text':
      if (selectedTrack.theme === 'intention'
        && String(ev.text || '').trim().toUpperCase() !== 'INTENTION') break;
      if (on) showIntentText(ev.text, ev.sub, ev.hold ?? 3.2);
      else dom.intentText?.classList.remove('on');
      break;
    case 'static':
      document.body.classList.toggle('static-on', on);
      document.body.classList.toggle('static-heavy', on && (ev.power ?? 0) >= 0.9);
      // The memory movement keeps a thin, transparent veil; the later STATIC
      // section is the one that thickens into real interference.
      document.body.classList.toggle('static-soft', on && (ev.power ?? 0) < 0.9);
      break;
    case 'distort':
      document.body.classList.toggle('distort-on', on);
      break;
    case 'bright':
      document.body.classList.toggle('bright-on', on);
      break;
    case 'white':
      dom.whiteout?.classList.toggle('on', on);
      document.body.classList.toggle('intent-whiteout', on);
      break;
    case 'yellow':
      document.body.classList.toggle('intent-yellow', on);
      dom.yellow?.classList.toggle('on', on);
      break;
    case 'rainbow':
      intent.forceSync = on;
      dom.syncEl?.classList.toggle('rainbow', on);
      dom.rainbow?.classList.toggle('on', on);
      if (on) dom.energy.style.height = '100%';
      break;
    default:
      break;
  }
}

function applyIntentEvent(ev) {
  if (ev.mode === 'phase') {
    intent.phase = ev.phase;
    scene.setIntentionPhase(ev.phase);
    // The dawn is note-less; the lane field stays on so the ocean can breathe.
    setIntentNotesHidden(ev.phase === 'dawn');
    return;
  }
  if (ev.mode === 'hud') applyIntentHud(ev);
}

function intentJudged(kind) {
  if (!intent.guiltOn || intent.fakeGuilt) return;
  const gain = kind === 'perfect' ? 1.35
    : kind === 'great' ? 0.95
    : kind === 'good' ? 0.5
    : kind === 'bad' ? -2.2
    : -6;
  intent.guilt = Math.max(0, Math.min(100, intent.guilt + gain));
  paintGuilt();
}

function updateIntent(dt, t) {
  if (intent.guiltOn && !intent.fakeGuilt) {
    // The bar drains faster while a stream is coming and slows down when the
    // chart thins out, so sparse phrases never punish the player for waiting.
    let ahead = 0;
    for (const n of noteObjects) {
      if (n.state === 'pending' && n.data.t >= t && n.data.t < t + 2.4) ahead++;
    }
    const density = ahead / 2.4;
    const drain = 0.5 + Math.min(1.5, density * 0.55);
    intent.guilt = Math.max(0, Math.min(100, intent.guilt - drain * dt));
    paintGuilt();
  }
  if (intent.fakeGuilt) {
    // Tie the decorative drain to the song clock, not frame time, so it still
    // reaches the shatter point on slow devices.
    const age = Math.max(0, audio.time - intent.fakeStart);
    intent.fakeValue = Math.max(2.6, intent.fakeBase - age * 0.5);
    paintGuilt();
  }
  if (intent.heartOn) {
    intent.hbAcc += dt;
    const interval = 60 / Math.max(40, intent.heartBpm);
    if (intent.hbAcc >= interval) {
      intent.hbAcc %= interval;
      // bottom → middle → top on successive beats, then repeat. The CSS
      // transition carries the line between positions while the ripple and
      // ECG flash fire on the beat itself.
      intent.hbBeat = (intent.hbBeat + 1) % 3;
      setHeartbeatPosition(intent.hbBeat);
      const el = dom.heartbeat;
      if (el) {
        el.classList.remove('beat');
        void el.offsetWidth;
        el.classList.add('beat');
      }
    }
  } else {
    intent.hbAcc = 0;
  }
  if (intent.screenGlitch) {
    intent.glitchAcc += dt;
    if (intent.glitchAcc > 0.52 + Math.random() * 0.4) {
      intent.glitchAcc = 0;
      scene.bossGlitch(0.32 + Math.random() * 0.3);
      glitchScreen(0.45);
    }
  }
}

function updateSection(sec, force = false) {
  if (!sec || (!force && sec === currentSection)) return;
  currentSection = sec;
  scene.setSection(sec);
  if (sec.bpm) scene.setTempo(sec.bpm, sec.beatOffset ?? 0);
  noteSpeed = SPEED * (sec.noteSpeed || 1);
  dom.section.textContent = sec.name;
  dom.keys.textContent = sec.keys;
  if (dom.hudBpm && sec.bpm) dom.hudBpm.textContent = `${Number(sec.bpm).toFixed(1).replace(/\.0$/, '')} BPM`;
  const active = new Set(activeLanesFor(sec.keys));
  for (const pad of dom.pads) {
    const lane = Number(pad.dataset.lane);
    const live = active.has(lane);
    pad.classList.toggle('active', live);
    pad.classList.toggle('sleep', !live);
    pad.setAttribute('aria-hidden', String(!live));
    pad.tabIndex = live ? 0 : -1;
  }
  document.documentElement.style.setProperty('--cyan', sec.color);
  document.documentElement.style.setProperty('--magenta', sec.accent);
  if (!force) {
    // The boss overture uses full-screen title cards instead of lane toasts.
    if (!(selectedTrack.boss && sec.intro)) toast(`${sec.name} // ${sec.keys} LANES`, 1100);
    scene.state.shake = Math.min(0.12, scene.state.shake + 0.035);
  }
}

function findSection(t) {
  const ss = chart.sections;
  for (let i = ss.length - 1; i >= 0; i--) {
    if (t >= ss[i].start) return { index: i, sec: ss[i] };
  }
  return { index: 0, sec: ss[0] };
}

// ---------------------------------------------------------------- judging
function judgeHit(note, offset) {
  const a = Math.abs(offset);
  let kind;
  if (a <= WIN.perfect) kind = 'perfect';
  else if (a <= WIN.great) kind = 'great';
  else if (a <= WIN.good) kind = 'good';
  else kind = 'bad';

  stats[kind]++;
  stats.judged++;
  stats.weight += WEIGHT[kind];
  stats.score += SCORE[kind];
  stats.health = Math.min(100, stats.health + (kind === 'perfect' ? 1.1 : kind === 'great' ? .8 : kind === 'good' ? .4 : -1.6));
  intentJudged(kind);

  if (kind === 'bad') {
    setCombo(0, false);
  } else {
    setCombo(stats.combo + 1);
  }

  if (note.type === 'hold') {
    note.state = 'holding';
    note.endTime = note.data.t + note.data.dur;
    note.tickAt = audio.time;
    note.head.visible = false;
    holdNote[note.lane] = note;
  } else {
    note.state = 'done';
    note.group.visible = false;
  }

  const text = kind === 'perfect' ? 'PERFECT' : kind === 'great' ? 'GREAT' : kind === 'good' ? 'GOOD' : 'BAD';
  showJudge(kind, text);
  scene.hitFx(note.lane, kind);
  audio.click(note.lane, kind === 'perfect' ? 0.52 : 0.38);
}

function missNote(note) {
  if (note.state !== 'pending') return;
  note.state = 'miss';
  note.group.visible = false;
  stats.miss++;
  stats.judged++;
  stats.health = Math.max(0, stats.health - 5);
  setCombo(0, false);
  showJudge('miss', 'MISS');
  scene.missFx(note.lane);
  audio.thud();
  intentJudged('miss');
}

function dropHold(note) {
  if (note.state !== 'holding') return;
  note.state = 'dropped';
  note.group.visible = false;
  holdNote[note.lane] = null;
  stats.dropped++;
  stats.miss++;
  stats.judged++;
  stats.health = Math.max(0, stats.health - 4);
  setCombo(0, false);
  showJudge('miss', 'HOLD LOST');
  scene.missFx(note.lane);
  audio.thud();
  intentJudged('miss');
}

function completeHold(note) {
  if (note.state !== 'holding') return;
  note.state = 'done';
  note.group.visible = false;
  holdNote[note.lane] = null;
  stats.score += 450;
  stats.health = Math.min(100, stats.health + 1.2);
  scene.pressFx(note.lane);
  scene.hitFx(note.lane, 'great');
}

function nearestNote(t, lane = null) {
  let best = null;
  let bestAbs = Infinity;
  for (const n of noteObjects) {
    if (n.state !== 'pending') continue;
    if (lane !== null && n.lane !== lane) continue;
    const d = t - n.data.t;
    if (d < -EARLY_WINDOW || d > HIT_WINDOW) continue;
    const a = Math.abs(d);
    // `<` (not `<=`) keeps the first note on a tied chord: the next finger
    // then claims the second one instead of stacking both on one tap.
    if (a < bestAbs - 1e-6) { bestAbs = a; best = n; }
  }
  return best;
}

function flashPad(lane) {
  const pad = dom.pads[lane];
  if (!pad) return;
  pad.classList.add('pressed');
  clearTimeout(padFlashTimers[lane]);
  padFlashTimers[lane] = setTimeout(() => pad.classList.remove('pressed'), 90);
}

function hitNote(note, t) {
  flashPad(note.lane);
  scene.pressFx(note.lane);
  judgeHit(note, t - note.data.t);
}

// Global tap: ignores the lane under the finger and always takes the single
// note closest to the timing line.
function pressGlobal() {
  if (gameState !== 'playing') return;
  const t = audio.time;
  if (t < 0) return;
  const best = nearestNote(t);
  if (!best) {
    audio.click(3, 0.07);
    return;
  }
  hitNote(best, t);
}

// Kept for automated tests and the keyboard fallback: a lane-scoped tap still
// takes only one note.
function pressLane(lane) {
  if (gameState !== 'playing') return;
  const t = audio.time;
  if (t < 0) return;
  const best = nearestNote(t, lane);
  if (!best) {
    scene.pressFx(lane);
    audio.click(lane, 0.1);
    return;
  }
  hitNote(best, t);
}

function releaseHolds() {
  if (gameState !== 'playing' || inputHeld()) return;
  const active = holdNote.filter((n) => n && n.state === 'holding');
  for (const n of active) {
    holdNote[n.lane] = null;
    if (audio.time < n.endTime - 0.12) dropHold(n);
    else completeHold(n);
  }
}

function releaseLane(lane) {
  if (gameState !== 'playing') return;
  const n = holdNote[lane];
  if (!n) return;
  // Another finger or key still held keeps every active hold alive.
  if (touching()) return;
  holdNote[lane] = null;
  if (audio.time < n.endTime - 0.12) dropHold(n);
  else completeHold(n);
}

// ---------------------------------------------------------------- pendulum
// The STASIS gimmick is judged separately from the lane notes: the bob crosses
// the centre on a fixed swing grid, and the player taps the centre target.
function startPendulum(ev) {
  if (!swingNotes.length) return;
  swingMode = true;
  scene.startPendulum({
    start: ev.t,
    period: ev.period ?? 2.4146,
    amplitude: ev.amplitude ?? 0.42,
    times: swingNotes.map((n) => n.t),
  });
  document.body.classList.add('pendulum');
  dom.centerPad.classList.add('show');
  dom.centerPad.setAttribute('aria-hidden', 'false');
  alignCenterPad();
  toast('STASIS // TAP THE CENTRE', 1800);
}

function endPendulum() {
  swingMode = false;
  scene.stopPendulum();
  document.body.classList.remove('pendulum');
  if (dom.centerPad) {
    dom.centerPad.classList.remove('show', 'pressed');
    dom.centerPad.setAttribute('aria-hidden', 'true');
  }
}

function alignCenterPad() {
  if (!swingMode || !dom.centerPad) return;
  const p = scene.pendulumTargetScreen();
  const size = Math.max(140, p.radius * 2);
  dom.centerPad.style.left = p.x.toFixed(1) + 'px';
  dom.centerPad.style.top = p.y.toFixed(1) + 'px';
  dom.centerPad.style.width = size.toFixed(1) + 'px';
  dom.centerPad.style.height = size.toFixed(1) + 'px';
}

function judgeSwing(note, offset) {
  const a = Math.abs(offset);
  let kind;
  if (a <= WIN.perfect) kind = 'perfect';
  else if (a <= WIN.great) kind = 'great';
  else if (a <= WIN.good) kind = 'good';
  else kind = 'bad';

  note.state = 'done';
  stats[kind]++;
  stats.judged++;
  stats.weight += WEIGHT[kind];
  stats.score += SCORE[kind];
  stats.health = Math.min(100, stats.health + (kind === 'perfect' ? 1.2 : kind === 'great' ? .9 : kind === 'good' ? .5 : -1.4));

  if (kind === 'bad') setCombo(0, false);
  else setCombo(stats.combo + 1);

  showJudge(kind, kind === 'perfect' ? 'PERFECT' : kind === 'great' ? 'GREAT' : kind === 'good' ? 'GOOD' : 'BAD');
  scene.swingResolve(note.index, 'hit');
  audio.click(3, kind === 'perfect' ? 0.56 : 0.4);
}

function missSwing(note) {
  if (note.state !== 'pending') return;
  note.state = 'miss';
  stats.miss++;
  stats.judged++;
  stats.health = Math.max(0, stats.health - 5);
  setCombo(0, false);
  showJudge('miss', 'MISS');
  scene.swingResolve(note.index, 'miss');
  audio.thud();
}

function updateSwing(t) {
  if (!swingMode) return;
  for (const n of swingNotes) {
    if (n.state === 'pending' && t > n.t + HIT_WINDOW) missSwing(n);
  }
}

function swingTap() {
  if (gameState !== 'playing' || !swingMode) return;
  const t = audio.time;
  let best = null;
  let bestAbs = Infinity;
  for (const n of swingNotes) {
    if (n.state !== 'pending') continue;
    const d = t - n.t;
    if (d < -EARLY_WINDOW || d > HIT_WINDOW) continue;
    const a = Math.abs(d);
    if (a < bestAbs) { bestAbs = a; best = n; }
  }
  if (!best) {
    scene.swingWhiff();
    audio.click(3, 0.1);
    return;
  }
  judgeSwing(best, t - best.t);
}

}

// ---------------------------------------------------------------- note render
const SPEED = 8.4;
let noteSpeed = SPEED;

function updateNotes(t) {
  const ns = scene.noteScale;
  for (const n of noteObjects) {
    if (n.state === 'pending') {
      const y = (n.data.t - t) * noteSpeed;
      if (n.free) {
        // Boss notes fly along a curved stage-space path and converge on the
        // lane ring exactly at the hit line.
        const pose = scene.freeNotePose(n.lane, y, n.index);
        n.group.position.set(pose.x, pose.y, pose.z);
      } else {
        // local lane space: the lane frame supplies the diagonal world position
        n.group.position.set(0, y, 0.24);
      }
      n.group.visible = y < 14.5 && y > -1.3;
      n.head.scale.set(1.04 * ns, 1.04 * ns, 1);
      if (n.body) {
        const len = n.data.dur * noteSpeed;
        n.body.visible = n.group.visible;
        n.tail.visible = n.group.visible;
        n.body.scale.set(0.52 * ns, len, 1);
        n.body.position.y = len / 2;
        n.body.material.rotation = n.free ? 0 : -scene.laneScreenAngle(n.lane);
        n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
        n.tail.position.y = len;
      }
      if (t > n.data.t + HIT_WINDOW && gameState === 'playing') missNote(n);
    } else if (n.state === 'holding') {
      if (!held[n.lane] && !touching()) { dropHold(n); continue; }
      if (t >= n.endTime - 0.02) {
        completeHold(n);
        continue;
      }
      const remain = Math.max(0, (n.endTime - t) * noteSpeed);
      n.group.visible = true;
      if (n.free) {
        const pose = scene.freeNotePose(n.lane, 0, n.index);
        n.group.position.set(pose.x, 0.02, pose.z);
      } else {
        n.group.position.set(0, 0.02, 0.24);
      }
      n.head.visible = false;
      if (n.body) {
        n.body.visible = remain > 0.03;
        n.body.scale.set(0.52 * ns, remain, 1);
        n.body.position.y = remain / 2;
        n.body.material.rotation = n.free ? 0 : -scene.laneScreenAngle(n.lane);
        n.tail.visible = remain > 0.4;
        n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
        n.tail.position.y = remain;
      }
      if (t > n.tickAt) {
        n.tickAt = t + 0.12;
        stats.score += 24;
        stats.health = Math.min(100, stats.health + 0.06);
      }
    } else {
      n.group.visible = false;
    }
  }
}

// ---------------------------------------------------------------- game flow
async function startGame() {
  if (!audio.loaded) return;
  resultToken++;
  dom.start.classList.remove('show');
  dom.result.classList.remove('show');
  dom.resultLoading.classList.remove('show');
  dom.pause.classList.remove('show');
  dom.hud.classList.remove('hidden');
  dom.hud.setAttribute('aria-hidden', 'false');
  document.body.classList.add('playing');
  hideCaption();
  dom.bossGlitch?.classList.remove('on');
  if (selectedTrack.boss) {
    scene.setBoss('intro', selectedTrack.theme || 'untouchable');
    setBossIntro(true);
  } else {
    scene.setBoss('off', selectedTrack.theme || 'untouchable');
    setBossIntro(false);
  }
  setIntentPresentation(selectedTrack.theme === 'intention', true);
  resetGame();
  gameState = 'starting';
  try {
    await audio.start(0, { fadeStart: selectedTrack.fadeStart, fadeEnd: selectedTrack.fadeEnd });
    gameState = 'playing';
    if (!selectedTrack.boss) toast(`LISTEN // ${chart.sections[0].keys} LANES`, 1500);
  } catch (err) {
    console.error(err);
    gameState = 'menu';
    document.body.classList.remove('playing');
    dom.hud.classList.add('hidden');
    dom.start.classList.add('show');
    dom.startLabel.textContent = 'AUDIO ERROR';
    toast('AUDIO COULD NOT START', 3000);
  }
}

function pauseGame() {
  if (gameState !== 'playing') return;
  gameState = 'paused';
  audio.pause();
  dom.pause.classList.add('show');
}

async function resumeGame() {
  if (gameState !== 'paused') return;
  audio.resume();
  dom.pause.classList.remove('show');
  gameState = 'playing';
}

function quitToMenu() {
  resultToken++;
  gameState = 'menu';
  gameOver.active = false;
  gameOver.finished = false;
  gameOver.elapsed = 0;
  document.body.classList.remove('game-over');
  scene.resetGameOver();
  audio.stop();
  audio.resume();
  dom.pause.classList.remove('show');
  dom.result.classList.remove('show');
  dom.resultLoading.classList.remove('show');
  dom.hud.classList.add('hidden');
  dom.hud.setAttribute('aria-hidden', 'true');
  dom.start.classList.add('show');
  document.body.classList.remove('playing');
  scene.setSection(chart.sections[0]);
  scene.setTempo(chart.song.bpm, chart.song.beatOffset);
  scene.setCity(chart.sections[0].city || 0);
  scene.setBoss(selectedTrack.boss ? 'preview' : 'off', selectedTrack.theme || 'untouchable');
  scene.setPreviewLanes(new Set());
  setBossIntro(false);
  setIntentPresentation(false);
  hideCaption();
  dom.bossGlitch?.classList.remove('on');
  resetIntentHud();
  for (const n of noteObjects) n.group.visible = false;
  held.fill(false);
  holdNote.fill(null);
  touchPoints.clear();
  keysHeld.clear();
  ghostCursor = 0;
  eventCursor = 0;
  scene.clearGhosts();
  scene.clockReset();
  endPendulum();
  scene.pendulumReset();
  if (selectedTrack.id === 'chronostasis') scene.setClock('run', 0.4);
  for (const p of dom.pads) p.classList.remove('pressed', 'active', 'sleep');
  document.documentElement.style.setProperty('--cyan', '#5ee7ff');
  document.documentElement.style.setProperty('--magenta', '#ff5fd2');
}

function rankFor(acc, judged) {
  if (judged === 0) return 'F';
  if (acc >= 99.5) return 'S+';
  if (acc >= 98) return 'S';
  if (acc >= 93) return 'A';
  if (acc >= 86) return 'B';
  if (acc >= 76) return 'C';
  return acc < 50 ? 'F' : 'D';
}

function comboGraphPath(history, peak) {
  const w = 320, h = 116;
  const pts = history.length ? history : [0, 0, 0, 0];
  const max = Math.max(1, peak, ...pts);
  const step = w / Math.max(1, pts.length - 1);
  let line = '';
  for (let i = 0; i < pts.length; i++) {
    const x = i * step;
    const y = h - (pts[i] / max) * (h - 10);
    line += `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`;
  }
  const fill = `${line}L${w} ${h}L0 ${h}Z`;
  return { line, fill };
}

function flashScreen(power = 1) {
  dom.flash.style.opacity = String(Math.min(0.42, 0.16 + power * 0.18));
  dom.flash.classList.add('on');
  clearTimeout(vibeTimer);
  vibeTimer = setTimeout(() => {
    dom.flash.style.opacity = '';
    dom.flash.classList.remove('on');
  }, 180);
}

function animateNumber(el, to, duration, formatter) {
  const from = 0;
  const start = performance.now();
  const tick = (now) => {
    const p = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - p, 3);
    el.textContent = formatter(Math.round(from + (to - from) * eased));
    if (p < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

function showResults(data) {
  const { rank, acc, full, isBest, prevBest, judgeTotals } = data;
  dom.rank.textContent = rank;
  dom.finalScore.textContent = '0000000';
  dom.finalAcc.textContent = '0.00%';
  animateNumber(dom.finalScore, data.score, 900, (n) => String(n).padStart(7, '0'));
  animateNumber(dom.fMaxCombo, data.maxCombo, 700, (n) => String(n));
  const accStart = performance.now();
  const accTick = (now) => {
    const p = Math.min(1, (now - accStart) / 900);
    const value = acc * (1 - Math.pow(1 - p, 3));
    dom.finalAcc.textContent = value.toFixed(2) + '%';
    dom.accRing.style.setProperty('--acc', value.toFixed(2) + '%');
    if (p < 1) requestAnimationFrame(accTick);
  };
  requestAnimationFrame(accTick);

  dom.cPerfect.textContent = data.counts.perfect;
  dom.cGreat.textContent = data.counts.great;
  dom.cGood.textContent = data.counts.good;
  dom.cBad.textContent = data.counts.bad;
  dom.cMiss.textContent = data.counts.miss;
  const total = Math.max(1, judgeTotals);
  dom.barPerfect.style.width = ((data.counts.perfect / total) * 100).toFixed(1) + '%';
  dom.barGreat.style.width = ((data.counts.great / total) * 100).toFixed(1) + '%';
  dom.barGood.style.width = ((data.counts.good / total) * 100).toFixed(1) + '%';
  dom.barBad.style.width = ((data.counts.bad / total) * 100).toFixed(1) + '%';
  dom.barMiss.style.width = ((data.counts.miss / total) * 100).toFixed(1) + '%';

  const graph = comboGraphPath(comboHistory, stats.maxCombo);
  dom.comboLine.setAttribute('d', graph.line);
  dom.comboFill.setAttribute('d', graph.fill);
  dom.peakCombo.textContent = stats.maxCombo;

  dom.resultTrack.textContent = selectedTrack.title;
  dom.resultDiff.textContent = selectedTrack.difficulty;
  dom.resultBpm.textContent = selectedTrack.bpmLabel || `${selectedTrack.bpm} BPM`;
  dom.footTrack.textContent = selectedTrack.shortTitle;
  dom.footLanes.textContent = selectedTrack.laneLabel;
  dom.resultTag.textContent = data.failed ? 'SIGNAL LOST // GAME OVER'
    : full ? 'FULL COMBO // FIELD MASTERED'
    : !data.cleared ? 'SIGNAL LOST // TRY AGAIN'
    : selectedTrack.boss ? (selectedTrack.clearTag || 'THE UNTOUCHABLE // FELLED')
    : 'CLEARED // SIGNAL COMPLETE';
  dom.fcBadge.classList.toggle('on', full);
  dom.bestBadge.classList.toggle('on', isBest);

  const best = bestMap[selectedTrack.id] || null;
  dom.bestNote.innerHTML = best
    ? `${String(best.score).padStart(7, '0')} · ${best.rank || '—'}`
    : 'FIRST RUN';
  const gap = Math.max(0, (best?.score || 0) - data.score);
  dom.scoreDelta.textContent = isBest
    ? (prevBest ? `NEW BEST +${String(Math.max(0, data.score - prevBest.score)).padStart(5, '0')}`
      : data.cleared ? 'FIRST CLEAR' : 'FIRST SCORE')
    : !data.scored ? 'NO SCORE RECORDED'
    : gap > 0 ? `PB GAP ${String(gap).padStart(5, '0')}` : 'PB MATCHED';

  dom.result.classList.remove('show');
  void dom.result.offsetWidth;
  dom.result.classList.add('show');
  setTimeout(() => { dom.resultLoading.classList.remove('show'); }, 60);
  dom.resultLoading.setAttribute('aria-hidden', 'true');
}

function startGameOver() {
  if (gameOver.active || (gameState !== 'playing' && gameState !== 'paused')) return;
  gameOver.active = true;
  gameOver.finished = false;
  gameOver.elapsed = 0;
  gameOver.wallStart = performance.now();
  gameOver.t0 = audio.time;
  gameOver.visualT = gameOver.t0;
  gameState = 'gameover';
  audio.pitchDrop(0.5, 2.4);
  scene.startGameOver();
  document.body.classList.add('game-over');
  clearTimeout(toastTimer);
  dom.toast.classList.remove('on');
  hideCaption();
  endPendulum();
  dom.pause.classList.remove('show');
}

function updateGameOver() {
  // Wall-clock, not frame time: the sequence still lasts 3.7s on a device
  // that drops frames instead of stretching the flatline for half a minute.
  gameOver.elapsed = (performance.now() - gameOver.wallStart) / 1000;
  // The chart clock keeps moving but decelerates to a full stop. Notes that
  // were approaching the line glide in and freeze instead of snapping away.
  const p = Math.min(1, gameOver.elapsed / 2.7);
  const eased = 1 - Math.pow(1 - p, 2.3);
  gameOver.visualT = gameOver.t0 + 1.3 * eased;
  if (!gameOver.finished && gameOver.elapsed >= 3.7) {
    gameOver.finished = true;
    finishGame(true);
  }
}

function finishGame(failed = false) {
  if (gameState !== 'playing' && gameState !== 'paused' && gameState !== 'gameover') return;
  gameState = 'results';
  audio.stop();
  audio.resume();
  gameOver.active = false;
  scene.resetGameOver();
  document.body.classList.remove('game-over');
  dom.hud.classList.add('hidden');
  dom.hud.setAttribute('aria-hidden', 'true');
  dom.pause.classList.remove('show');
  document.body.classList.remove('playing');
  setIntentPresentation(false);
  setBossIntro(false);

  const acc = stats.judged ? (stats.weight / stats.judged) * 100 : 100;
  const rank = rankFor(acc, stats.judged);
  comboHistory.push(stats.combo);
  if (comboHistory.length > COMBO_CAP) comboHistory.shift();
  const full = !failed && stats.miss === 0 && stats.bad === 0 && stats.judged > 0;
  const runScore = stats.score;
  const scored = runScore > 0 && !failed;
  const cleared = scored && acc >= 50;
  const prevBest = bestMap[selectedTrack.id] || null;
  // Skipping to the end (or never touching a lane) must not overwrite a real
  // personal best with a zero-score run. A failed run is not a clear either.
  const isBest = scored && (!prevBest
    || runScore > prevBest.score
    || (runScore === prevBest.score && acc > prevBest.acc));
  if (isBest) {
    bestMap[selectedTrack.id] = { score: runScore, acc, rank, maxCombo: stats.maxCombo, full, at: Date.now() };
    try { localStorage.setItem(BEST_KEY, JSON.stringify(bestMap)); } catch { /* storage unavailable */ }
  }
  renderBest();

  const data = {
    score: runScore, acc, rank, full, isBest, prevBest, scored, cleared, failed,
    maxCombo: stats.maxCombo, counts: { ...stats }, judgeTotals: stats.judged,
  };

  const token = ++resultToken;
  dom.result.classList.remove('show');
  dom.resultLoading.classList.add('show');
  dom.resultLoading.setAttribute('aria-hidden', 'false');
  dom.loadTrack.textContent = `${selectedTrack.shortTitle} // ${selectedTrack.difficulty}`;
  dom.loadRank.textContent = '?';
  dom.loadProgress.style.width = '0%';
  dom.loadPct.textContent = '00%';

  const start = performance.now();
  const duration = 1650;
  const tick = (now) => {
    if (token !== resultToken) return;
    const p = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - p, 3);
    dom.loadProgress.style.width = (eased * 100).toFixed(1) + '%';
    dom.loadPct.textContent = String(Math.round(eased * 100)).padStart(2, '0') + '%';
    if (p < 1) requestAnimationFrame(tick);
    else {
      dom.loadRank.textContent = rank;
      setTimeout(() => {
        if (token === resultToken) showResults(data);
      }, 280);
    }
  };
  requestAnimationFrame(tick);
}

function retryGame() {
  resultToken++;
  dom.result.classList.remove('show');
  startGame();
}

function alignPads(ahead = new Set()) {
  // Pad strips are visual affordances for the live lanes; input is global, but
  // a lane with an incoming note is still surfaced before its section starts.
  const active = new Set(currentSection ? activeLanesFor(currentSection.keys) : []);
  for (const lane of ahead) active.add(lane);
  for (let i = 0; i < 8; i++) {
    const g = scene.laneScreenGeometry(i);
    const left = i > 0 ? g.x - scene.laneScreenGeometry(i - 1).x : g.x - scene.laneScreenGeometry(1).x;
    const right = i < 7 ? scene.laneScreenGeometry(i + 1).x - g.x : g.x - scene.laneScreenGeometry(6).x;
    // Fill the whole gap between neighbouring lanes. The strip boundaries meet
    // (and slightly overlap) at the midpoint, so a thumb landing between two
    // lanes still hits one of them instead of an invisible dead zone.
    const gap = Math.max(26, (Math.abs(left) + Math.abs(right)) * 0.5);
    const width = Math.max(48, Math.min(240, gap * 1.1));
    // The strip is anchored at the hit circle and runs straight up the lane;
    // a small tail below the ring gives thumbs somewhere to land naturally.
    const bottom = g.y + 26;

    const bottom = g.y + 26;
    const top = Math.max(6, Math.min(bottom - 110, g.topY));
    const height = Math.max(110, bottom - top);
    const p = dom.pads[i];
    const transform = `translate(-50%,-100%) rotate(${g.angle.toFixed(4)}rad)`;
    p.style.left = g.x.toFixed(1) + 'px';
    p.style.top = bottom.toFixed(1) + 'px';
    p.style.width = width.toFixed(1) + 'px';
    p.style.height = height.toFixed(1) + 'px';
    p.style.transform = transform;
    const live = active.has(i);
    if (p.classList.contains('sleep') === live) p.classList.toggle('sleep', !live);
    p.setAttribute('aria-hidden', String(!live));
  }
  alignCenterPad();
}

function refreshSection(t) {
  const found = findSection(t);
  if (found.index !== sectionIndex || currentSection === null) {
    sectionIndex = found.index;
    updateSection(found.sec);
  }
}

function updateGhostEvents(t) {
  const list = chart.ghosts || [];
  while (ghostCursor < list.length && list[ghostCursor].t <= t) {
    const g = list[ghostCursor++];
    scene.ghostFx(g.lane, g.type);
  }
}

function updateChartEvents(t) {
  const list = chart.events || [];
  while (eventCursor < list.length && list[eventCursor].t <= t) {
    const ev = list[eventCursor++];
    switch (ev.type) {
      case 'echo': scene.echoFx(ev.lane, ev.dir ?? (ev.lane < 3.5 ? -1 : 1), ev.power ?? 1); break;
      case 'pulse': scene.pulseFx(ev.power ?? 1); break;
      case 'burst': scene.burstFx(ev.lane, ev.power ?? 1); break;
      case 'vibe':
        scene.vibeFx(ev.power ?? 1);
        flashScreen(ev.power ?? 1);
        break;
      case 'motion': scene.motionEvent(ev.style, ev.amp, ev.speed, ev.pitch); break;
      case 'clock':
        scene.setClock(ev.mode, ev.power ?? 1, ev.t);
        if (ev.mode !== 'freeze') endPendulum();
        break;
      case 'clockTick': scene.clockTick(ev.hand, ev.power ?? 1); break;
      case 'pendulum':
        if (ev.mode === 'start') startPendulum(ev);
        else endPendulum();
        break;
      case 'bossCamera':
        scene.bossCameraEvent(ev.pos, ev.look, ev.fov, ev.roll, ev.dur);
        break;
      case 'bossGlitch':
        scene.bossGlitch(ev.power ?? 1);
        glitchScreen(ev.power ?? 1);
        flashScreen((ev.power ?? 1) * 0.6);
        break;
      case 'bossTick':
        scene.bossTick(ev.hand, ev.power ?? 1);
        break;
      case 'bossPhase':
        scene.setBoss(ev.mode === 'play' ? 'play' : 'outro', selectedTrack.theme);
        if (ev.mode === 'play') {
          setBossIntro(false);
          if (selectedTrack.theme === 'intention') setIntentCinematic(false);
          else toast('CLOCK STAGE // FREE FIELD', 1700);
        } else {
          if (selectedTrack.theme === 'intention') setIntentCinematic(true);
          else hideCaption();
        }
        break;
      case 'intent':
        applyIntentEvent(ev);
        break;
      case 'wind':
        scene.windFx(ev.power ?? 1);
        break;
      case 'caption':
        showCaption(ev);
        break;
      default: break;
    }
  }
}

// ---------------------------------------------------------------- input
// Lane keys are accepted as a convenience, but the destination lane is chosen
// by the chart: the closest note to the hit line always answers first.
function keyDown(e) {
  if (e.code === 'Escape') {
    if (gameState === 'playing') { e.preventDefault(); pauseGame(); }
    else if (gameState === 'paused') { e.preventDefault(); resumeGame(); }
    return;
  }
  if (e.code === 'Space') {
    if (gameState === 'playing' && swingMode) {
      e.preventDefault();
      if (!e.repeat) swingTap();
    }
    return;
  }
  if (e.repeat) return;
  if (KEYMAP[e.code] === undefined) return;
  e.preventDefault();
  if (gameState !== 'playing') return;
  if (keysHeld.has(e.code)) return;
  keysHeld.add(e.code);
  pressGlobal();
}

function keyUp(e) {
  if (KEYMAP[e.code] === undefined) return;
  keysHeld.delete(e.code);
  releaseHolds();
}

document.addEventListener('keydown', keyDown, { passive: false });
document.addEventListener('keyup', keyUp);

function overGameUi(target) {
  return !!(target?.closest?.('#pauseBtn, #centerPad, .overlay, #startScreen, #resultScreen, #pauseScreen'));
}

// One capture-phase listener owns every tap. Pads are visuals and accessible
// buttons now; the finger can land anywhere in the playfield.
function pointerDown(e) {
  if (gameState !== 'playing') return;
  if (overGameUi(e.target)) return;
  e.preventDefault();
  try { e.target.setPointerCapture?.(e.pointerId); } catch { /* noop */ }
  touchPoints.add(e.pointerId);
  if (swingMode) swingTap();
  else pressGlobal();
}

function pointerUp(e) {
  touchPoints.delete(e.pointerId);
  releaseHolds();
}

window.addEventListener('pointerdown', pointerDown, { capture: true, passive: false });
window.addEventListener('pointerup', pointerUp, { capture: true, passive: true });
window.addEventListener('pointercancel', pointerUp, { capture: true, passive: true });
window.addEventListener('blur', () => {
  touchPoints.clear();
  keysHeld.clear();
  releaseHolds();
});

for (const pad of dom.pads) {
  pad.addEventListener('contextmenu', (e) => e.preventDefault());
}

if (dom.centerPad) {
  const down = (e) => {
    e.preventDefault();
    if (gameState !== 'playing' || !swingMode) return;
    touchPoints.add(e.pointerId);
    dom.centerPad.classList.add('pressed');
    swingTap();
  };
  const up = (e) => {
    e.preventDefault();
    touchPoints.delete(e.pointerId);
    dom.centerPad.classList.remove('pressed');
    releaseHolds();
  };
  dom.centerPad.addEventListener('pointerdown', down, { passive: false });
  dom.centerPad.addEventListener('pointerup', up, { passive: false });
  dom.centerPad.addEventListener('pointercancel', up, { passive: false });
  dom.centerPad.addEventListener('lostpointercapture', up, { passive: false });
  dom.centerPad.addEventListener('contextmenu', (e) => e.preventDefault());
}

dom.startBtn.addEventListener('click', () => {
  if (gameState === 'boot' || gameState === 'menu') startGame();
});
for (const card of dom.trackCards) {
  card.addEventListener('click', () => {
    if (gameState !== 'boot' && gameState !== 'menu') return;
    if (card.dataset.track === selectedTrack.id) return;
    selectTrack(card.dataset.track);
  });
}
dom.pauseBtn.addEventListener('click', pauseGame);
$('resumeBtn').addEventListener('click', resumeGame);
$('restartBtn').addEventListener('click', () => { dom.pause.classList.remove('show'); startGame(); });
$('quitBtn').addEventListener('click', quitToMenu);
$('retryBtn').addEventListener('click', retryGame);
$('menuBtn').addEventListener('click', quitToMenu);

document.addEventListener('visibilitychange', () => {
  if (document.hidden && gameState === 'playing') pauseGame();
});
addEventListener('blur', () => {
  if (gameState === 'playing') pauseGame();
});
dom.canvas.addEventListener('contextmenu', (e) => e.preventDefault());

// ---------------------------------------------------------------- track select
function applyTrackUI() {
  const t = selectedTrack;
  if (dom.startTrack) dom.startTrack.textContent = t.shortTitle;
  if (dom.startLength) dom.startLength.textContent = fmtTime(t.duration);
  if (dom.startLevel) dom.startLevel.textContent = t.difficulty;
  if (dom.startLanes) dom.startLanes.textContent = t.laneLabel;
  if (dom.hudTrack) dom.hudTrack.textContent = t.shortTitle;
  if (dom.hudBpm) dom.hudBpm.textContent = t.bpmLabel || `${t.bpm} BPM`;
  if (dom.loadTrack) dom.loadTrack.textContent = `${t.shortTitle} // ${t.difficulty}`;
  const count = $('trackCount');
  if (count) count.textContent = String(TRACKS.length).padStart(2, '0');
  document.body.classList.toggle('boss-track', !!t.boss);
  for (const card of dom.trackCards) {
    const meta = TRACK_BY_ID[card.dataset.track];
    if (meta) card.style.setProperty('--card-accent', meta.accent);
    const on = card.dataset.track === t.id;
    card.classList.toggle('active', on);
    card.setAttribute('aria-selected', String(on));
  }
  document.documentElement.style.setProperty('--track-accent', t.accent);
  renderBest();
}

async function selectTrack(id, { autoLoad = true } = {}) {
  const next = TRACK_BY_ID[id];
  if (!next) return;
  selectedTrack = next;
  chart = next.chart;
  chartEnd = chart.song.chartEnd;
  trackDuration = next.duration;
  applyTrackUI();
  setBossIntro(false);
  setIntentPresentation(false);
  hideCaption();
  dom.bossGlitch?.classList.remove('on');
  scene.setBoss(next.boss ? 'preview' : 'off', next.theme || 'untouchable');
  scene.setSection(chart.sections[0]);
  scene.setTempo(chart.song.bpm, chart.song.beatOffset);
  scene.setCity(chart.sections[0].city || 0);
  scene.setPreviewLanes(new Set());
  buildNotes();
  resetGame();
  // Show the clock as a menu preview for CHRONOSTASIS; every other track keeps
  // the background clean. Gameplay re-arms it from the chart's motif events.
  if (next.id === 'chronostasis') scene.setClock('run', 0.4);
  if (!autoLoad) return;
  gameState = 'boot';
  dom.startBtn.disabled = true;
  await loadAudio(next);
}

async function loadAudio(track = selectedTrack) {
  const token = ++loadToken;
  dom.startLabel.textContent = 'DECODING AUDIO';
  dom.loadFill.style.width = '0%';
  try {
    const buffer = await audio.load(track.audio, (p) => {
      if (token !== loadToken) return;
      dom.loadFill.style.width = Math.round(p * 100) + '%';
    });
    if (token !== loadToken) return;
    audio.setBuffer(buffer);
    dom.loadFill.style.width = '100%';
    dom.startLabel.textContent = 'START SESSION';
    dom.startBtn.disabled = false;
    gameState = 'menu';
  } catch (err) {
    if (token !== loadToken) return;
    console.error(err);
    dom.startLabel.textContent = 'AUDIO UNAVAILABLE';
    toast('COULD NOT LOAD AUDIO', 4000);
    gameState = 'menu';
  }
}

buildNotes();
resetGame();
gameState = 'boot';
applyTrackUI();
loadAudio(selectedTrack);

// ---------------------------------------------------------------- loop
let last = performance.now();
let menuT = 0;

function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
  last = now;
  menuT += dt;

  if (gameState === 'playing') {
    const t = audio.time;
    refreshSection(t);
    const ahead = lanesAhead(t);
    scene.setPreviewLanes(ahead);
    updateGhostEvents(t);
    updateChartEvents(t);
    updateIntent(dt, t);
    updateSwing(t);
    updateNotes(t);
    updateHUD(t);
    scene.animate(dt, t, true);
    alignPads(ahead);
    const failed = stats.health <= 0.001
      || (intent.guiltOn && !intent.fakeGuilt && intent.guilt <= 0.001);
    if (t >= chartEnd) finishGame();
    else if (failed) startGameOver();
  } else if (gameState === 'gameover') {
    updateGameOver();
    updateNotes(gameOver.visualT);
    scene.animate(dt, gameOver.visualT, true);
    alignPads(new Set());
  } else if (gameState === 'paused') {
    const t = audio.time;
    scene.animate(dt, t, true);
  } else if (gameState === 'results') {
    scene.animate(dt, menuT, false);
  } else {
    scene.animate(dt, menuT, false);
  }

  scene.render();
  requestAnimationFrame(frame);
}

// exposed for automated smoke tests / tinkering
window.__cryout = {
  audio, stats, scene, pressLane, pressGlobal, releaseLane, selectTrack,
  get chart() { return chart; },
  get notes() { return noteObjects; },
  get swings() { return swingNotes; },
  get swingMode() { return swingMode; },
  swingTap,
  get state() { return gameState; },
  get best() { return personalBest; },
  get intent() { return intent; },
};

requestAnimationFrame(frame);

/* ============================================================
   CRYOUT — dynamic 3D rhythm
   ============================================================ */
:root{
  --bg:#04040c;
  --ink:#eaf6ff;
  --muted:#8393ab;
  --cyan:#5ee7ff;
  --magenta:#ff5fd2;
  --violet:#9374ff;
  --panel:rgba(8,12,26,.58);
  --line:rgba(148,190,255,.18);
  --mono:ui-monospace,"DejaVu Sans Mono","Liberation Mono",Menlo,Consolas,monospace;
  --sans:Lato,"DejaVu Sans","Liberation Sans",system-ui,sans-serif;
}

*{box-sizing:border-box}
html,body{height:100%;margin:0;background:var(--bg);color:var(--ink);overflow:hidden}
body{
  font-family:var(--sans);
  -webkit-font-smoothing:antialiased;
  overscroll-behavior:none;
  user-select:none;
  -webkit-user-select:none;
  -webkit-tap-highlight-color:transparent;
}
body.playing{touch-action:none}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer}
#scene{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none}

#vignette{
  position:fixed;inset:0;pointer-events:none;z-index:1;
  background:
    radial-gradient(ellipse at 50% 44%, transparent 28%, rgba(2,2,9,.28) 66%, rgba(1,1,6,.82) 100%),
    linear-gradient(180deg, rgba(1,1,6,.55) 0%, transparent 18%, transparent 72%, rgba(1,1,6,.7) 100%);
  mix-blend-mode:multiply;
}
#vignette::after{
  content:"";position:absolute;inset:0;opacity:.16;pointer-events:none;
  background-image:repeating-linear-gradient(0deg, rgba(255,255,255,.08) 0 1px, transparent 1px 3px);
  mix-blend-mode:overlay;
}

#app{position:relative;z-index:2;height:100%;width:100%}
.hidden{display:none !important}

/* ---------------- HUD ---------------- */
#hud{
  position:absolute;inset:0;pointer-events:none;
  padding:max(clamp(14px,2.2vw,30px),env(safe-area-inset-top)) clamp(14px,2.2vw,30px) clamp(14px,2.2vw,30px);
  display:flex;flex-direction:column;
}
.topbar{
  display:grid;grid-template-columns:minmax(140px,1fr) minmax(240px,2.2fr) minmax(160px,1fr);
  align-items:start;gap:clamp(14px,3vw,54px);
}
.brand-title{
  font-weight:900;font-size:clamp(19px,2vw,27px);letter-spacing:.2em;line-height:1;
  text-shadow:0 0 22px rgba(94,231,255,.45);
}
.brand-sub{
  margin-top:7px;font-size:9px;letter-spacing:.22em;color:var(--muted);font-family:var(--mono);
}
.brand-sub span{color:var(--cyan)}
.brand-sub em{font-style:normal}

.track-wrap{align-self:start;padding-top:4px}
.progress{
  position:relative;height:4px;background:rgba(130,170,230,.14);
  box-shadow:0 0 0 1px rgba(140,190,255,.08) inset;overflow:hidden;
}
.progress b{
  position:absolute;inset:0 auto 0 0;width:0%;
  background:linear-gradient(90deg,var(--cyan),var(--violet) 55%,var(--magenta));
  box-shadow:0 0 16px var(--cyan);transition:width .08s linear;
}
.progress span{
  position:absolute;top:-3px;width:10px;height:10px;border-radius:50%;left:0%;
  background:#fff;box-shadow:0 0 14px 3px var(--cyan);transform:translateX(-50%);
  transition:left .08s linear;
}
.trackmeta{
  display:flex;justify-content:space-between;margin-top:10px;
  font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--muted);
}
#sectionName{color:var(--cyan);text-shadow:0 0 12px rgba(94,231,255,.6)}
.scoreblock{text-align:right}
.score{
  font-family:var(--mono);font-size:clamp(22px,2.4vw,32px);font-weight:700;letter-spacing:.08em;
  line-height:1;font-variant-numeric:tabular-nums;
  text-shadow:0 0 24px rgba(94,231,255,.28);
}
.acc{margin-top:8px;font-family:var(--mono);font-size:9px;letter-spacing:.16em;color:var(--muted)}
.acc .dot{margin:0 6px;color:rgba(255,255,255,.3)}
#acc{color:#cfeaff}

.left-hud{
  position:absolute;left:clamp(14px,2.2vw,30px);bottom:clamp(112px,15vh,160px);
  display:flex;flex-direction:column;gap:18px;align-items:flex-start;
}
.lane-count{display:flex;align-items:baseline;gap:7px;font-family:var(--mono)}
.lane-count span{
  font-size:clamp(26px,3vw,40px);font-weight:700;line-height:1;
  color:var(--cyan);text-shadow:0 0 22px rgba(94,231,255,.55);
}
.lane-count small{font-size:8px;letter-spacing:.24em;color:var(--muted)}
.sync{display:flex;align-items:center;gap:9px}
.sync-label{font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted);writing-mode:vertical-rl;transform:rotate(180deg)}
.energy{
  width:3px;height:82px;background:rgba(150,190,255,.15);position:relative;overflow:hidden;
}
.energy i{
  position:absolute;inset:auto 0 0 0;height:100%;
  background:linear-gradient(0deg,var(--magenta),var(--violet),var(--cyan));
  box-shadow:0 0 12px var(--cyan);transition:height .2s ease;
}
#comboHud{
  position:absolute;left:22%;top:45%;transform:translate(-50%,-50%) scale(.9);
  text-align:center;opacity:0;transition:opacity .2s ease, transform .2s ease;
  pointer-events:none;
}
#comboHud.on{opacity:.94;transform:translate(-50%,-50%) scale(1)}
#comboHud b{
  display:block;font-family:var(--mono);font-size:clamp(42px,6vw,84px);line-height:.85;
  font-weight:800;letter-spacing:-.03em;color:#fff;
  text-shadow:0 0 24px rgba(94,231,255,.78), 0 0 70px rgba(147,116,255,.4);
  font-variant-numeric:tabular-nums;
}
#comboHud span{
  display:block;margin-top:8px;font-family:var(--mono);font-size:9px;letter-spacing:.5em;
  color:var(--cyan);text-indent:.5em;
}
#comboHud.bump b{animation:bump .18s ease}
@keyframes bump{0%{transform:scale(1)}42%{transform:scale(1.13)}100%{transform:scale(1)}}

#judge{
  position:absolute;left:50%;top:57%;transform:translate(-50%,-50%);
  font-family:var(--mono);font-size:clamp(13px,1.5vw,18px);letter-spacing:.4em;
  color:#fff;opacity:0;text-transform:uppercase;white-space:nowrap;
  text-indent:.4em;text-shadow:0 0 22px currentColor;
  pointer-events:none;
}
#judge.pop{animation:judgePop .45s cubic-bezier(.2,.75,.2,1) both}
@keyframes judgePop{
  0%{opacity:0;transform:translate(-50%,-50%) scale(.72)}
  16%{opacity:1;transform:translate(-50%,-50%) scale(1.03)}
  62%{opacity:1;transform:translate(-50%,-62%) scale(1)}
  100%{opacity:0;transform:translate(-50%,-80%) scale(.98)}
}
#judge.perfect{color:#a9f6ff}
#judge.great{color:#73e6ff}
#judge.good{color:#a8a5ff}
#judge.bad{color:#ff9b6a}
#judge.miss{color:#ff4e75}

#pauseBtn{
  position:absolute;right:clamp(14px,2.2vw,30px);bottom:clamp(14px,2.2vw,30px);
  width:42px;height:42px;border:1px solid var(--line);border-radius:50%;
  background:rgba(8,12,26,.5);backdrop-filter:blur(8px);
  color:var(--muted);font-size:11px;pointer-events:auto;letter-spacing:.08em;
  transition:.2s;
}
#pauseBtn:hover{border-color:var(--cyan);color:var(--cyan);box-shadow:0 0 20px rgba(94,231,255,.25)}

/* ---------------- touch / key pads ----------------
   The pads are invisible tap zones placed on top of the 3D hit rings. The ring
   itself is the hit position, so tapping the ring is tapping the note. */
#pads{
  position:fixed;inset:0;z-index:4;
  pointer-events:none;touch-action:none;
#centerPad.pressed{
  transform:translate(-50%,-50%) scale(.92);
  background:radial-gradient(circle, rgba(255,209,102,.36), rgba(255,209,102,.1) 58%, transparent 72%);
  box-shadow:0 0 70px rgba(255,209,102,.42), inset 0 0 44px rgba(255,209,102,.2);
}
.cp-ring{
  position:absolute;inset:12%;border:1px dashed rgba(255,226,154,.4);border-radius:50%;
  animation:cp-spin 9s linear infinite;
}
.cp-label{
  font-family:var(--mono);font-size:10px;letter-spacing:.28em;color:#fff6dc;
  padding:5px 11px 4px;border-radius:999px;pointer-events:none;
  background:rgba(6,9,20,.62);border:1px solid rgba(255,209,102,.34);
  box-shadow:0 0 18px rgba(255,209,102,.28),inset 0 0 10px rgba(255,209,102,.12);
  text-shadow:0 0 12px rgba(255,209,102,1),0 0 3px rgba(255,240,200,.9);
}
@keyframes cp-spin{to{transform:rotate(360deg)}}
body.pendulum .pad{opacity:.2}
body.pendulum .pad.pressed{opacity:.32}
/* Keep hit feedback clear of the centre target while the pendulum runs. */
body.pendulum #judge{color:#ffe6a3;top:33%}

/* ---------------- THE UNTOUCHABLE boss stage ---------------- */
.track-card.boss{
  border-color:rgba(255,59,92,.28);
  background:linear-gradient(90deg,rgba(255,59,92,.08),rgba(255,209,102,.03));
}
.track-card.boss .tc-copy b{letter-spacing:.1em}
.track-card.boss .tc-tags .thumb{
  color:#ffe6a3;border-color:rgba(255,209,102,.38);
  box-shadow:0 0 12px rgba(255,209,102,.16);
}

/* During the cinematic the field and HUD are deliberately empty. */
body.boss-intro #hud{opacity:0;pointer-events:none}
body.boss-intro #hud .pad{pointer-events:none}
#hud{transition:opacity .55s ease}

/* Chart-synced title cards */
#bossCaption{
  position:fixed;left:50%;top:54%;z-index:4;
  width:min(900px,88vw);transform:translate(-50%,-42%);
  display:flex;flex-direction:column;align-items:center;gap:8px;
  text-align:center;pointer-events:none;opacity:0;visibility:hidden;
  transition:opacity .4s ease, transform .55s cubic-bezier(.2,.7,.2,1), visibility .4s;
  text-shadow:0 2px 18px rgba(2,1,6,.9),0 0 30px rgba(255,59,92,.45),0 0 8px rgba(255,240,200,.3);
}
#bossCaption::before{
  content:'';position:absolute;inset:-14% -8%;z-index:-1;border-radius:50%;
  background:radial-gradient(ellipse at center,rgba(3,2,9,.74) 0%,rgba(3,2,9,.4) 48%,rgba(3,2,9,0) 74%);
}
#bossCaption.on{opacity:1;visibility:visible;transform:translate(-50%,-50%)}
#bossCaption span{
  font-family:var(--mono);font-size:10px;letter-spacing:.52em;color:#ffd166;
  padding-left:.52em;
}
#bossCaption b{
  font-family:var(--sans);font-size:clamp(36px,7.2vw,94px);font-weight:700;
  letter-spacing:.12em;line-height:.94;color:#fff6e2;
}
#bossCaption em{
  font-family:var(--mono);font-style:normal;font-size:clamp(9px,1.2vw,13px);
  letter-spacing:.44em;color:#ffb0b8;padding-left:.44em;
}

/* Beat-synced glitch bands. JS toggles .on from chart events. */
#bossGlitch{
  position:fixed;inset:0;z-index:5;pointer-events:none;opacity:0;
  mix-blend-mode:screen;overflow:hidden;
}
#bossGlitch i{
  position:absolute;left:-4%;right:-4%;height:9%;
  background:
    linear-gradient(90deg,rgba(255,59,92,.5),rgba(255,209,102,.08) 42%,rgba(79,242,255,.34) 72%,transparent);
  filter:blur(.5px);transform:translateX(0);
}
#bossGlitch i:nth-child(1){top:18%;height:3%}
#bossGlitch i:nth-child(2){top:43%;height:11%;background:linear-gradient(90deg,rgba(79,242,255,.32),transparent 28%,rgba(255,59,92,.46))}
#bossGlitch i:nth-child(3){top:68%;height:5%}
#bossGlitch i:nth-child(4){top:86%;height:14%;background:linear-gradient(90deg,transparent,rgba(255,209,102,.34),rgba(255,59,92,.25))}
#bossGlitch.on{animation:boss-glitch-flash .3s steps(2,end)}
#bossGlitch.on i:nth-child(1){animation:boss-glitch-a .3s steps(2,end)}
#bossGlitch.on i:nth-child(2){animation:boss-glitch-b .3s steps(2,end)}
#bossGlitch.on i:nth-child(3){animation:boss-glitch-a .3s steps(2,end) reverse}
#bossGlitch.on i:nth-child(4){animation:boss-glitch-b .3s steps(2,end) reverse}
@keyframes boss-glitch-flash{0%{opacity:.8}35%{opacity:.25}60%{opacity:.65}100%{opacity:0}}
@keyframes boss-glitch-a{0%{transform:translateX(-3%)}50%{transform:translateX(2.4%)}100%{transform:translateX(-1%)}}
@keyframes boss-glitch-b{0%{transform:translateX(4%)}50%{transform:translateX(-3.2%)}100%{transform:translateX(1.5%)}}

/* ============================================================
   INTENTION — guilt HUD, heartbeat, ocean overlays
   ============================================================ */
.track-card[data-track="intention"]{
  border-color:rgba(255,209,102,.30);
  background:linear-gradient(90deg,rgba(255,209,102,.07),rgba(120,190,255,.03));
}
.track-card[data-track="intention"] .tc-tags .thumb{color:#ffe6a3;border-color:rgba(255,209,102,.4)}

#guiltHud{
  position:absolute;left:clamp(14px,2.2vw,30px);bottom:clamp(108px,14.5vh,156px);
  width:clamp(180px,20vw,310px);display:none;flex-direction:column;gap:7px;
  font-family:var(--mono);pointer-events:none;
}
body.guilt-on #guiltHud{display:flex}
body.guilt-on .sync{opacity:0;pointer-events:none}
.guilt-head{display:flex;align-items:flex-end;justify-content:space-between;letter-spacing:.28em}
.guilt-head span{font-size:9px;color:#ff6b84;text-shadow:0 0 16px rgba(255,51,85,.6)}
.guilt-head b{font-size:clamp(24px,3vw,38px);line-height:.82;color:#fff;font-weight:800;
  font-variant-numeric:tabular-nums;text-shadow:0 0 20px rgba(255,51,85,.8)}
.guilt-track{
  position:relative;height:15px;background:rgba(255,51,85,.10);
  border:1px solid rgba(255,90,118,.32);overflow:hidden;
  box-shadow:0 0 0 1px rgba(0,0,0,.5) inset;
}
.guilt-track::after{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:repeating-linear-gradient(90deg,transparent 0 17px,rgba(4,2,8,.8) 17px 20px);
}
.guilt-track i{
  position:absolute;inset:0 auto 0 0;width:100%;display:block;
  background:linear-gradient(90deg,#7d0c24,#ff3355 48%,#ff879c);
  box-shadow:0 0 22px rgba(255,51,85,.8),0 0 6px rgba(255,200,210,.5) inset;
  transition:width .12s linear;
}
.guilt-track u{position:absolute;inset:0;display:block;opacity:0;pointer-events:none;
  background:
    linear-gradient(112deg,transparent 0 44%,rgba(4,2,8,.9) 45% 47%,transparent 48% 100%),
    linear-gradient(68deg,transparent 0 61%,rgba(4,2,8,.85) 62% 64%,transparent 65% 100%);
}
.guilt-copy{font-size:7px;letter-spacing:.18em;color:#8f6170;line-height:1.5;text-transform:uppercase}
body.guilt-fake .guilt-track{border-color:rgba(255,90,118,.55);animation:guilt-crack 1.7s steps(2,end) infinite}
body.guilt-fake .guilt-track u{opacity:1}
body.guilt-fake .guilt-head b{color:#ffd4dc;animation:guilt-flicker 2.1s steps(2,end) infinite}
body.guilt-fake .guilt-copy{color:#a3374b}
@keyframes guilt-crack{0%,100%{transform:translateX(0)}28%{transform:translateX(-1px)}31%{transform:translateX(2px)}34%{transform:translateX(0)}}
@keyframes guilt-flicker{0%,100%{opacity:1}42%{opacity:.55}46%{opacity:1}72%{opacity:.68}}
body:not(.guilt-on):not(.guilt-fake) #guiltHud{display:none}

/* heartbeat line — a full-screen ECG that climbs one third of the screen per
   beat (bottom → middle → top) and pulses a concentric shockwave on every hit */
#heartbeat{
  position:fixed;inset:0;z-index:3;pointer-events:none;
  opacity:0;transition:opacity .5s ease;mix-blend-mode:screen;
  --hb-y:70%;
}
#heartbeat.on{opacity:1}
.hb-wash{
  position:absolute;inset:0;
  background:
    radial-gradient(ellipse at 50% var(--hb-y),rgba(255,38,80,.22),transparent 44%),
    radial-gradient(ellipse at 50% var(--hb-y),rgba(255,120,140,.10),transparent 24%),
    linear-gradient(180deg,transparent 0%,rgba(255,20,60,.045) 50%,transparent 100%);
  opacity:.7;transition:background .18s linear;
}
.hb-track{
  position:absolute;left:-2%;right:-2%;top:var(--hb-y);
  height:clamp(120px,21vh,230px);transform:translateY(-50%);
  transition:top .17s cubic-bezier(.2,.9,.25,1);
  filter:drop-shadow(0 0 20px rgba(255,51,85,.38));
  will-change:top,transform;
}
.hb-track svg{width:100%;height:100%;overflow:visible}
#heartbeat path{fill:none;stroke-linecap:round;stroke-linejoin:round}
.hb-ghost{stroke:rgba(255,90,120,.16);stroke-width:1;transform:translateY(-8px)}
.hb-split{stroke:rgba(90,230,255,.32);stroke-width:1.1;transform:translate(3px,-4px)}
.hb-glow{stroke:rgba(255,51,85,.30);stroke-width:17;filter:blur(11px)}
.hb-line{stroke:#ff5b73;stroke-width:2.3;filter:drop-shadow(0 0 7px rgba(255,51,85,.95))}
.hb-rings{position:absolute;left:50%;top:50%;width:0;height:0;pointer-events:none}
.hb-rings i{
  position:absolute;left:0;top:0;width:18vmin;height:18vmin;margin:-9vmin 0 0 -9vmin;
  border:1.5px solid rgba(255,92,120,.7);border-radius:50%;
  opacity:0;transform:scale(.15);box-shadow:0 0 22px rgba(255,51,85,.35) inset;
}
.hb-spark{
  position:absolute;left:50%;top:50%;width:9px;height:9px;margin:-4.5px 0 0 -4.5px;
  border-radius:50%;background:#fff;opacity:0;
  box-shadow:0 0 12px #fff,0 0 34px #ff3355,0 0 70px rgba(255,51,85,.8);
}
#heartbeat.beat .hb-line{animation:hb-beat .34s cubic-bezier(.2,.8,.2,1)}
#heartbeat.beat .hb-glow{animation:hb-glow .34s ease-out}
#heartbeat.beat .hb-ghost{animation:hb-ghost .44s ease-out}
#heartbeat.beat .hb-split{animation:hb-split .38s ease-out}
#heartbeat.beat .hb-spark{animation:hb-spark .36s ease-out}
#heartbeat.beat .hb-track{animation:hb-lurch .34s cubic-bezier(.2,.9,.25,1)}
#heartbeat.beat .hb-wash{animation:hb-wash .42s ease-out}
#heartbeat.beat .hb-rings i:nth-child(1){animation:hb-ring .62s ease-out}
#heartbeat.beat .hb-rings i:nth-child(2){animation:hb-ring .62s .07s ease-out}
#heartbeat.beat .hb-rings i:nth-child(3){animation:hb-ring .62s .14s ease-out}
@keyframes hb-beat{0%{stroke:#fff;stroke-width:3.8}24%{stroke:#ffd2da;stroke-width:3.2}52%{stroke:#ff5b73;stroke-width:2.6}100%{stroke:#ff5b73;stroke-width:2.3}}
@keyframes hb-glow{0%{stroke-width:30;opacity:1}38%{stroke-width:22;opacity:.9}100%{stroke-width:17;opacity:.72}}
@keyframes hb-ghost{0%{opacity:.55;transform:translateY(-2px)}100%{opacity:.16;transform:translateY(-10px)}}
@keyframes hb-split{0%{opacity:.85;transform:translate(7px,-8px)}100%{opacity:.32;transform:translate(3px,-4px)}}
@keyframes hb-spark{0%{opacity:1;transform:scale(2.6)}34%{opacity:.9;transform:scale(1)}100%{opacity:0;transform:scale(.2)}}
@keyframes hb-lurch{0%{transform:translateY(-50%) scaleY(1.13)}30%{transform:translateY(-50%) scaleY(.95)}62%{transform:translateY(-50%) scaleY(1.03)}100%{transform:translateY(-50%) scaleY(1)}}
@keyframes hb-wash{0%{opacity:1}100%{opacity:.7}}
@keyframes hb-ring{0%{opacity:.85;transform:scale(.2)}70%{opacity:.25}100%{opacity:0;transform:scale(2.5)}}
body.heartbeat-on #heartbeat{opacity:1}

/* During the heartbeat the standard HUD steps aside. The progress line, the
   sync/guilt bars and the heartbeat itself stay; score, judgement, combo,
   lane labels and pads fade out. */
body.heartbeat-on #hud .brand,
body.heartbeat-on #hud .scoreblock,
body.heartbeat-on #hud .trackmeta,
body.heartbeat-on #hud .lane-count,
body.heartbeat-on #hud .sync-label,
body.heartbeat-on #hud #comboHud,
body.heartbeat-on #hud #judge,
body.heartbeat-on #hud #pads,
body.heartbeat-on #hud .pad .pk,
body.heartbeat-on #toast{
  opacity:0 !important;visibility:hidden !important;pointer-events:none !important;
  transition:opacity .28s ease,visibility .28s ease;
}

/* INTENTIONS glitch title */
#intentGlitchText{
  position:fixed;left:50%;top:43%;z-index:5;transform:translate(-50%,-50%);
  display:flex;flex-direction:column;align-items:center;gap:10px;pointer-events:none;
  opacity:0;visibility:hidden;transition:opacity .2s ease, visibility .2s;
}
#intentGlitchText.on{opacity:1;visibility:visible;animation:intent-shake .4s steps(2,end) infinite}
#intentGlitchText span{
  position:relative;font-family:var(--sans);font-weight:900;
  font-size:clamp(42px,9vw,128px);letter-spacing:.16em;color:#fff;line-height:.9;
  text-shadow:0 0 32px rgba(255,255,255,.38),0 0 90px rgba(120,200,255,.24);
}
#intentGlitchText span::before,#intentGlitchText span::after{
  content:attr(data-text);position:absolute;inset:0;pointer-events:none;
}
#intentGlitchText span::before{color:#ff3355;transform:translate(3px,-2px);clip-path:inset(12% 0 46% 0);opacity:.72}
#intentGlitchText span::after{color:#65e5ff;transform:translate(-3px,2px);clip-path:inset(56% 0 8% 0);opacity:.66}
#intentGlitchText em{font-family:var(--mono);font-style:normal;font-size:9px;letter-spacing:.58em;color:#ffd166;text-indent:.58em}
@keyframes intent-shake{0%,100%{transform:translate(-50%,-50%)}25%{transform:translate(calc(-50% + 2px),calc(-50% - 1px))}50%{transform:translate(calc(-50% - 2px),-50%)}75%{transform:translate(-50%,calc(-50% + 1px))}}

/* screen overlays */
#blackout,#whiteout{position:fixed;inset:0;pointer-events:none;z-index:1;opacity:0;transition:opacity .35s ease}
#blackout{background:#010104}
#blackout.on{opacity:1}
#whiteout{background:#fff;z-index:30;transition:opacity .12s ease}
#whiteout.on{opacity:1}
body.intent-whiteout #hud,body.intent-whiteout #vignette{opacity:0}
body.intent-whiteout #whiteout{opacity:1}
/* The 3D stage goes black for the guilt sections; no DOM overlay is used, so
   the white guilt lane and its notes stay readable above the void. */
body.intent-black #vignette{opacity:.35}

#pads{transition:opacity .4s ease}

#intentStatic{
  position:fixed;inset:0;z-index:3;pointer-events:none;opacity:0;
  background-image:
    repeating-linear-gradient(0deg,rgba(255,255,255,.055) 0 1px,transparent 1px 3px),
    repeating-linear-gradient(90deg,rgba(255,255,255,.035) 0 1px,transparent 1px 5px),
    radial-gradient(circle at 34% 62%,rgba(255,255,255,.16),transparent 26%),
    radial-gradient(circle at 72% 31%,rgba(120,210,255,.13),transparent 24%);
  background-size:100% 100%,100% 100%,170% 170%,190% 190%;
  mix-blend-mode:screen;animation:intent-static .28s steps(2,end) infinite;
  transition:opacity .35s ease;
}
body.static-on #intentStatic{opacity:.55}
body.static-on.static-heavy #intentStatic{opacity:.9}
@keyframes intent-static{0%{background-position:0 0,0 0,0 0,0 0}50%{background-position:0 2px,3px 0,4% 6%,-3% 2%}100%{background-position:0 0,0 0,0 0,0 0}}

#intentScanlines{
  position:fixed;inset:0;z-index:1;pointer-events:none;opacity:0;
  background:
    linear-gradient(90deg,rgba(255,0,60,.10),transparent 12%,transparent 82%,rgba(0,210,255,.10)),
    repeating-linear-gradient(0deg,rgba(255,255,255,.035) 0 1px,transparent 1px 4px);
  mix-blend-mode:screen;transition:opacity .3s ease;
}
body.distort-on #intentScanlines{opacity:.85;animation:intent-roll 2.2s linear infinite}
body.distort-on #scene{filter:saturate(1.15) contrast(1.06)}
@keyframes intent-roll{0%{background-position:0 0,0 0}100%{background-position:0 0,0 48px}}

#yellowVignette{
  position:fixed;inset:0;z-index:1;pointer-events:none;opacity:0;transition:opacity 1.2s ease;
  background:radial-gradient(ellipse at 50% 58%,transparent 30%,rgba(255,209,102,.12) 62%,rgba(255,190,50,.34) 100%);
  mix-blend-mode:screen;
}
#yellowVignette.on{opacity:1}
#rainbowWash{
  position:fixed;inset:0;z-index:1;pointer-events:none;opacity:0;transition:opacity 1.1s ease;
  background:linear-gradient(120deg,rgba(255,80,120,.12),rgba(255,210,80,.12) 22%,rgba(90,255,190,.12) 44%,rgba(80,190,255,.13) 62%,rgba(180,110,255,.13));
  mix-blend-mode:screen;
}
#rainbowWash.on{opacity:1}
body.bright-on #vignette{opacity:.32}

body.guilt-on #judge{color:#ff9dac}
body.guilt-on #comboHud b{color:#fff;text-shadow:0 0 24px rgba(255,51,85,.9),0 0 70px rgba(255,51,85,.45)}
body.guilt-on #comboHud span{color:#ff6b84}

/* rainbow sync bar at the dawn */
.sync.rainbow .sync-label{color:#ffe9a8}
.sync.rainbow .energy{width:8px;background:rgba(255,255,255,.18);box-shadow:0 0 18px rgba(255,255,255,.25)}
.sync.rainbow .energy i{
  background:linear-gradient(0deg,#ff5b73,#ffd166 22%,#9cffb0 44%,#65e5ff 66%,#b18cff 84%,#ff8ad8);
  box-shadow:0 0 18px rgba(255,255,255,.85);
  animation:rainbow-breathe 2.4s ease-in-out infinite;
}
@keyframes rainbow-breathe{0%,100%{filter:saturate(1.1) brightness(1)}50%{filter:saturate(1.5) brightness(1.25)}}

@media (max-width:900px){
  #guiltHud{bottom:clamp(96px,13vh,138px);width:clamp(150px,42vw,230px)}
  .guilt-track{height:13px}
  #intentGlitchText span{font-size:clamp(34px,12vw,78px)}
  .hb-track{height:15vh}
  body.guilt-on #comboHud{left:28%;top:35%}
}

/* ============================================================
   INTENTION — textless field, title cards only in cutscenes
   ============================================================ */
body.intent-clean #hud .brand,
body.intent-clean #hud .scoreblock,
body.intent-clean #hud .trackmeta,
body.intent-clean #hud .lane-count,
body.intent-clean #hud .sync-label,
body.intent-clean #hud #comboHud,
body.intent-clean #hud #judge,
body.intent-clean #hud .pad .pk,
body.intent-clean #hud #centerPad .cp-label,
body.intent-clean #guiltHud .guilt-head,
body.intent-clean #guiltHud .guilt-copy,
body.intent-clean #intentGlitchText,
body.intent-clean #toast{display:none !important}

/* Keep the silent progress line and sync/guilt bars as pure graphics. */
body.intent-clean #hud .topbar{grid-template-columns:1fr}
body.intent-clean #hud .track-wrap{grid-column:1 / -1}
body.intent-clean #bossCaption{opacity:0 !important;visibility:hidden !important}
body.intent-clean.intent-cutscene #bossCaption.on{opacity:1 !important;visibility:visible !important}

/* ============================================================
   GAME OVER — tape-stop field, red wash, flatline
   ============================================================ */
#gameOverFx{
  position:fixed;inset:0;z-index:25;pointer-events:none;overflow:hidden;
  opacity:0;transition:opacity .22s ease;
}
body.game-over #gameOverFx{opacity:1}
body.game-over #scene{
  filter:saturate(.35) contrast(1.28) brightness(.72);
  transform:scale(1.015);
}
body.game-over #hud{opacity:.16;filter:blur(1.2px);transition:opacity .5s ease}
body.game-over #toast{opacity:0 !important}

.go-wash{
  position:absolute;inset:0;
  background:
    radial-gradient(ellipse at 50% 48%,transparent 24%,rgba(190,0,24,.24) 60%,rgba(96,0,12,.72) 100%),
    linear-gradient(180deg,rgba(255,0,32,.10),rgba(90,0,14,.28));
  mix-blend-mode:screen;
  animation:go-pulse 1.5s ease-in-out infinite;
}
.go-bars{position:absolute;inset:0;opacity:.6;mix-blend-mode:screen}
.go-bars i{
  position:absolute;left:-10%;right:-10%;height:2px;
  background:linear-gradient(90deg,transparent,rgba(255,40,70,.85),transparent);
  animation:go-scan 2.4s linear infinite;
}
.go-bars i:nth-child(1){top:12%;animation-delay:-.2s}
.go-bars i:nth-child(2){top:31%;animation-delay:-1.1s;opacity:.6}
.go-bars i:nth-child(3){top:49%;animation-delay:-.6s;height:4px}
.go-bars i:nth-child(4){top:68%;animation-delay:-1.7s;opacity:.5}
.go-bars i:nth-child(5){top:86%;animation-delay:-.9s}
.go-flatline{
  position:absolute;left:-2%;right:-2%;top:50%;height:clamp(110px,19vh,210px);
  transform:translateY(-50%);opacity:.8;
  filter:drop-shadow(0 0 18px rgba(255,24,56,.7));
}
.go-flatline svg{width:100%;height:100%;overflow:visible}
.go-flatline path{
  fill:none;stroke:#ff2748;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;
  stroke-dasharray:1400;stroke-dashoffset:0;
  animation:go-flatline 2.2s ease-out both;
}
.go-title{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  display:flex;flex-direction:column;align-items:center;gap:12px;
  text-align:center;
}
.go-title b{
  font-family:var(--sans);font-size:clamp(40px,9vw,118px);font-weight:900;
  letter-spacing:.14em;color:#fff;line-height:.9;
  text-shadow:0 0 22px rgba(255,31,67,.95),0 0 80px rgba(255,0,40,.5);
  animation:go-title-glitch .9s steps(2,end) infinite;
}
.go-title span{
  font-family:var(--mono);font-size:9px;letter-spacing:.62em;color:#ff8fa2;
  text-indent:.62em;
}
body.intent-clean .go-title{display:none}

@keyframes go-pulse{0%,100%{opacity:.72;transform:scale(1)}50%{opacity:1;transform:scale(1.012)}}
@keyframes go-scan{0%{transform:translateY(-14vh)}100%{transform:translateY(114vh)}}
@keyframes go-flatline{0%{stroke-dashoffset:1400;opacity:0}16%{opacity:1}100%{stroke-dashoffset:0;opacity:1}}
@keyframes go-title-glitch{
  0%,100%{transform:translate(0,0);text-shadow:0 0 22px rgba(255,31,67,.95),0 0 80px rgba(255,0,40,.5)}
  24%{transform:translate(-2px,1px);text-shadow:3px 0 rgba(90,230,255,.8),-3px 0 rgba(255,0,40,.9)}
  48%{transform:translate(2px,-1px);text-shadow:-2px 0 rgba(90,230,255,.7),2px 0 rgba(255,0,40,.85)}
}

@media (max-width:900px){
  .go-title b{font-size:clamp(34px,12vw,74px)}
}

  .pad .pk{display:none}
  .pad::before{display:none}
}

/* ---------------- overlays ---------------- */
.overlay{
  position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;
  opacity:0;visibility:hidden;transition:opacity .4s ease, visibility .4s;
  padding:clamp(18px,4vw,60px);
  background:
    radial-gradient(ellipse at 68% 42%, rgba(15,24,54,.42), transparent 60%),
    linear-gradient(90deg, rgba(2,3,10,.92) 0%, rgba(2,3,10,.62) 48%, rgba(2,3,10,.18) 100%);
  backdrop-filter:blur(2px);
  overflow:auto;
}
.overlay.show{opacity:1;visibility:visible}
.overlay::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background-image:
    linear-gradient(rgba(130,180,255,.045) 1px,transparent 1px),
    linear-gradient(90deg,rgba(130,180,255,.045) 1px,transparent 1px);
  background-size:64px 64px;
  mask-image:radial-gradient(ellipse at 50% 50%,#000 10%,transparent 78%);
}
.start-grid{
  width:min(1180px,100%);display:grid;grid-template-columns:1.2fr .8fr;
  gap:clamp(28px,5vw,90px);align-items:center;position:relative;
}
.eyebrow{
  display:flex;align-items:center;gap:10px;font-family:var(--mono);
  font-size:9px;letter-spacing:.32em;color:var(--cyan);text-transform:uppercase;
}
.eyebrow i{width:24px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.start-copy h1{
  margin:18px 0 10px;font-size:clamp(88px,13.4vw,190px);line-height:.72;
  font-weight:900;letter-spacing:-.065em;color:#fff;
  text-shadow:
    0 0 1px #fff,
    0 0 34px rgba(94,231,255,.32),
    7px 7px 0 rgba(255,95,210,.12),
    -5px -5px 0 rgba(94,231,255,.1);
  position:relative;
}
.start-copy h1::after{
  content:"";position:absolute;left:2px;right:16%;top:47%;height:2px;
  background:linear-gradient(90deg,transparent,rgba(94,231,255,.65),transparent);
  mix-blend-mode:screen;animation:scan 5s linear infinite;
}
@keyframes scan{0%,100%{opacity:.2;transform:translateY(-0.5em)}50%{opacity:.8;transform:translateY(1.3em)}}
.tagline{
  margin:0 0 26px;font-size:clamp(15px,1.5vw,20px);line-height:1.55;color:#b8c7db;
  max-width:34ch;font-weight:300;
}
.specs{
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;
  border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  padding:14px 0;margin-bottom:26px;max-width:560px;
}
.specs span{display:block;font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted);margin-bottom:6px}
.specs b{font-family:var(--mono);font-size:12px;letter-spacing:.08em;font-weight:600;color:#e7f3ff}
.cta{
  display:inline-flex;align-items:center;gap:22px;justify-content:space-between;
  min-width:260px;padding:16px 22px;border:1px solid rgba(94,231,255,.52);
  background:linear-gradient(90deg,rgba(94,231,255,.16),rgba(147,116,255,.1));
  font-family:var(--mono);font-size:11px;letter-spacing:.26em;color:#eaffff;
  box-shadow:0 0 40px rgba(94,231,255,.12) inset,0 0 30px rgba(94,231,255,.06);
  transition:.22s;position:relative;overflow:hidden;
}
.cta::after{
  content:"";position:absolute;inset:0;background:linear-gradient(100deg,transparent 20%,rgba(255,255,255,.18) 50%,transparent 80%);
  transform:translateX(-120%);transition:transform .6s;
}
.cta:hover:not(:disabled)::after{transform:translateX(120%)}
.cta:hover:not(:disabled){border-color:var(--cyan);box-shadow:0 0 50px rgba(94,231,255,.22),0 0 30px rgba(94,231,255,.08) inset;transform:translateY(-2px)}
.cta:disabled{opacity:.45;cursor:wait}
.cta i{font-style:normal;font-size:17px;line-height:1;color:var(--track-accent,var(--cyan))}
.cta.small{min-width:180px;padding:13px 18px}
.loadbar{height:2px;width:min(300px,100%);background:rgba(140,190,255,.14);margin-top:12px;overflow:hidden}
.loadbar b{display:block;height:100%;width:0%;background:var(--track-accent,var(--cyan));box-shadow:0 0 12px var(--track-accent,var(--cyan));transition:width .2s}
.best-line{display:none;margin:10px 0 0;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--muted)}
.best-line b{color:#dff6ff;font-weight:500;letter-spacing:.1em}
.hint{margin:16px 0 0;font-family:var(--mono);font-size:9px;line-height:1.7;letter-spacing:.08em;color:#687792}

.start-side{display:flex;flex-direction:column;gap:14px}
.panel{
  border:1px solid var(--line);background:var(--panel);backdrop-filter:blur(12px);
  padding:20px 20px 18px;position:relative;
}
.panel::before{
  content:"";position:absolute;left:-1px;top:-1px;width:35px;height:1px;background:var(--cyan);
  box-shadow:0 0 10px var(--cyan);
}
.panel-title{font-family:var(--mono);font-size:9px;letter-spacing:.28em;color:var(--cyan);margin-bottom:16px}
.keyrow{display:grid;grid-template-columns:repeat(8,1fr);gap:4px;margin-bottom:12px}
kbd{
  display:flex;align-items:center;justify-content:center;aspect-ratio:1;min-height:28px;
  border:1px solid rgba(150,195,255,.28);background:rgba(10,16,34,.8);
  font-family:var(--mono);font-size:10px;color:#cfe6ff;border-radius:3px;
  box-shadow:0 2px 0 rgba(0,0,0,.35);
}
.panel p{margin:0;font-size:12px;line-height:1.6;color:#9cadc4}
.touchline{display:flex;align-items:center;gap:8px;margin-top:14px;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--muted)}
.touchicon{width:11px;height:16px;border:1px solid var(--muted);border-radius:3px;position:relative}
.touchicon::after{content:"";position:absolute;left:4px;top:3px;width:2px;height:4px;background:var(--cyan)}
.pendline{color:#e8c982;margin-top:8px}
.pendicon{width:14px;height:14px;border:1px solid currentColor;border-radius:50%;position:relative;box-shadow:0 0 8px rgba(255,209,102,.5)}
.pendicon::after{content:"";position:absolute;left:50%;top:1px;width:1px;height:6px;background:currentColor;transform-origin:50% 100%;transform:rotate(32deg)}
.syslist{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.syslist li{display:flex;justify-content:space-between;font-family:var(--mono);font-size:9px;letter-spacing:.12em;color:var(--muted);border-bottom:1px dashed rgba(140,190,255,.1);padding-bottom:9px}
.syslist li:last-child{border:0;padding:0}
.syslist b{color:#d7e9ff;font-weight:500}
.credit{font-family:var(--mono);font-size:8px;line-height:1.8;letter-spacing:.14em;color:#4d5a72;text-align:right;margin-top:2px}

/* modal / results */
.modal,.results{
  width:min(720px,100%);position:relative;
  border:1px solid var(--line);background:rgba(5,8,19,.84);backdrop-filter:blur(18px);
  padding:clamp(24px,4vw,48px);box-shadow:0 30px 90px rgba(0,0,0,.6);
  animation:modalIn .45s cubic-bezier(.2,.7,.2,1) both;
}
@keyframes modalIn{from{opacity:0;transform:translateY(18px) scale(.98)}to{opacity:1;transform:none}}
.modal h2,.results h2{
  margin:16px 0 4px;font-size:clamp(48px,8vw,92px);line-height:.86;letter-spacing:-.04em;font-weight:900;
}
.modal-sub{margin:10px 0 28px;font-family:var(--mono);font-size:10px;letter-spacing:.18em;color:var(--muted)}
.btnrow{display:flex;gap:10px;flex-wrap:wrap}
.ghost{
  padding:13px 18px;border:1px solid rgba(140,190,255,.22);
  font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:#9fb4cd;transition:.2s;
}
.ghost:hover{border-color:var(--cyan);color:#eaffff;background:rgba(94,231,255,.05)}

.result-head{display:flex;justify-content:space-between;align-items:flex-start;gap:24px}
.rank-wrap{display:flex;flex-direction:column;align-items:flex-end;gap:10px}
#rank{
  font-size:clamp(90px,15vw,170px);line-height:.72;font-weight:900;letter-spacing:-.07em;
  color:#fff;text-shadow:0 0 40px rgba(94,231,255,.6),0 0 110px rgba(255,95,210,.35);
  font-style:italic;
}
.best-badge{
  display:none;font-family:var(--mono);font-size:8px;letter-spacing:.24em;
  color:#04040c;background:var(--cyan);padding:5px 10px;
  box-shadow:0 0 26px rgba(94,231,255,.45);
}
.best-badge.on{display:block;animation:bestPop .5s cubic-bezier(.2,.8,.2,1) both}
@keyframes bestPop{0%{opacity:0;transform:translateY(6px) scale(.92)}100%{opacity:1;transform:none}}
.result-foot{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}
.fc{
  font-family:var(--mono);font-size:9px;letter-spacing:.26em;color:var(--cyan);
  border:1px solid rgba(94,231,255,.45);padding:8px 12px;opacity:0;transform:translateY(4px);
  transition:.3s;
}
.fc.on{opacity:1;transform:none;box-shadow:0 0 20px rgba(94,231,255,.18)}

/* ---------------- track picker ---------------- */
.track-picker{max-width:560px;margin:0 0 16px;display:flex;flex-direction:column;gap:6px}
.picker-head{display:flex;justify-content:space-between;align-items:center;font-family:var(--mono);font-size:8px;letter-spacing:.24em;color:var(--muted);margin-bottom:2px}
.picker-head b{color:var(--cyan);font-weight:500}
.picker-head em{margin-left:auto;margin-right:12px;font-style:normal;font-weight:500;color:#6d7b93}
.picker-head em.all{color:var(--cyan);text-shadow:0 0 12px rgba(94,231,255,.5)}
.track-card.cleared .tc-num{color:var(--cyan)}
.track-card{
  --card-accent:var(--cyan);
  display:grid;grid-template-columns:34px 1fr auto;align-items:center;gap:12px;width:100%;
  text-align:left;padding:10px 13px;border:1px solid rgba(140,190,255,.16);
  background:rgba(8,12,26,.5);transition:.2s;position:relative;overflow:hidden;
}
.track-card::before{
  content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--card-accent);
  transform:scaleY(0);transition:transform .25s;box-shadow:0 0 14px var(--card-accent);
}
.track-card:hover{border-color:var(--card-accent);background:rgba(94,231,255,.06)}
.track-card.active{
  border-color:var(--card-accent);
  background:linear-gradient(90deg,rgba(94,231,255,.12),rgba(147,116,255,.05));
  background:linear-gradient(90deg,color-mix(in srgb,var(--card-accent) 14%,transparent),rgba(147,116,255,.05));
  box-shadow:0 0 30px color-mix(in srgb,var(--card-accent) 12%,transparent);
}
.track-card.active::before{transform:scaleY(1)}
.tc-num{font-family:var(--mono);font-size:11px;color:var(--muted);letter-spacing:.1em}
.track-card.active .tc-num{color:var(--card-accent)}
.tc-copy{display:flex;flex-direction:column;gap:3px;min-width:0}
.tc-copy b{font-size:13px;letter-spacing:.12em;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tc-copy em{font-style:normal;font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted)}
.tc-tags{display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end}
.tc-tags span{font-family:var(--mono);font-size:7px;letter-spacing:.12em;color:#a9c3de;border:1px solid rgba(140,190,255,.2);padding:3px 5px;white-space:nowrap}
.tc-tags .thumb{color:#04040c;background:var(--card-accent);border-color:var(--card-accent)}
.tc-best{font-family:var(--mono);font-size:8px;color:var(--card-accent,var(--cyan))}
.tc-best:empty{display:none}

/* ---------------- results v2 ---------------- */
.results{
  width:min(1080px,100%);position:relative;overflow:hidden;
  border:1px solid rgba(148,190,255,.24);background:rgba(5,8,19,.88);
  backdrop-filter:blur(18px);padding:clamp(22px,3.4vw,44px);
  box-shadow:0 40px 120px rgba(0,0,0,.7),0 0 90px rgba(94,231,255,.06) inset;
  animation:modalIn .5s cubic-bezier(.2,.7,.2,1) both;
}
.results::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:
    radial-gradient(ellipse at 88% 6%,rgba(94,231,255,.12),transparent 44%),
    radial-gradient(ellipse at 4% 100%,rgba(255,95,210,.09),transparent 50%);
}
.results::after{
  content:"";position:absolute;left:0;right:0;top:0;height:1px;
  background:linear-gradient(90deg,transparent,var(--cyan),var(--magenta),transparent);
  box-shadow:0 0 20px var(--cyan);
}
.result-head{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;position:relative;z-index:1}
.result-title h2{margin:10px 0 6px;font-size:clamp(40px,5.6vw,76px);line-height:.84;letter-spacing:-.045em;font-weight:900}
.result-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--muted)}
.result-meta i{width:3px;height:3px;border-radius:50%;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.result-title .modal-sub{margin:10px 0 0;font-size:9px;letter-spacing:.24em;color:var(--cyan)}
.rank-wrap{position:relative;display:flex;flex-direction:column;align-items:flex-end;gap:8px;min-width:190px;min-height:150px;justify-content:center}
.rank-orbit{position:absolute;right:14px;top:50%;width:158px;height:158px;transform:translateY(-50%);pointer-events:none}
.rank-orbit i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(94,231,255,.18)}
.rank-orbit i:nth-child(1){border-style:dashed;animation:rankSpin 22s linear infinite}
.rank-orbit i:nth-child(2){inset:18px;border-color:rgba(255,95,210,.2);animation:rankSpin 16s linear infinite reverse}
.rank-orbit i:nth-child(3){inset:38px;border-color:rgba(94,231,255,.28);box-shadow:0 0 26px rgba(94,231,255,.12) inset}
@keyframes rankSpin{to{transform:rotate(360deg)}}
#rank{position:relative;font-size:clamp(92px,12vw,150px);line-height:.72;font-weight:900;letter-spacing:-.07em;font-style:italic;color:#fff;text-shadow:0 0 40px rgba(94,231,255,.85),0 0 110px rgba(255,95,210,.5)}
.best-badge{display:none;font-family:var(--mono);font-size:8px;letter-spacing:.24em;color:#04040c;background:var(--cyan);padding:5px 10px;box-shadow:0 0 26px rgba(94,231,255,.45)}
.best-badge.on{display:block;animation:bestPop .5s cubic-bezier(.2,.8,.2,1) both}
@keyframes bestPop{0%{opacity:0;transform:translateY(6px) scale(.92)}100%{opacity:1;transform:none}}

.result-hero{
  display:grid;grid-template-columns:1.5fr .9fr 1fr;align-items:center;gap:18px;
  margin:20px 0 16px;padding:18px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  position:relative;z-index:1;
}
.hero-score span,.hero-combo span{display:block;font-family:var(--mono);font-size:8px;letter-spacing:.28em;color:var(--muted);margin-bottom:8px}
.hero-score b{display:block;font-family:var(--mono);font-size:clamp(32px,4.2vw,54px);line-height:1;letter-spacing:.04em;font-weight:800;color:#fff;font-variant-numeric:tabular-nums;text-shadow:0 0 30px rgba(94,231,255,.35)}
.hero-score em{display:block;margin-top:9px;font-style:normal;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--cyan);min-height:12px}
.hero-acc{display:flex;justify-content:center}
.acc-ring{
  width:118px;height:118px;border-radius:50%;position:relative;display:flex;flex-direction:column;
  align-items:center;justify-content:center;
  background:conic-gradient(var(--cyan) var(--acc,0%),rgba(120,160,220,.12) 0);
  box-shadow:0 0 34px rgba(94,231,255,.16);
}
.acc-ring::before{content:"";position:absolute;inset:6px;border-radius:50%;background:#060a17;border:1px solid rgba(148,190,255,.12)}
.acc-ring b{position:relative;z-index:1;font-family:var(--mono);font-size:21px;letter-spacing:.02em;color:#fff}
.acc-ring small{position:relative;z-index:1;margin-top:4px;font-family:var(--mono);font-size:7px;letter-spacing:.22em;color:var(--muted)}
.hero-combo{text-align:right}
.hero-combo b{display:block;font-family:var(--mono);font-size:clamp(30px,3.6vw,44px);line-height:1;color:#fff;font-weight:700}
.fc{display:inline-block;margin-top:10px;font-family:var(--mono);font-size:8px;letter-spacing:.24em;color:var(--cyan);border:1px solid rgba(94,231,255,.45);padding:7px 10px;opacity:0;transform:translateY(4px);transition:.3s}
.fc.on{opacity:1;transform:none;box-shadow:0 0 20px rgba(94,231,255,.18)}

.result-body{display:grid;grid-template-columns:1.05fr 1fr;gap:clamp(18px,3vw,38px);position:relative;z-index:1}
.panel-title{font-family:var(--mono);font-size:8px;letter-spacing:.28em;color:var(--cyan);margin-bottom:13px}
.judge-list{display:flex;flex-direction:column;gap:9px}
.judge-row{display:grid;grid-template-columns:62px 1fr 38px;align-items:center;gap:9px;font-family:var(--mono);font-size:8px;letter-spacing:.14em;color:var(--muted)}
.judge-row i{height:5px;background:rgba(140,190,255,.1);position:relative;overflow:hidden;border-radius:1px}
.judge-row i b{position:absolute;inset:0 auto 0 0;width:0;background:currentColor;box-shadow:0 0 10px currentColor;transition:width .7s cubic-bezier(.2,.8,.2,1)}
.judge-row em{font-style:normal;text-align:right;font-size:10px;color:#e2f1ff}
.judge-row.perfect{color:#a9f6ff}.judge-row.great{color:#73e6ff}.judge-row.good{color:#a8a5ff}.judge-row.bad{color:#ffb07a}.judge-row.miss{color:#ff4e75}
.combo-panel svg{width:100%;height:104px;display:block;border:1px solid rgba(148,190,255,.12);background:rgba(4,8,20,.5)}
.combo-meta{display:flex;justify-content:space-between;margin-top:10px;font-family:var(--mono);font-size:8px;letter-spacing:.16em;color:var(--muted)}
.combo-meta b{color:#dff6ff;font-weight:500}

.result-foot{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;margin-top:20px;padding-top:16px;border-top:1px solid var(--line);position:relative;z-index:1}
.result-footline{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--muted)}
.result-footline b{color:#dff6ff;font-weight:500;margin-right:10px}
.result-foot .btnrow{flex-wrap:nowrap}

/* ---------------- results transition ---------------- */
/* The compile screen is purely decorative: it fades out over the results card,
   and must never swallow clicks aimed at RETRY / MENU. */
#resultLoading,#resultLoading *{pointer-events:none}
#resultLoading.transition{
  z-index:30;background:
    radial-gradient(ellipse at 50% 46%,rgba(12,24,54,.55),transparent 62%),
    #02030a;
  backdrop-filter:none;
}
#resultLoading.transition::before{opacity:.5;mask-image:radial-gradient(ellipse at 50% 50%,#000 0%,transparent 68%)}
.compile{
  width:min(820px,100%);display:grid;grid-template-columns:auto 1fr;align-items:center;
  gap:clamp(20px,5vw,56px);position:relative;
}
.compile-orbit{width:clamp(120px,18vw,180px);aspect-ratio:1;position:relative;display:grid;place-items:center}
.compile-orbit i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(94,231,255,.28)}
.compile-orbit i:nth-child(1){border-style:dashed;animation:compileSpin 7s linear infinite;box-shadow:0 0 30px rgba(94,231,255,.1) inset}
.compile-orbit i:nth-child(2){inset:14%;border-color:rgba(255,95,210,.3);animation:compileSpin 4.4s linear infinite reverse}
.compile-orbit i:nth-child(3){inset:30%;border-color:rgba(94,231,255,.4);animation:compilePulse 1.8s ease-in-out infinite}
@keyframes compileSpin{to{transform:rotate(360deg)}}
@keyframes compilePulse{0%,100%{transform:scale(1);opacity:.7}50%{transform:scale(1.12);opacity:1}}
.compile-core{
  width:44%;aspect-ratio:1;border-radius:50%;display:grid;place-items:center;position:relative;z-index:1;
  background:radial-gradient(circle at 35% 30%,rgba(94,231,255,.4),rgba(10,18,40,.95) 66%);
  border:1px solid rgba(94,231,255,.5);box-shadow:0 0 42px rgba(94,231,255,.35),0 0 60px rgba(255,95,210,.14) inset;
}
.compile-core span{font-family:var(--mono);font-size:clamp(22px,3.4vw,34px);font-weight:800;font-style:italic;color:#fff;text-shadow:0 0 20px rgba(94,231,255,.8)}
.compile-copy h2{margin:8px 0 6px;font-size:clamp(34px,5.2vw,64px);line-height:.86;letter-spacing:-.045em;font-weight:900}
.compile-copy h2 span{color:transparent;-webkit-text-stroke:1px rgba(94,231,255,.7);text-shadow:0 0 32px rgba(94,231,255,.25)}
.compile-copy p{margin:0 0 22px;font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--muted)}
.compile-progress{height:3px;background:rgba(140,190,255,.14);position:relative;overflow:hidden}
.compile-progress b{display:block;height:100%;width:0%;background:linear-gradient(90deg,var(--cyan),var(--magenta));box-shadow:0 0 16px var(--cyan)}
.compile-meta{display:flex;justify-content:space-between;margin-top:9px;font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted)}
.compile-meta span:first-child{color:var(--cyan)}
.compile-bars{position:absolute;left:0;right:0;bottom:-54px;height:38px;display:flex;align-items:flex-end;gap:5px;opacity:.7}
.compile-bars i{flex:1;background:linear-gradient(180deg,var(--cyan),rgba(94,231,255,0));transform-origin:bottom;animation:compileBar 1.1s ease-in-out infinite}
.compile-bars i:nth-child(3n){background:linear-gradient(180deg,var(--magenta),rgba(255,95,210,0));animation-duration:1.5s}
.compile-bars i:nth-child(2n){animation-delay:.18s}
.compile-bars i:nth-child(3n+1){animation-delay:.34s}
.compile-bars i:nth-child(4n){animation-delay:.52s}
@keyframes compileBar{0%,100%{height:12%;opacity:.35}50%{height:100%;opacity:1}}

#flash{
  position:fixed;inset:0;z-index:20;pointer-events:none;background:#fff;opacity:0;
  mix-blend-mode:screen;transition:opacity .18s ease;
}
#flash.on{transition:opacity .04s ease}


#toast{
  position:absolute;left:50%;top:22%;transform:translate(-50%,-8px);
  font-family:var(--mono);font-size:11px;letter-spacing:.28em;color:#fff;
  background:rgba(4,8,20,.8);border:1px solid var(--line);padding:10px 16px;
  opacity:0;transition:.3s;pointer-events:none;white-space:nowrap;
}
#toast.on{opacity:1;transform:translate(-50%,0)}

#rotateHint{
  display:none;position:absolute;left:50%;bottom:calc(max(12px,env(safe-area-inset-bottom)) + 68px);
  transform:translateX(-50%);font-family:var(--mono);font-size:8px;letter-spacing:.18em;
  color:var(--muted);pointer-events:none;
}
#rotateHint span{color:var(--cyan);font-size:12px}

