// last available sixteenths before the dawn and keep the same lane safety.
let topT = 2.0;
while (notes.length < TARGET) {
  const sec = sections.find((s) => topT >= s.start && topT < s.end && s.notes);
  if (!sec) { topT += 0.137; if (topT > 203) topT = 2.0; continue; }
  const active = ACTIVE[sec.keys] || ACTIVE[8];
  const lane = active[Math.floor(rng() * active.length)];
  if (place(topT, lane) || place(topT + 0.003, lane)) { /* accepted */ }
  topT += 0.061;
  if (topT > 203.8) topT = 2.0;
}
notes.sort((a, b) => a.t - b.t || a.lane - b.lane);
