for (let t = 6; t < 204; t += 8) {
  push(t, { type: 'bossGlitch', power: 0.55 + rng() * 0.5 });
  push(t, { type: 'vibe', power: 0.8 });
  push(t + 0.03, { type: 'pulse', power: 1.1 });
