  [160, 'CHAPTER 03 // STILL HERE', 'DO NOT MOVE THE JACKET', 'KAI', 'kai'],
  [183, 'CHAPTER ?? // SIGNAL NOT FOUND', 'THE THIRD VOICE IS UNDER THE STATIC', 'NOVA', 'nova'],
