440:   // ---------------------------------------------------------------- void motes
441:   const MOTES = 420;
442:   const mPos = new Float32Array(MOTES * 3);
443:   const mBase = new Float32Array(MOTES * 3);
444:   const mPhase = new Float32Array(MOTES);
445:   for (let i = 0; i < MOTES; i++) {
446:     const x = (Math.random() - .5) * 64;
447:     const y = -3 + Math.random() * 24;
448:     const z = -26 + Math.random() * 42;
449:     mBase[i * 3] = x; mBase[i * 3 + 1] = y; mBase[i * 3 + 2] = z;
450:     mPos[i * 3] = x; mPos[i * 3 + 1] = y; mPos[i * 3 + 2] = z;
451:     mPhase[i] = Math.random() * 6.28;
452:   }
453:   const mGeo = new THREE.BufferGeometry();
454:   mGeo.setAttribute('position', new THREE.BufferAttribute(mPos, 3));
455:   const mMat = new THREE.PointsMaterial({
456:     size: .34, map: T.glow, color: 0xffffff, transparent: true, opacity: 0,
457:     depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true, fog: false,
458:   });
459:   const motes = new THREE.Points(mGeo, mMat);
460:   motes.renderOrder = 6;
461:   root.add(motes);
