463:   // ---------------------------------------------------------------- memories
464:   const memories = [];
465:   for (let i = 0; i < 18; i++) {
466:     const mat = new THREE.SpriteMaterial({
467:       map: T.glow, color: i % 3 ? 0xff5f7f : 0xffd166, transparent: true, opacity: 0,
468:       depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending, fog: false,
469:     });
470:     const s = new THREE.Sprite(mat);
471:     s.scale.set(.8 + Math.random() * 1.8, .8 + Math.random() * 1.8, 1);
472:     s.renderOrder = -8;
473:     root.add(s);
474:     memories.push({
475:       sprite: s, mat, x: (Math.random() - .5) * 18,
476:       z: -20 - Math.random() * 28,
477:       phase: Math.random() * 6.28,
478:       speed: .5 + Math.random() * .7,
479:     });
480:   }
481: 
482:   // ---------------------------------------------------------------- update
483:   let time = 0;
484:   let pulse = 0;
485: 
486:   function setPhase(phase) {
487:     level.phase = phase;
488:     const t = phaseTable[phase] || phaseTable.off;
489:     target.world = t.world ?? 0;
490:     target.void = t.void ?? 0;
491:     target.flowers = t.flowers ?? 0;
492:     target.pillars = t.pillars ?? 0;
493:     target.halo = t.halo ?? 0;
494:     target.memory = t.memory ?? 0;
495:     target.bright = t.bright ?? 0;
496:     // The guilt/glitch transitions are cuts, not dissolves: black them out on
497:     // the downbeat so no ocean or libra silhouette leaks into the void.
498:     if (phase === 'guilt' || phase === 'fake' || phase === 'offbeat' || phase === 'fastbeat') {
499:       level.world = Math.min(level.world, target.world + 0.01);
500:       level.flowers = Math.min(level.flowers, target.flowers + 0.01);
501:       level.pillars = Math.min(level.pillars, target.pillars + 0.01);
502:       level.halo = Math.min(level.halo, target.halo + 0.01);
503:       level.memory = Math.min(level.memory, target.memory + 0.01);
504:     }
505:   }
506: 
507:   function setActive(on) {
508:     level.active = !!on;
509:     root.visible = !!on;
510:     if (!on) {
511:       level.phase = 'off';
512:       for (const k of Object.keys(target)) target[k] = 0;
513:     }
514:   }
515: 
516:   function beat(power = 1) {
517:     pulse = Math.max(pulse, Math.min(1.4, power));
518:     for (const p of pillars) p.flash = Math.max(p.flash, power * .8);
519:   }
520: 
521:   function glitch(power = 1) {
522:     level.glitch = Math.min(2.2, level.glitch + power);
523:   }
524: 
525:   function update(dt, songTime) {
526:     if (!level.active) return;
527:     time = songTime;
528:     pulse *= Math.exp(-dt * 4.2);
529:     level.glitch *= Math.exp(-dt * 4.8);
530:     for (const k of Object.keys(target)) {
531:       level[k] += (target[k] - level[k]) * (1 - Math.exp(-dt * 2.6));
532:     }
533: 
534:     const world = level.world;
535:     const voidA = level.void;
536:     const gl = level.glitch;
537: 
538:     root.visible = world > .012 || voidA > .012 || level.flowers > .01;
539:     skyMat.opacity = world * (.9 + level.bright * .08);
540:     oceanMat.opacity = world * .94;
541:     T.ocean.offset.x = (time * .005) % 1;
542:     T.ocean.offset.y = (time * .013) % 1;
543:     ocean.position.x = Math.sin(time * .04) * 2;
544: 
545:     // The libra breathes with the pulse and tilts like a real balance.
546:     libra.position.y = -5.4 + Math.sin(time * .38) * .08;
547:     libra.rotation.z = Math.sin(time * .31) * .012 + (pulse * .006);
548:     beam.rotation.z = Math.sin(time * .5) * .025 + Math.sin(time * .17) * .012;
549:     beam.rotation.y = Math.sin(time * .2) * .03;
550:     beamCap.scale.setScalar(1 + pulse * .18);
551:     halo.rotation.y += dt * (1.1 + pulse * 2.2);
552:     halo.rotation.z += dt * .45;
553:     halo.rotation.x = Math.sin(time * .3) * .12;
554:     const hf = level.halo;
555:     star.scale.set(4.2 * (1 + pulse * .16), 4.2 * (1 + pulse * .16), 1);
556:     starMat.opacity = (world * .55 + hf * .4) * (0.85 + pulse * .15);
557:     haloMats[1].opacity = hf * (.5 + pulse * .25);
558:     haloMats[2].opacity = hf * (.32 + pulse * .2);
559:     haloMats[3].opacity = hf * (.2 + pulse * .14);
560:     haloMats[4].opacity = hf * (.07 + pulse * .07);
561:     for (const m of libraMats) {
562:       if (m === goldMat) m.opacity = world * .96;
563:       else if (m === paleMat) m.opacity = world * .92;
564:       else if (m === darkMat) m.opacity = world * .8;
565:       else m.opacity = world * .55;
566:     }
567:     for (const m of haloMats) if (m !== starMat) { /* handled above */ }
568: 
569:     // Clouds drift; a slow parallax keeps the sky from feeling painted on.
570:     for (const c of clouds) {
571:       c.sprite.position.x = c.x + Math.sin(time * .035 + c.phase) * 3.2;
572:       c.sprite.position.y += Math.sin(time * .055 + c.phase) * dt * .12;
573:       c.mat.opacity = world * c.base * (.85 + .15 * Math.sin(time * .2 + c.phase));
574:     }
575: 
576:     // Flowers ride the swell and open up at dawn.
577:     const open = Math.min(1.8, level.flowers);
578:     fMat.opacity = world * Math.min(1, .18 + open * .68);
579:     fMat.size = 1.05 + open * .2;
580:     // The dawn uncovers the whole bloom, not just the petals already on screen.
581:     fGeo.setDrawRange(0, Math.min(FLOWERS, Math.floor(FLOWERS * (.62 + Math.min(.5, open * .36)))));
582:     for (let i = 0; i < FLOWERS; i++) {
583:       const ph = fPhase[i];
584:       const x = fBase[i * 3];
585:       const y = fBase[i * 3 + 1] + Math.sin(time * .75 + ph) * .16 + Math.sin(time * .27 + ph * 2.1) * .1;
586:       const z = fBase[i * 3 + 2];
587:       fPos[i * 3] = x + Math.sin(time * .19 + ph) * .45;
588:       fPos[i * 3 + 1] = y + open * .1;
589:       fPos[i * 3 + 2] = z;
590:     }
591:     fGeo.attributes.position.needsUpdate = true;
592: 
593:     // Pillars grow out of the ocean, then keep a slow ember pulse.
594:     for (const p of pillars) {
595:       const wanted = level.pillars * (1 + Math.sin(time * .33 + p.def.x * .04) * .012);
