.tc-copy{display:flex;flex-direction:column;gap:3px;min-width:0}
.tc-copy b{font-size:13px;letter-spacing:.12em;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tc-copy em{font-style:normal;font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted)}
.tc-tags{display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end}
.tc-tags span{font-family:var(--mono);font-size:7px;letter-spacing:.12em;color:#a9c3de;border:1px solid rgba(140,190,255,.2);padding:3px 5px;white-space:nowrap}
.tc-tags .thumb{color:#04040c;background:var(--card-accent);border-color:var(--card-accent)}
.tc-best{font-family:var(--mono);font-size:8px;color:var(--card-accent,var(--cyan))}
.tc-best:empty{display:none}

/* ---------------- results v2 ---------------- */
.results{
  width:min(1080px,100%);position:relative;overflow:hidden;
  border:1px solid rgba(148,190,255,.24);background:rgba(5,8,19,.88);
  backdrop-filter:blur(18px);padding:clamp(22px,3.4vw,44px);
  box-shadow:0 40px 120px rgba(0,0,0,.7),0 0 90px rgba(94,231,255,.06) inset;
  animation:modalIn .5s cubic-bezier(.2,.7,.2,1) both;
}
.results::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:
    radial-gradient(ellipse at 88% 6%,rgba(94,231,255,.12),transparent 44%),
    radial-gradient(ellipse at 4% 100%,rgba(255,95,210,.09),transparent 50%);
}
.results::after{
  content:"";position:absolute;left:0;right:0;top:0;height:1px;
  background:linear-gradient(90deg,transparent,var(--cyan),var(--magenta),transparent);
  box-shadow:0 0 20px var(--cyan);
}
.result-head{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;position:relative;z-index:1}
.result-title h2{margin:10px 0 6px;font-size:clamp(40px,5.6vw,76px);line-height:.84;letter-spacing:-.045em;font-weight:900}
.result-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--muted)}
.result-meta i{width:3px;height:3px;border-radius:50%;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.result-title .modal-sub{margin:10px 0 0;font-size:9px;letter-spacing:.24em;color:var(--cyan)}
.rank-wrap{position:relative;display:flex;flex-direction:column;align-items:flex-end;gap:8px;min-width:190px;min-height:150px;justify-content:center}
.rank-orbit{position:absolute;right:14px;top:50%;width:158px;height:158px;transform:translateY(-50%);pointer-events:none}
.rank-orbit i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(94,231,255,.18)}
.rank-orbit i:nth-child(1){border-style:dashed;animation:rankSpin 22s linear infinite}
.rank-orbit i:nth-child(2){inset:18px;border-color:rgba(255,95,210,.2);animation:rankSpin 16s linear infinite reverse}
.rank-orbit i:nth-child(3){inset:38px;border-color:rgba(94,231,255,.28);box-shadow:0 0 26px rgba(94,231,255,.12) inset}
@keyframes rankSpin{to{transform:rotate(360deg)}}
#rank{position:relative;font-size:clamp(92px,12vw,150px);line-height:.72;font-weight:900;letter-spacing:-.07em;font-style:italic;color:#fff;text-shadow:0 0 40px rgba(94,231,255,.85),0 0 110px rgba(255,95,210,.5)}
.best-badge{display:none;font-family:var(--mono);font-size:8px;letter-spacing:.24em;color:#04040c;background:var(--cyan);padding:5px 10px;box-shadow:0 0 26px rgba(94,231,255,.45)}
.best-badge.on{display:block;animation:bestPop .5s cubic-bezier(.2,.8,.2,1) both}
@keyframes bestPop{0%{opacity:0;transform:translateY(6px) scale(.92)}100%{opacity:1;transform:none}}

.result-hero{
  display:grid;grid-template-columns:1.5fr .9fr 1fr;align-items:center;gap:18px;
  margin:20px 0 16px;padding:18px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  position:relative;z-index:1;
}
.hero-score span,.hero-combo span{display:block;font-family:var(--mono);font-size:8px;letter-spacing:.28em;color:var(--muted);margin-bottom:8px}
.hero-score b{display:block;font-family:var(--mono);font-size:clamp(32px,4.2vw,54px);line-height:1;letter-spacing:.04em;font-weight:800;color:#fff;font-variant-numeric:tabular-nums;text-shadow:0 0 30px rgba(94,231,255,.35)}
.hero-score em{display:block;margin-top:9px;font-style:normal;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--cyan);min-height:12px}
.hero-acc{display:flex;justify-content:center}
.acc-ring{
  width:118px;height:118px;border-radius:50%;position:relative;display:flex;flex-direction:column;
  align-items:center;justify-content:center;
  background:conic-gradient(var(--cyan) var(--acc,0%),rgba(120,160,220,.12) 0);
  box-shadow:0 0 34px rgba(94,231,255,.16);
}
.acc-ring::before{content:"";position:absolute;inset:6px;border-radius:50%;background:#060a17;border:1px solid rgba(148,190,255,.12)}
.acc-ring b{position:relative;z-index:1;font-family:var(--mono);font-size:21px;letter-spacing:.02em;color:#fff}
.acc-ring small{position:relative;z-index:1;margin-top:4px;font-family:var(--mono);font-size:7px;letter-spacing:.22em;color:var(--muted)}
.hero-combo{text-align:right}
.hero-combo b{display:block;font-family:var(--mono);font-size:clamp(30px,3.6vw,44px);line-height:1;color:#fff;font-weight:700}
.fc{display:inline-block;margin-top:10px;font-family:var(--mono);font-size:8px;letter-spacing:.24em;color:var(--cyan);border:1px solid rgba(94,231,255,.45);padding:7px 10px;opacity:0;transform:translateY(4px);transition:.3s}
.fc.on{opacity:1;transform:none;box-shadow:0 0 20px rgba(94,231,255,.18)}

.result-body{display:grid;grid-template-columns:1.05fr 1fr;gap:clamp(18px,3vw,38px);position:relative;z-index:1}
.panel-title{font-family:var(--mono);font-size:8px;letter-spacing:.28em;color:var(--cyan);margin-bottom:13px}
.judge-list{display:flex;flex-direction:column;gap:9px}
.judge-row{display:grid;grid-template-columns:62px 1fr 38px;align-items:center;gap:9px;font-family:var(--mono);font-size:8px;letter-spacing:.14em;color:var(--muted)}
.judge-row i{height:5px;background:rgba(140,190,255,.1);position:relative;overflow:hidden;border-radius:1px}
.judge-row i b{position:absolute;inset:0 auto 0 0;width:0;background:currentColor;box-shadow:0 0 10px currentColor;transition:width .7s cubic-bezier(.2,.8,.2,1)}
.judge-row em{font-style:normal;text-align:right;font-size:10px;color:#e2f1ff}
.judge-row.perfect{color:#a9f6ff}.judge-row.great{color:#73e6ff}.judge-row.good{color:#a8a5ff}.judge-row.bad{color:#ffb07a}.judge-row.miss{color:#ff4e75}
.combo-panel svg{width:100%;height:104px;display:block;border:1px solid rgba(148,190,255,.12);background:rgba(4,8,20,.5)}
.combo-meta{display:flex;justify-content:space-between;margin-top:10px;font-family:var(--mono);font-size:8px;letter-spacing:.16em;color:var(--muted)}
.combo-meta b{color:#dff6ff;font-weight:500}

.result-foot{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;margin-top:20px;padding-top:16px;border-top:1px solid var(--line);position:relative;z-index:1}
.result-footline{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--muted)}
.result-footline b{color:#dff6ff;font-weight:500;margin-right:10px}
.result-foot .btnrow{flex-wrap:nowrap}

/* ---------------- results transition ---------------- */
/* The compile screen is purely decorative: it fades out over the results card,
   and must never swallow clicks aimed at RETRY / MENU. */
#resultLoading,#resultLoading *{pointer-events:none}
#resultLoading.transition{
  z-index:30;background:
    radial-gradient(ellipse at 50% 46%,rgba(12,24,54,.55),transparent 62%),
    #02030a;
  backdrop-filter:none;
}
#resultLoading.transition::before{opacity:.5;mask-image:radial-gradient(ellipse at 50% 50%,#000 0%,transparent 68%)}
.compile{
  width:min(820px,100%);display:grid;grid-template-columns:auto 1fr;align-items:center;
  gap:clamp(20px,5vw,56px);position:relative;
}
.compile-orbit{width:clamp(120px,18vw,180px);aspect-ratio:1;position:relative;display:grid;place-items:center}
.compile-orbit i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(94,231,255,.28)}
.compile-orbit i:nth-child(1){border-style:dashed;animation:compileSpin 7s linear infinite;box-shadow:0 0 30px rgba(94,231,255,.1) inset}
.compile-orbit i:nth-child(2){inset:14%;border-color:rgba(255,95,210,.3);animation:compileSpin 4.4s linear infinite reverse}
.compile-orbit i:nth-child(3){inset:30%;border-color:rgba(94,231,255,.4);animation:compilePulse 1.8s ease-in-out infinite}
@keyframes compileSpin{to{transform:rotate(360deg)}}
@keyframes compilePulse{0%,100%{transform:scale(1);opacity:.7}50%{transform:scale(1.12);opacity:1}}
.compile-core{
  width:44%;aspect-ratio:1;border-radius:50%;display:grid;place-items:center;position:relative;z-index:1;
  background:radial-gradient(circle at 35% 30%,rgba(94,231,255,.4),rgba(10,18,40,.95) 66%);

  background:radial-gradient(circle at 35% 30%,rgba(94,231,255,.4),rgba(10,18,40,.95) 66%);
  border:1px solid rgba(94,231,255,.5);box-shadow:0 0 42px rgba(94,231,255,.35),0 0 60px rgba(255,95,210,.14) inset;
}
.compile-core span{font-family:var(--mono);font-size:clamp(22px,3.4vw,34px);font-weight:800;font-style:italic;color:#fff;text-shadow:0 0 20px rgba(94,231,255,.8)}
.compile-copy h2{margin:8px 0 6px;font-size:clamp(34px,5.2vw,64px);line-height:.86;letter-spacing:-.045em;font-weight:900}
.compile-copy h2 span{color:transparent;-webkit-text-stroke:1px rgba(94,231,255,.7);text-shadow:0 0 32px rgba(94,231,255,.25)}
.compile-copy p{margin:0 0 22px;font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--muted)}
.compile-progress{height:3px;background:rgba(140,190,255,.14);position:relative;overflow:hidden}
.compile-progress b{display:block;height:100%;width:0%;background:linear-gradient(90deg,var(--cyan),var(--magenta));box-shadow:0 0 16px var(--cyan)}
.compile-meta{display:flex;justify-content:space-between;margin-top:9px;font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted)}
.compile-meta span:first-child{color:var(--cyan)}
.compile-bars{position:absolute;left:0;right:0;bottom:-54px;height:38px;display:flex;align-items:flex-end;gap:5px;opacity:.7}
.compile-bars i{flex:1;background:linear-gradient(180deg,var(--cyan),rgba(94,231,255,0));transform-origin:bottom;animation:compileBar 1.1s ease-in-out infinite}
.compile-bars i:nth-child(3n){background:linear-gradient(180deg,var(--magenta),rgba(255,95,210,0));animation-duration:1.5s}
.compile-bars i:nth-child(2n){animation-delay:.18s}
.compile-bars i:nth-child(3n+1){animation-delay:.34s}
.compile-bars i:nth-child(4n){animation-delay:.52s}
@keyframes compileBar{0%,100%{height:12%;opacity:.35}50%{height:100%;opacity:1}}

#flash{
  position:fixed;inset:0;z-index:20;pointer-events:none;background:#fff;opacity:0;
  mix-blend-mode:screen;transition:opacity .18s ease;
}
#flash.on{transition:opacity .04s ease}


#toast{
  position:absolute;left:50%;top:22%;transform:translate(-50%,-8px);
  font-family:var(--mono);font-size:11px;letter-spacing:.28em;color:#fff;
  background:rgba(4,8,20,.8);border:1px solid var(--line);padding:10px 16px;
  opacity:0;transition:.3s;pointer-events:none;white-space:nowrap;
}
#toast.on{opacity:1;transform:translate(-50%,0)}

#rotateHint{
  display:none;position:absolute;left:50%;bottom:calc(max(12px,env(safe-area-inset-bottom)) + 68px);
  transform:translateX(-50%);font-family:var(--mono);font-size:8px;letter-spacing:.18em;
  color:var(--muted);pointer-events:none;
}
#rotateHint span{color:var(--cyan);font-size:12px}

/* ---------------- responsive ---------------- */
@media (max-width:900px){
  .overlay{background:linear-gradient(180deg,rgba(2,3,10,.94),rgba(2,3,10,.72) 55%,rgba(2,3,10,.9));align-items:flex-start;padding-top:6vh}
  .start-grid{grid-template-columns:1fr;gap:26px}
  .start-side{display:grid;grid-template-columns:1fr 1fr;gap:10px}
  .credit{grid-column:1/-1}
  .start-copy h1{font-size:clamp(76px,19vw,130px)}
  .specs{max-width:none}
  .topbar{grid-template-columns:1fr 1.3fr;gap:14px}
  .track-wrap{grid-column:1/-1;grid-row:2;order:3}
  .scoreblock{position:absolute;right:clamp(14px,4vw,30px);top:clamp(14px,4vw,30px)}
  .left-hud{bottom:clamp(100px,14vh,150px)}
  #comboHud{left:24%;top:41%}
  #judge{top:52%}
}

/* short desktop/laptop windows: keep the whole start screen on one page */
@media (max-height:860px) and (min-width:721px){
  .start-copy h1{font-size:clamp(80px,12vw,150px);margin:12px 0 8px}
  .tagline{margin-bottom:18px}
  .specs{padding:11px 0;margin-bottom:18px}
  .start-side{gap:11px}
  .panel{padding:16px 18px 14px}
  .panel-title{margin-bottom:11px}
  .touchline{margin-top:10px}
  .hint{margin-top:10px}
}

/* five-track picker on a 720p screen: keep the launch button above the fold */
@media (max-height:820px) and (min-width:721px){
  .start-copy h1{font-size:clamp(72px,10.6vw,132px);margin:10px 0 6px}
  .tagline{margin-bottom:12px}
  .track-picker{gap:4px;margin-bottom:12px}
  .track-card{padding:7px 11px}
  .specs{padding:9px 0;margin-bottom:12px}
  .cta{padding:12px 18px}
}

@media (max-width:620px){
  .start-side{display:none}
  .credit{text-align:left;display:none}
  .specs{grid-template-columns:repeat(2,1fr)}
  .start-copy h1{font-size:clamp(70px,23vw,110px)}
  .start-copy .tagline{font-size:14px;margin-bottom:20px}
  .cta{width:100%;min-width:0}
  .panel{padding:15px}
  .panel:nth-child(2){display:none}
  #rank{font-size:80px}
  .modal,.results{padding:22px}
  .topbar{padding-top:4px}
  .brand-title{font-size:16px}
  .brand-sub em,.brand-sub .slash{display:none}
  .brand-sub{display:flex;gap:6px;white-space:nowrap}
  .brand-sub em{display:inline;max-width:96px;overflow:hidden;text-overflow:ellipsis}
  .score{font-size:22px}
  .left-hud{display:none}
  #pauseBtn{width:34px;height:34px;bottom:max(10px,env(safe-area-inset-bottom));right:12px}
  #comboHud b{font-size:42px}
  #judge{font-size:11px;letter-spacing:.28em}

  /* compact modal + result layouts so they fit without scrolling */
  .results{padding:20px}
  .result-head{gap:12px}
  .results h2{font-size:44px;margin:12px 0 2px}
  .results .modal-sub{margin:8px 0 14px;font-size:9px}
  .result-foot{gap:10px}
  .fc:not(.on){display:none}
  .result-foot .btnrow{display:grid;grid-template-columns:1fr 1fr;width:100%}
  .result-foot .btnrow .cta,.result-foot .btnrow .ghost{width:100%;min-width:0}
  #resultScreen.show,#pauseScreen.show,#resultLoading.show{align-items:center;padding-top:18px}
  #resultLoading.show{padding-top:0}
  .best-line{display:block}
  .modal .btnrow{display:grid;grid-template-columns:1fr 1fr;width:100%}
  .modal .btnrow .cta{grid-column:span 2;width:100%}
  .modal .btnrow .ghost{width:100%}
}

@media (orientation:portrait) and (max-width:900px){
  body.playing #rotateHint{display:block;animation:rotateHintFade 9s ease forwards}
  .start-grid{padding-bottom:70px}
}
@keyframes rotateHintFade{0%,70%{opacity:1}100%{opacity:0}}

/* ---------------- results / transition responsive ---------------- */
@media (max-width:820px){
  .result-hero{grid-template-columns:1fr auto;gap:14px}
  .hero-combo{grid-column:1/-1;display:flex;align-items:center;gap:12px;text-align:left}
  .hero-combo span{margin:0}
  .fc{margin-top:0}
  .result-body{grid-template-columns:1fr;gap:16px}
  .combo-panel svg{height:82px}
  .rank-wrap{min-width:120px;min-height:110px}
  .rank-orbit{width:118px;height:118px;right:8px}
  #rank{font-size:74px}
  .result-head{gap:8px}
  .compile{grid-template-columns:1fr;justify-items:center;text-align:center;gap:18px}
  .compile-copy .eyebrow{justify-content:center}
  .compile-copy h2{font-size:38px}
  .compile-orbit{width:120px}
  .compile-bars{bottom:-58px;height:30px;gap:4px}
}

@media (max-width:620px){
  .results{padding:16px}
  .result-hero{grid-template-columns:1fr auto;padding:12px 0;margin:12px 0}
  .hero-score b{font-size:30px}
  .acc-ring{width:88px;height:88px}
  .acc-ring b{font-size:16px}
  .acc-ring small{font-size:6px}
  .result-title h2{font-size:40px}
  .result-meta{font-size:7px;gap:6px}
  .judge-row{grid-template-columns:50px 1fr 30px;font-size:7px}
