  .hero-score span,.hero-combo span{font-size:7px;margin-bottom:4px}
  .hero-score b{font-size:24px}
  .hero-score em{margin-top:4px;font-size:7px;min-height:9px}
  .acc-ring{width:64px;height:64px}
  .acc-ring::before{inset:4px}
  .acc-ring b{font-size:13px}
  .acc-ring small{font-size:5px;margin-top:1px}
  .hero-combo b{font-size:22px}
  .fc{margin-top:4px;padding:4px 7px;font-size:6px}
  .result-body{gap:16px}
  .panel-title{font-size:6px;margin-bottom:5px}
  .judge-list{gap:3px}
  .judge-row{grid-template-columns:44px 1fr 24px;gap:6px;font-size:6px}
  .judge-row i{height:4px}
  .judge-row em{font-size:7px}
  .combo-panel svg{height:48px}
  .combo-meta{margin-top:4px;font-size:6px}
  .result-foot{margin-top:6px;padding-top:6px;gap:8px}
  .result-footline{font-size:6px;gap:5px}
  .result-footline b{margin-right:4px}
  .result-foot .btnrow{flex-wrap:nowrap}
  .result-foot .cta.small{width:auto;min-width:120px;padding:8px 12px;font-size:9px}
  .result-foot .ghost{padding:8px 12px;font-size:9px}
