/* ---------------- pendulum centre tap (CHRONOSTASIS STASIS) ---------------- */
#centerPad{
  position:fixed;left:50%;top:52%;width:190px;height:190px;z-index:6;
  transform:translate(-50%,-50%) scale(.82);
  display:grid;place-items:center;
  padding:0;border:1px solid rgba(255,209,102,.5);border-radius:50%;
  background:radial-gradient(circle, rgba(255,209,102,.16), rgba(255,209,102,.05) 58%, transparent 72%);
  box-shadow:0 0 46px rgba(255,209,102,.22), inset 0 0 34px rgba(255,209,102,.1);
  opacity:0;visibility:hidden;pointer-events:none;
  transition:opacity .22s ease, transform .22s ease, visibility .22s;
  touch-action:none;overflow:visible;
}
#centerPad.show{
  opacity:1;visibility:visible;pointer-events:auto;
  transform:translate(-50%,-50%) scale(1);
}
#centerPad.pressed{

  position:absolute;left:-2%;right:-2%;top:50%;height:clamp(110px,19vh,210px);
  transform:translateY(-50%);opacity:.8;
  filter:drop-shadow(0 0 18px rgba(255,24,56,.7));
}
.go-flatline svg{width:100%;height:100%;overflow:visible}
.go-flatline path{
  fill:none;stroke:#ff2748;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;
  stroke-dasharray:1400;stroke-dashoffset:0;
  animation:go-flatline 2.2s ease-out both;
}
.go-title{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  display:flex;flex-direction:column;align-items:center;gap:12px;
  text-align:center;
}
.go-title b{
  font-family:var(--sans);font-size:clamp(40px,9vw,118px);font-weight:900;
  letter-spacing:.14em;color:#fff;line-height:.9;
  text-shadow:0 0 22px rgba(255,31,67,.95),0 0 80px rgba(255,0,40,.5);
  animation:go-title-glitch .9s steps(2,end) infinite;
}
.go-title span{
  font-family:var(--mono);font-size:9px;letter-spacing:.62em;color:#ff8fa2;
  text-indent:.62em;
}
body.intent-clean .go-title{display:none}

@keyframes go-pulse{0%,100%{opacity:.72;transform:scale(1)}50%{opacity:1;transform:scale(1.012)}}
@keyframes go-scan{0%{transform:translateY(-14vh)}100%{transform:translateY(114vh)}}
@keyframes go-flatline{0%{stroke-dashoffset:1400;opacity:0}16%{opacity:1}100%{stroke-dashoffset:0;opacity:1}}
@keyframes go-title-glitch{
  0%,100%{transform:translate(0,0);text-shadow:0 0 22px rgba(255,31,67,.95),0 0 80px rgba(255,0,40,.5)}
  24%{transform:translate(-2px,1px);text-shadow:3px 0 rgba(90,230,255,.8),-3px 0 rgba(255,0,40,.9)}
  48%{transform:translate(2px,-1px);text-shadow:-2px 0 rgba(90,230,255,.7),2px 0 rgba(255,0,40,.85)}
}

@media (max-width:900px){
  .go-title b{font-size:clamp(34px,12vw,74px)}
}

