    for (let i = 0; i < SPARKS; i++) {
      sPos[i * 3] += sVel[i * 3] * dt * (.7 + chaos * .9);
      sPos[i * 3 + 1] += sVel[i * 3 + 1] * dt;
      sPos[i * 3 + 2] += sVel[i * 3 + 2] * dt;
      if (sPos[i * 3] > 52) sPos[i * 3] = -52;
      else if (sPos[i * 3] < -52) sPos[i * 3] = 52;
      if (sPos[i * 3 + 1] > 34) sPos[i * 3 + 1] = -5;
