/* heartbeat line — a full-screen ECG that climbs one third of the screen per
   beat (bottom → middle → top) and pulses a concentric shockwave on every hit */
#heartbeat{
  position:fixed;inset:0;z-index:3;pointer-events:none;
  opacity:0;transition:opacity .5s ease;mix-blend-mode:screen;
  --hb-y:70%;
}
#heartbeat.on{opacity:1}
.hb-wash{
  position:absolute;inset:0;
  background:
    radial-gradient(ellipse at 50% var(--hb-y),rgba(255,38,80,.22),transparent 44%),
    radial-gradient(ellipse at 50% var(--hb-y),rgba(255,120,140,.10),transparent 24%),
    linear-gradient(180deg,transparent 0%,rgba(255,20,60,.045) 50%,transparent 100%);
  opacity:.7;transition:background .18s linear;
}
.hb-track{
  position:absolute;left:-2%;right:-2%;top:var(--hb-y);
  height:clamp(120px,21vh,230px);transform:translateY(-50%);
  transition:top .17s cubic-bezier(.2,.9,.25,1);
  filter:drop-shadow(0 0 20px rgba(255,51,85,.38));
  will-change:top,transform;
}
.hb-track svg{width:100%;height:100%;overflow:visible}
#heartbeat path{fill:none;stroke-linecap:round;stroke-linejoin:round}
.hb-ghost{stroke:rgba(255,90,120,.16);stroke-width:1;transform:translateY(-8px)}
.hb-split{stroke:rgba(90,230,255,.32);stroke-width:1.1;transform:translate(3px,-4px)}
.hb-glow{stroke:rgba(255,51,85,.30);stroke-width:17;filter:blur(11px)}
.hb-line{stroke:#ff5b73;stroke-width:2.3;filter:drop-shadow(0 0 7px rgba(255,51,85,.95))}
.hb-rings{position:absolute;left:50%;top:50%;width:0;height:0;pointer-events:none}
.hb-rings i{
  position:absolute;left:0;top:0;width:18vmin;height:18vmin;margin:-9vmin 0 0 -9vmin;
  border:1.5px solid rgba(255,92,120,.7);border-radius:50%;
  opacity:0;transform:scale(.15);box-shadow:0 0 22px rgba(255,51,85,.35) inset;
}
.hb-spark{
  position:absolute;left:50%;top:50%;width:9px;height:9px;margin:-4.5px 0 0 -4.5px;
  border-radius:50%;background:#fff;opacity:0;
  box-shadow:0 0 12px #fff,0 0 34px #ff3355,0 0 70px rgba(255,51,85,.8);
}
