/* Heartbeat performance pass: the same visual language without stacking three
   live SVG filters over the whole screen. The line keeps one small drop-shadow,
   the wide glow becomes a soft wide stroke, and the track is composited on its
   own layer instead of re-filtering every frame. */
#heartbeat{contain:layout paint;isolation:isolate;will-change:opacity;transform:translateZ(0)}
.hb-glow{filter:none;stroke:rgba(255,51,85,.22);stroke-width:25px}
.hb-line{filter:drop-shadow(0 0 5px rgba(255,51,85,.8))}
.hb-track{filter:none;will-change:transform,top;transform:translateZ(0)}
.hb-wash{will-change:opacity}
@media (max-width:900px){
  /* Two decorative echo layers are invisible at phone size; skipping them
     removes four full-width animations per heartbeat without changing the read. */
  .hb-ghost,.hb-split{display:none}
  #heartbeat.beat .hb-rings i:nth-child(3){animation:none}
  .hb-glow{stroke-width:20px}
}
@media (prefers-reduced-motion: reduce){
  #heartbeat.beat .hb-line,#heartbeat.beat .hb-glow,#heartbeat.beat .hb-ghost,
  #heartbeat.beat .hb-split,#heartbeat.beat .hb-spark,#heartbeat.beat .hb-track,
  #heartbeat.beat .hb-wash,#heartbeat.beat .hb-rings i{animation:none}
}
EOF
