670: function applyIntentHud(ev) {
671:   const on = ev.on !== false;
672:   switch (ev.hud) {
673:     case 'clear':
674:       clearIntentClasses();
675:       intent.guiltOn = false;
676:       intent.fakeGuilt = false;
677:       intent.heartOn = false;
678:       intent.screenGlitch = false;
679:       intent.forceSync = false;
680:       if (intent.notesHidden) setIntentNotesHidden(false);
681:       break;
682:     case 'black':
683:       // The 3D stage itself goes to black for the guilt sections; the class
684:       // only tints the HUD so the lanes stay readable on the pure void.
685:       document.body.classList.toggle('intent-black', on);
686:       break;
687:     case 'guilt':
688:       intent.guiltOn = on;
689:       intent.fakeGuilt = false;
690:       if (on) intent.guilt = ev.value ?? 100;
691:       document.body.classList.toggle('guilt-on', on);
692:       document.body.classList.remove('guilt-fake');
693:       if (dom.guiltCopy) dom.guiltCopy.textContent = 'CONSISTENT PERFECTS KEEP IT FULL';
694:       paintGuilt();
695:       break;
696:     case 'fakeGuilt':
697:       intent.fakeGuilt = on;
698:       intent.guiltOn = on;
699:       if (on) {
700:         intent.fakeBase = ev.value ?? 14;
701:         intent.fakeValue = intent.fakeBase;
702:         intent.fakeStart = audio.time;
703:       }
704:       document.body.classList.toggle('guilt-fake', on);
705:       document.body.classList.toggle('guilt-on', on);
706:       if (dom.guiltCopy) dom.guiltCopy.textContent = 'IT WILL NOT REFILL';
707:       paintGuilt();
708:       break;
709:     case 'heartbeat':
710:       intent.heartOn = on;
711:       if (ev.bpm) intent.heartBpm = ev.bpm;
712:       intent.hbAcc = 0;
713:       if (on) {
714:         intent.hbBeat = -1;
715:         setHeartbeatPosition(0);
716:       } else {
717:         intent.hbBeat = -1;
718:       }
719:       dom.heartbeat?.classList.toggle('on', on);
720:       document.body.classList.toggle('heartbeat-on', on);
721:       break;
722:     case 'glitch':
723:       intent.screenGlitch = on;
724:       document.body.classList.toggle('intent-glitch', on);
725:       break;
726:     case 'text':
727:       if (selectedTrack.theme === 'intention'
728:         && String(ev.text || '').trim().toUpperCase() !== 'INTENTION') break;
729:       if (on) showIntentText(ev.text, ev.sub, ev.hold ?? 3.2);
730:       else dom.intentText?.classList.remove('on');
731:       break;
732:     case 'static':
733:       document.body.classList.toggle('static-on', on);
734:       document.body.classList.toggle('static-heavy', on && (ev.power ?? 0) >= 0.9);
735:       // The memory movement keeps a thin, transparent veil; the later STATIC
736:       // section is the one that thickens into real interference.
737:       document.body.classList.toggle('static-soft', on && (ev.power ?? 0) < 0.9);
738:       break;
739:     case 'distort':
740:       document.body.classList.toggle('distort-on', on);
741:       break;
742:     case 'bright':
743:       document.body.classList.toggle('bright-on', on);
744:       break;
745:     case 'white':
746:       dom.whiteout?.classList.toggle('on', on);
747:       document.body.classList.toggle('intent-whiteout', on);
748:       break;
749:     case 'yellow':
750:       document.body.classList.toggle('intent-yellow', on);
751:       dom.yellow?.classList.toggle('on', on);
752:       break;
753:     case 'rainbow':
754:       intent.forceSync = on;
755:       dom.syncEl?.classList.toggle('rainbow', on);
756:       dom.rainbow?.classList.toggle('on', on);
757:       if (on) dom.energy.style.height = '100%';
758:       break;
759:     default:
760:       break;
761:   }
762: }
