874: // ---------------------------------------------------------------- judging
875: function judgeHit(note, offset) {
876:   const a = Math.abs(offset);
877:   let kind;
878:   if (a <= WIN.perfect) kind = 'perfect';
879:   else if (a <= WIN.great) kind = 'great';
880:   else if (a <= WIN.good) kind = 'good';
881:   else kind = 'bad';
882: 
883:   stats[kind]++;
884:   stats.judged++;
885:   stats.weight += WEIGHT[kind];
886:   stats.score += SCORE[kind];
887:   stats.health = Math.min(100, stats.health + (kind === 'perfect' ? 1.1 : kind === 'great' ? .8 : kind === 'good' ? .4 : -1.6));
888:   intentJudged(kind);
889: 
890:   if (kind === 'bad') {
891:     setCombo(0, false);
892:   } else {
893:     setCombo(stats.combo + 1);
894:   }
895: 
896:   if (note.type === 'hold') {
897:     note.state = 'holding';
898:     note.endTime = note.data.t + note.data.dur;
899:     note.tickAt = audio.time;
900:     note.head.visible = false;
901:     holdNote[note.lane] = note;
902:   } else {
903:     note.state = 'done';
904:     note.group.visible = false;
905:   }
906: 
907:   const text = kind === 'perfect' ? 'PERFECT' : kind === 'great' ? 'GREAT' : kind === 'good' ? 'GOOD' : 'BAD';
908:   showJudge(kind, text);
909:   scene.hitFx(note.lane, kind);
910:   audio.click(note.lane, kind === 'perfect' ? 0.52 : 0.38);
911: }
