954: function nearestNote(t, lane = null) {
955:   let best = null;
956:   let bestAbs = Infinity;
957:   for (const n of noteObjects) {
958:     if (n.state !== 'pending') continue;
959:     if (lane !== null && n.lane !== lane) continue;
960:     const d = t - n.data.t;
961:     if (d < -EARLY_WINDOW || d > HIT_WINDOW) continue;
962:     const a = Math.abs(d);
963:     // `<` (not `<=`) keeps the first note on a tied chord: the next finger
964:     // then claims the second one instead of stacking both on one tap.
965:     if (a < bestAbs - 1e-6) { bestAbs = a; best = n; }
966:   }
967:   return best;
968: }
