775: function intentJudged(kind) {
776:   if (!intent.guiltOn || intent.fakeGuilt) return;
777:   const gain = kind === 'perfect' ? 1.35
778:     : kind === 'great' ? 0.95
779:     : kind === 'good' ? 0.5
780:     : kind === 'bad' ? -2.2
781:     : -6;
782:   intent.guilt = Math.max(0, Math.min(100, intent.guilt + gain));
783:   paintGuilt();
784: }
