786: function updateIntent(dt, t) {
787:   if (intent.guiltOn && !intent.fakeGuilt) {
788:     // The bar drains faster while a stream is coming and slows down when the
789:     // chart thins out, so sparse phrases never punish the player for waiting.
790:     let ahead = 0;
791:     for (const n of noteObjects) {
792:       if (n.state === 'pending' && n.data.t >= t && n.data.t < t + 2.4) ahead++;
793:     }
794:     const density = ahead / 2.4;
795:     const drain = 0.5 + Math.min(1.5, density * 0.55);
796:     intent.guilt = Math.max(0, Math.min(100, intent.guilt - drain * dt));
797:     paintGuilt();
798:   }
799:   if (intent.fakeGuilt) {
800:     // Tie the decorative drain to the song clock, not frame time, so it still
801:     // reaches the shatter point on slow devices.
802:     const age = Math.max(0, audio.time - intent.fakeStart);
803:     intent.fakeValue = Math.max(2.6, intent.fakeBase - age * 0.5);
804:     paintGuilt();
805:   }
806:   if (intent.heartOn) {
807:     intent.hbAcc += dt;
808:     const interval = 60 / Math.max(40, intent.heartBpm);
809:     if (intent.hbAcc >= interval) {
810:       intent.hbAcc %= interval;
811:       // bottom → middle → top on successive beats, then repeat. The CSS
812:       // transition carries the line between positions while the ripple and
813:       // ECG flash fire on the beat itself.
814:       intent.hbBeat = (intent.hbBeat + 1) % 3;
815:       setHeartbeatPosition(intent.hbBeat);
816:       const el = dom.heartbeat;
817:       if (el) {
818:         // Restart the beat animation without forcing a synchronous layout.
819:         // The CSS animations are transform/opacity driven; a one-frame gap is
820:         // enough to replay them and avoids the full-screen reflow that used to
821:         // hitch the game on every heartbeat.
822:         el.classList.remove('beat');
823:         setTimeout(() => { if (intent.heartOn) el.classList.add('beat'); }, 18);
824:       }
825:     }
826:   } else {
827:     intent.hbAcc = 0;
828:   }
829:   if (intent.screenGlitch) {
830:     intent.glitchAcc += dt;
831:     if (intent.glitchAcc > 0.52 + Math.random() * 0.4) {
832:       intent.glitchAcc = 0;
833:       scene.bossGlitch(0.32 + Math.random() * 0.3);
834:       glitchScreen(0.45);
835:     }
836:   }
837: }
