847:   if (dom.hudBpm && sec.bpm) dom.hudBpm.textContent = `${Number(sec.bpm).toFixed(1).replace(/\.0$/, '')} BPM`;
848:   const active = new Set(activeLanesFor(sec.keys));
849:   for (const pad of dom.pads) {
