874: // ---------------------------------------------------------------- judging
875: function judgeHit(note, offset) {
876:   const a = Math.abs(offset);
877:   let kind;
878:   if (a <= WIN.perfect) kind = 'perfect';
879:   else if (a <= WIN.great) kind = 'great';
880:   else if (a <= WIN.good) kind = 'good';
881:   else kind = 'bad';
882: 
883:   stats[kind]++;
884:   stats.judged++;
885:   stats.weight += WEIGHT[kind];
