1073: function judgeSwing(note, offset) {
1074:   const a = Math.abs(offset);
1075:   let kind;
1076:   if (a <= WIN.perfect) kind = 'perfect';
1077:   else if (a <= WIN.great) kind = 'great';
1078:   else if (a <= WIN.good) kind = 'good';
1079:   else kind = 'bad';
1080: 
1081:   note.state = 'done';
1082:   stats[kind]++;
1083:   stats.judged++;
1084:   stats.weight += WEIGHT[kind];
1085:   stats.score += SCORE[kind];
1086:   stats.health = Math.min(100, stats.health + (kind === 'perfect' ? 1.2 : kind === 'great' ? .9 : kind === 'good' ? .5 : -1.4));
1087: 
1088:   if (kind === 'bad') setCombo(0, false);
1089:   else setCombo(stats.combo + 1);
1090: 
1091:   showJudge(kind, kind === 'perfect' ? 'PERFECT' : kind === 'great' ? 'GREAT' : kind === 'good' ? 'GOOD' : 'BAD');
1092:   scene.swingResolve(note.index, 'hit');
1093:   audio.click(3, kind === 'perfect' ? 0.56 : 0.4);
1094: }
