1120:   for (const n of swingNotes) {
1121:     if (n.state !== 'pending') continue;
1122:     const d = t - n.t;
1123:     if (d < -EARLY_WINDOW || d > HIT_WINDOW) continue;
1124:     const a = Math.abs(d);
1125:     if (a < bestAbs) { bestAbs = a; best = n; }
1126:   }
1127:   if (!best) {
1128:     scene.swingWhiff();
