1135: // ---------------------------------------------------------------- note render
1136: const SPEED = 8.4;
1137: let noteSpeed = SPEED;
1138: 
1139: function updateNotes(t) {
1140:   const ns = scene.noteScale;
1141:   for (const n of noteObjects) {
1142:     if (n.state === 'pending') {
1143:       const y = (n.data.t - t) * noteSpeed;
1144:       if (n.free) {
1145:         // Boss notes fly along a curved stage-space path and converge on the
1146:         // lane ring exactly at the hit line.
1147:         const pose = scene.freeNotePose(n.lane, y, n.index);
1148:         n.group.position.set(pose.x, pose.y, pose.z);
1149:       } else {
1150:         // local lane space: the lane frame supplies the diagonal world position
1151:         n.group.position.set(0, y, 0.24);
1152:       }
1153:       n.group.visible = y < 14.5 && y > -1.3;
1154:       n.head.scale.set(1.04 * ns, 1.04 * ns, 1);
1155:       if (n.body) {
1156:         const len = n.data.dur * noteSpeed;
1157:         n.body.visible = n.group.visible;
1158:         n.tail.visible = n.group.visible;
1159:         n.body.scale.set(0.52 * ns, len, 1);
1160:         n.body.position.y = len / 2;
1161:         n.body.material.rotation = n.free ? 0 : -scene.laneScreenAngle(n.lane);
1162:         n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
1163:         n.tail.position.y = len;
1164:       }
1165:       if (t > n.data.t + HIT_WINDOW && gameState === 'playing') missNote(n);
1166:     } else if (n.state === 'holding') {
1167:       if (!held[n.lane] && !touching()) { dropHold(n); continue; }
1168:       if (t >= n.endTime - 0.02) {
1169:         completeHold(n);
1170:         continue;
1171:       }
1172:       const remain = Math.max(0, (n.endTime - t) * noteSpeed);
1173:       n.group.visible = true;
1174:       if (n.free) {
1175:         const pose = scene.freeNotePose(n.lane, 0, n.index);
1176:         n.group.position.set(pose.x, 0.02, pose.z);
1177:       } else {
1178:         n.group.position.set(0, 0.02, 0.24);
1179:       }
1180:       n.head.visible = false;
1181:       if (n.body) {
1182:         n.body.visible = remain > 0.03;
1183:         n.body.scale.set(0.52 * ns, remain, 1);
1184:         n.body.position.y = remain / 2;
1185:         n.body.material.rotation = n.free ? 0 : -scene.laneScreenAngle(n.lane);
1186:         n.tail.visible = remain > 0.4;
1187:         n.tail.scale.set(0.68 * ns, 0.68 * ns, 1);
1188:         n.tail.position.y = remain;
1189:       }
1190:       if (t > n.tickAt) {
1191:         n.tickAt = t + 0.12;
1192:         stats.score += 24;
1193:         stats.health = Math.min(100, stats.health + 0.06);
1194:       }
1195:     } else {
1196:       n.group.visible = false;
1197:     }
1198:   }
1199: }
