1317: function rankFor(acc, judged) {
1318:   if (judged === 0) return 'F';
1319:   if (acc >= 99.5) return 'S+';
1320:   if (acc >= 98) return 'S';
1321:   if (acc >= 93) return 'A';
1322:   if (acc >= 86) return 'B';
1323:   if (acc >= 76) return 'C';
1324:   return acc < 50 ? 'F' : 'D';
