1327: function comboGraphPath(history, peak) {
1328:   const w = 320, h = 116;
1329:   const pts = history.length ? history : [0, 0, 0, 0];
1330:   const max = Math.max(1, peak, ...pts);
1331:   const step = w / Math.max(1, pts.length - 1);
1332:   let line = '';
1333:   for (let i = 0; i < pts.length; i++) {
1334:     const x = i * step;
1335:     const y = h - (pts[i] / max) * (h - 10);
1336:     line += `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`;
1337:   }
1338:   const fill = `${line}L${w} ${h}L0 ${h}Z`;
1339:   return { line, fill };
1340: }
