1352: function animateNumber(el, to, duration, formatter) {
1353:   const from = 0;
1354:   const start = performance.now();
1355:   const tick = (now) => {
1356:     const p = Math.min(1, (now - start) / duration);
1357:     const eased = 1 - Math.pow(1 - p, 3);
1358:     el.textContent = formatter(Math.round(from + (to - from) * eased));
1359:     if (p < 1) requestAnimationFrame(tick);
1360:   };
1361:   requestAnimationFrame(tick);
1362: }
